create or replace function public.set_matchday_editorial_selection_item(
  p_matchday_id uuid,
  p_position integer,
  p_bank_item_id uuid
)
returns uuid
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_slot_type text;
  v_bank public.matchday_editorial_bank_items%rowtype;
  v_result_id uuid;
  v_source_type text;
  v_source_id text;
begin
  if p_matchday_id is null
    or p_bank_item_id is null
    or p_position not between 1 and 4
  then
    raise exception 'matchday-editorial-selection-invalid-input';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_profile_assignments as assignment_row
    where assignment_row.matchday_id = p_matchday_id
      and assignment_row.profile_key = 'liga_portugal_v1'
  ) then
    raise exception 'matchday-editorial-selection-profile-required';
  end if;

  select bank_row.*
  into v_bank
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = p_bank_item_id
    and bank_row.matchday_id = p_matchday_id
    and bank_row.status = 'active'
  limit 1;

  if not found then
    raise exception 'matchday-editorial-selection-bank-item-not-found';
  end if;

  v_source_type := lower(btrim(coalesce(v_bank.source_type, '')));
  v_source_id := btrim(coalesce(v_bank.source_id, ''));

  if v_source_type not in ('editorial_article', 'editorial_content')
    or v_source_id = ''
    or btrim(coalesce(v_bank.title, '')) = ''
    or btrim(coalesce(v_bank.link_url, '')) = ''
  then
    raise exception 'matchday-editorial-selection-bank-item-invalid';
  end if;

  v_slot_type := 'live_four_news:' || p_position::text;

  delete from public.matchday_live_layout_items as live_row
  where live_row.matchday_id = p_matchday_id
    and live_row.slot_type in (
      'live_four_news:1',
      'live_four_news:2',
      'live_four_news:3',
      'live_four_news:4'
    )
    and live_row.slot_type <> v_slot_type
    and lower(btrim(coalesce(live_row.source_type, ''))) = v_source_type
    and btrim(coalesce(live_row.source_id, '')) = v_source_id;

  insert into public.matchday_live_layout_items (
    matchday_id,
    slot_type,
    article_id,
    source_type,
    source_id,
    label,
    title,
    subtitle,
    image_url,
    link_url,
    updated_at
  ) values (
    p_matchday_id,
    v_slot_type,
    case
      when v_source_type = 'editorial_article'
       and v_source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then v_source_id::uuid
      else null
    end,
    v_source_type,
    v_source_id,
    nullif(btrim(v_bank.label), ''),
    btrim(v_bank.title),
    nullif(btrim(v_bank.subtitle), ''),
    nullif(btrim(v_bank.image_url), ''),
    nullif(btrim(v_bank.link_url), ''),
    pg_catalog.now()
  )
  on conflict (matchday_id, slot_type)
  do update set
    article_id = excluded.article_id,
    source_type = excluded.source_type,
    source_id = excluded.source_id,
    label = excluded.label,
    title = excluded.title,
    subtitle = excluded.subtitle,
    image_url = excluded.image_url,
    link_url = excluded.link_url,
    updated_at = excluded.updated_at
  returning id into v_result_id;

  return v_result_id;
end;
$function$;

