create or replace function public.sync_matchday_editorial_selection_from_bank()
returns trigger
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_source_type text;
  v_source_id text;
begin
  if tg_op not in ('INSERT', 'UPDATE') then
    return new;
  end if;

  v_source_type := lower(btrim(coalesce(new.source_type, '')));
  v_source_id := btrim(coalesce(new.source_id, ''));

  if v_source_type not in ('editorial_article', 'editorial_content')
    or v_source_id = ''
  then
    return new;
  end if;

  update public.matchday_live_layout_items as live_row
  set article_id = case
        when v_source_type = 'editorial_article'
         and v_source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then v_source_id::uuid
        else null
      end,
      label = nullif(btrim(new.label), ''),
      title = nullif(btrim(new.title), ''),
      subtitle = nullif(btrim(new.subtitle), ''),
      image_url = nullif(btrim(new.image_url), ''),
      link_url = nullif(btrim(new.link_url), ''),
      updated_at = pg_catalog.now()
  where live_row.matchday_id = new.matchday_id
    and live_row.slot_type in (
      'live_four_news:1',
      'live_four_news:2',
      'live_four_news:3',
      'live_four_news:4'
    )
    and lower(btrim(coalesce(live_row.source_type, ''))) = v_source_type
    and btrim(coalesce(live_row.source_id, '')) = v_source_id;

  return new;
end;
$function$;

