create or replace function public.apply_historical_composition_workspace_plan_v2(
  p_matchday_id uuid,
  p_composition_id uuid,
  p_operations jsonb,
  p_settings jsonb,
  p_dynamic_zones jsonb
)
returns integer
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_base integer;
  v_dynamic integer;
begin
  v_base :=
    public.apply_historical_composition_workspace_plan(
      p_matchday_id,
      p_composition_id,
      p_operations,
      p_settings
    );

  v_dynamic :=
    public.replace_historical_composition_dynamic_zones(
      p_matchday_id,
      p_composition_id,
      p_dynamic_zones
    );

  return
    coalesce(v_base, 0)
    + coalesce(v_dynamic, 0);
end
$$;

