  public.matchday_editorial_bank_items.classification_key
is
  'Classificação semântica contextual desta participação editorial na jornada. Não é propriedade global do artigo.';


comment on column
  public.matchday_editorial_bank_items.classification_source
is
  'Autoridade da classificação contextual: automatic, continuity_assisted ou manual.';


comment on column
  public.matchday_editorial_bank_items.classified_at
is
  'Instante em que a classificação contextual atual foi materializada.';


-- ============================================================
-- 2. BACKFILL
--
-- Durante o backfill não queremos:
-- - refresh de distribuição;
-- - sincronização artificial da seleção live;
-- - reescrever updated_at da bank.
--
-- Os triggers são repostos dentro da mesma transação.
-- ============================================================

alter table public.matchday_editorial_bank_items
  disable trigger refresh_matchday_editorial_profile_distribution_from_bank;

alter table public.matchday_editorial_bank_items
  disable trigger sync_matchday_editorial_selection_from_bank;

alter table public.matchday_editorial_bank_items
  disable trigger set_matchday_editorial_bank_items_updated_at;


-- 2A. Participações automáticas.
--
-- Usa deliberadamente o classifier público atual ANTES de o contrato
-- público passar a ler a classificação persistida.

with eligible_matchdays as materialized (
  select distinct bank_row.matchday_id
  from public.matchday_editorial_bank_items as bank_row
  where pg_catalog.lower(
          pg_catalog.btrim(coalesce(bank_row.status, ''))
        ) = 'active'
    and pg_catalog.lower(
          pg_catalog.btrim(coalesce(bank_row.source_type, ''))
        ) = 'editorial_article'
    and bank_row.automatic_eligible = true
),
classified as materialized (
  select
    matchday_row.matchday_id,
    classifier_row.source_type,
    classifier_row.source_id,
    classifier_row.classified_zone_key
  from eligible_matchdays as matchday_row
  cross join lateral
    public.matchday_editorial_profile_classification_plan(
      matchday_row.matchday_id
    ) as classifier_row
  join public.editorial_articles as article_row
    on article_row.id::text = pg_catalog.lower(
      pg_catalog.btrim(classifier_row.source_id)
    )
   and article_row.status = 'published'
)
update public.matchday_editorial_bank_items as bank_row
set
  classification_key = classified_row.classified_zone_key,
  classification_source = 'automatic',
  classified_at = pg_catalog.transaction_timestamp()
from classified as classified_row
where bank_row.matchday_id = classified_row.matchday_id
  and pg_catalog.lower(
        pg_catalog.btrim(coalesce(bank_row.source_type, ''))
      ) = pg_catalog.lower(
        pg_catalog.btrim(classified_row.source_type)
      )
  and pg_catalog.lower(
        pg_catalog.btrim(coalesce(bank_row.source_id, ''))
      ) = pg_catalog.lower(
        pg_catalog.btrim(classified_row.source_id)
      )
  and bank_row.classification_key is null
  and bank_row.classification_source is null
  and bank_row.classified_at is null;


-- 2B. Participações herdadas.
--
-- Materializa exatamente a semântica atualmente apresentada pelo
-- continuity classification plan. A partir deste ponto J05 deixa
-- de depender semanticamente de uma leitura viva de J04.

with continuity_matchdays as materialized (
  select distinct bank_row.matchday_id
  from public.matchday_editorial_bank_items as bank_row
  where pg_catalog.lower(
          pg_catalog.btrim(coalesce(bank_row.status, ''))
        ) = 'active'
    and pg_catalog.lower(
          pg_catalog.btrim(coalesce(bank_row.source_type, ''))
        ) = 'editorial_article'
    and bank_row.automatic_eligible = false
    and bank_row.continuity_source_matchday_id is not null
    and bank_row.continuity_source_composition_id is not null
),
classified as materialized (
  select
    matchday_row.matchday_id,
    classifier_row.source_type,
    classifier_row.source_id,
    classifier_row.classified_zone_key
  from continuity_matchdays as matchday_row
  cross join lateral
    public.matchday_editorial_profile_continuity_classification_plan(
      matchday_row.matchday_id
    ) as classifier_row
)
update public.matchday_editorial_bank_items as bank_row
set
  classification_key = classified_row.classified_zone_key,
  classification_source = 'continuity_assisted',
  classified_at = pg_catalog.transaction_timestamp()
from classified as classified_row
where bank_row.matchday_id = classified_row.matchday_id
  and pg_catalog.lower(
        pg_catalog.btrim(coalesce(bank_row.source_type, ''))
      ) = pg_catalog.lower(
        pg_catalog.btrim(classified_row.source_type)
      )
  and pg_catalog.lower(
        pg_catalog.btrim(coalesce(bank_row.source_id, ''))
      ) = pg_catalog.lower(
        pg_catalog.btrim(classified_row.source_id)
      )
  and bank_row.automatic_eligible = false
  and bank_row.classification_key is null
  and bank_row.classification_source is null
  and bank_row.classified_at is null;


-- O conjunto automático publicável atualmente conhecido não pode
-- ficar sem classificação depois da materialização.

do $block$
declare
  v_missing_automatic bigint;
  v_missing_continuity bigint;
begin
  select pg_catalog.count(*)
  into v_missing_automatic
  from public.matchday_editorial_bank_items as bank_row
  join public.editorial_articles as article_row
    on article_row.id::text =
      pg_catalog.lower(
        pg_catalog.btrim(coalesce(bank_row.source_id, ''))
      )
   and article_row.status = 'published'
  where pg_catalog.lower(
          pg_catalog.btrim(coalesce(bank_row.status, ''))
        ) = 'active'
    and pg_catalog.lower(
          pg_catalog.btrim(coalesce(bank_row.source_type, ''))
        ) = 'editorial_article'
    and bank_row.automatic_eligible = true
    and bank_row.classification_key is null;

  if v_missing_automatic <> 0 then
    raise exception
      'contextual-classification-backfill-missing-automatic:%',
      v_missing_automatic;
  end if;

  with continuity_matchdays as materialized (
    select distinct bank_row.matchday_id
    from public.matchday_editorial_bank_items as bank_row
    where pg_catalog.lower(
            pg_catalog.btrim(coalesce(bank_row.status, ''))
          ) = 'active'
      and pg_catalog.lower(
            pg_catalog.btrim(coalesce(bank_row.source_type, ''))
          ) = 'editorial_article'
      and bank_row.automatic_eligible = false
      and bank_row.continuity_source_matchday_id is not null
      and bank_row.continuity_source_composition_id is not null
  ),
  resolved as materialized (
    select
      matchday_row.matchday_id,
      classifier_row.source_type,
      classifier_row.source_id
    from continuity_matchdays as matchday_row
    cross join lateral
      public.matchday_editorial_profile_continuity_classification_plan(
        matchday_row.matchday_id
      ) as classifier_row
  )
  select pg_catalog.count(*)
  into v_missing_continuity
  from resolved as resolved_row
  join public.matchday_editorial_bank_items as bank_row
    on bank_row.matchday_id = resolved_row.matchday_id
   and pg_catalog.lower(
         pg_catalog.btrim(coalesce(bank_row.source_type, ''))
       ) = pg_catalog.lower(
         pg_catalog.btrim(resolved_row.source_type)
       )
   and pg_catalog.lower(
         pg_catalog.btrim(coalesce(bank_row.source_id, ''))
       ) = pg_catalog.lower(
         pg_catalog.btrim(resolved_row.source_id)
       )
  where bank_row.automatic_eligible = false
    and bank_row.classification_key is null;

  if v_missing_continuity <> 0 then
    raise exception
      'contextual-classification-backfill-missing-continuity:%',
      v_missing_continuity;
  end if;
end;
$block$;


alter table public.matchday_editorial_bank_items
  enable trigger set_matchday_editorial_bank_items_updated_at;

alter table public.matchday_editorial_bank_items
  enable trigger sync_matchday_editorial_selection_from_bank;

alter table public.matchday_editorial_bank_items
  enable trigger refresh_matchday_editorial_profile_distribution_from_bank;


-- ============================================================
-- 3. CLASSIFIER DERIVADO INTERNO
--
-- O contrato público passará a ler a classificação persistida.
-- Mantemos separadamente o motor que calcula uma classificação
-- automática quando uma participação nova/alterada precisa dela.
-- ============================================================

create or replace function
public.matchday_editorial_profile_derived_classification_plan_v1(
  p_matchday_id uuid
)
returns table(
  source_type text,
  source_id text,
  classified_zone_key text,
  actuality_order integer
)
language sql
stable
security definer
set search_path = ''
as $function$
  select
    derived_row.source_type,
    derived_row.source_id,
    derived_row.classified_zone_key,
    derived_row.actuality_order
  from public.matchday_editorial_profile_classification_plan_actuality_v1(
    p_matchday_id
  ) as derived_row;
$function$;


revoke all on function
  public.matchday_editorial_profile_derived_classification_plan_v1(uuid)
from public, anon, authenticated, service_role;


-- ============================================================
-- 4. AUTORIZAÇÃO INTERNA PRIVADA
--
-- Uma autorização interna não é estado de sessão controlável pelo caller.
-- Existe apenas para o backend, transação e Bank item exatos durante o
-- UPDATE interno protegido e é removida imediatamente depois do write.
-- ============================================================

create schema jornada_private authorization postgres;

revoke all on schema jornada_private
from public, anon, authenticated, service_role;

alter default privileges in schema jornada_private
  revoke execute on functions from public;

create table
jornada_private.matchday_editorial_bank_classification_authorizations (
  backend_pid integer not null,
  transaction_id xid8 not null,
  bank_item_id uuid not null,
  primary key (backend_pid, transaction_id, bank_item_id)
);

revoke all on table
  jornada_private.matchday_editorial_bank_classification_authorizations
from public, anon, authenticated, service_role;

create function
jornada_private.authorize_matchday_editorial_bank_classification_writes(
  p_bank_item_ids uuid[]
)
returns void
language sql
volatile
security definer
set search_path = ''
as $function$
  insert into
    jornada_private.matchday_editorial_bank_classification_authorizations (
      backend_pid,
      transaction_id,
      bank_item_id
    )
  select
    pg_catalog.pg_backend_pid(),
    pg_catalog.pg_current_xact_id(),
    authorized_id.bank_item_id
  from (
    select distinct bank_item_id
    from pg_catalog.unnest(
      coalesce(p_bank_item_ids, '{}'::uuid[])
    ) as authorized_row(bank_item_id)
    where bank_item_id is not null
  ) as authorized_id
  on conflict (backend_pid, transaction_id, bank_item_id)
  do nothing;
$function$;

create function
jornada_private.revoke_matchday_editorial_bank_classification_writes(
  p_bank_item_ids uuid[]
)
returns void
language sql
volatile
security definer
set search_path = ''
as $function$
  delete from
    jornada_private.matchday_editorial_bank_classification_authorizations
  where backend_pid = pg_catalog.pg_backend_pid()
    and transaction_id = pg_catalog.pg_current_xact_id()
    and bank_item_id = any(
      coalesce(p_bank_item_ids, '{}'::uuid[])
    );
$function$;


-- ============================================================
-- 5. GUARDA UNIVERSAL
-- ============================================================

create or replace function
public.guard_matchday_editorial_bank_contextual_classification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_internal boolean;
  v_old_source_type text;
  v_new_source_type text;
  v_old_source_id text;
  v_new_source_id text;
begin
  v_internal := exists (
    select 1
    from jornada_private.matchday_editorial_bank_classification_authorizations as authorization_row
    where authorization_row.backend_pid = pg_catalog.pg_backend_pid()
      and authorization_row.transaction_id = pg_catalog.pg_current_xact_id()
      and authorization_row.bank_item_id = new.id
  );

  v_new_source_type := pg_catalog.lower(pg_catalog.btrim(coalesce(new.source_type, '')));
  v_new_source_id := pg_catalog.lower(pg_catalog.btrim(coalesce(new.source_id, '')));

  if tg_op = 'INSERT' then
    if v_new_source_type <> 'editorial_article' or not v_internal then
      new.classification_key := null;
      new.classification_source := null;
      new.classified_at := null;
    end if;
    return new;
  end if;

  v_old_source_type := pg_catalog.lower(pg_catalog.btrim(coalesce(old.source_type, '')));
  v_old_source_id := pg_catalog.lower(pg_catalog.btrim(coalesce(old.source_id, '')));

  if v_new_source_type <> 'editorial_article' then
    new.classification_key := null;
    new.classification_source := null;
    new.classified_at := null;
    return new;
  end if;

  if old.id is distinct from new.id
    or old.matchday_id is distinct from new.matchday_id
    or v_old_source_type is distinct from v_new_source_type
    or v_old_source_id is distinct from v_new_source_id
  then
    new.classification_key := null;
    new.classification_source := null;
    new.classified_at := null;
    return new;
  end if;

  if old.classification_source = 'manual' and not v_internal then
    new.classification_key := old.classification_key;
    new.classification_source := old.classification_source;
    new.classified_at := old.classified_at;
    return new;
  end if;

  if not v_internal and (
      old.automatic_eligible is distinct from new.automatic_eligible
      or old.continuity_source_matchday_id is distinct from new.continuity_source_matchday_id
      or old.continuity_source_composition_id is distinct from new.continuity_source_composition_id
    )
  then
    new.classification_key := null;
    new.classification_source := null;
    new.classified_at := null;
    return new;
  end if;

  if not v_internal and (
      new.classification_key is distinct from old.classification_key
      or new.classification_source is distinct from old.classification_source
      or new.classified_at is distinct from old.classified_at
    )
  then
    new.classification_key := old.classification_key;
    new.classification_source := old.classification_source;
    new.classified_at := old.classified_at;
  end if;

  return new;
end;
$function$;

revoke all on function public.guard_matchday_editorial_bank_contextual_classification() from public, anon, authenticated, service_role;

drop trigger if exists guard_matchday_editorial_bank_contextual_classification on public.matchday_editorial_bank_items;

create trigger guard_matchday_editorial_bank_contextual_classification
before insert or update of id, matchday_id, source_type, source_id, automatic_eligible, continuity_source_matchday_id, continuity_source_composition_id, classification_key, classification_source, classified_at
on public.matchday_editorial_bank_items
for each row
execute function public.guard_matchday_editorial_bank_contextual_classification();


-- ============================================================
-- 5. MATERIALIZADOR CENTRAL
-- ============================================================

create function jornada_private.write_matchday_editorial_bank_contextual_classification(
  p_bank_item_id uuid,
  p_classification_key text,
  p_classification_source text
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_bank record;
  v_changed boolean := false;
begin
  if (p_classification_key is null) <> (p_classification_source is null) then
    raise exception 'contextual-classification-incomplete-triplet';
  end if;

  if p_classification_key is not null and p_classification_key not in ('benfica','sporting','fc_porto','other_liga_clubs','outside_liga_other') then
    raise exception 'contextual-classification-invalid-key:%', p_classification_key;
  end if;

  if p_classification_source is not null and p_classification_source not in ('automatic','continuity_assisted','manual') then
    raise exception 'contextual-classification-invalid-source:%', p_classification_source;
  end if;

  select bank_row.* into v_bank
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = p_bank_item_id
  for update;

  if not found then return false; end if;

  if pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.source_type, ''))) <> 'editorial_article'
    and p_classification_key is not null
  then
    raise exception 'contextual-classification-non-article:%', p_bank_item_id;
  end if;

  if v_bank.classification_source = 'manual' and p_classification_source is distinct from 'manual' then
    return false;
  end if;

  if v_bank.classification_source = 'continuity_assisted' and p_classification_source is distinct from 'continuity_assisted' then
    return false;
  end if;

  if v_bank.classification_key is not distinct from p_classification_key
    and v_bank.classification_source is not distinct from p_classification_source
  then
    return false;
  end if;

  perform jornada_private.authorize_matchday_editorial_bank_classification_writes(array[p_bank_item_id]);

  begin
    update public.matchday_editorial_bank_items as bank_row
    set classification_key = p_classification_key,
        classification_source = p_classification_source,
        classified_at = case when p_classification_key is null then null else pg_catalog.statement_timestamp() end
    where bank_row.id = p_bank_item_id;
    v_changed := found;
    perform jornada_private.revoke_matchday_editorial_bank_classification_writes(array[p_bank_item_id]);
  exception when others then
    perform jornada_private.revoke_matchday_editorial_bank_classification_writes(array[p_bank_item_id]);
    raise;
  end;

  return v_changed;
end;
$function$;

create function jornada_private.refresh_matchday_editorial_bank_automatic_classifications(
  p_matchday_ids uuid[] default null,
  p_bank_item_ids uuid[] default null,
  p_source_ids text[] default null,
  p_refresh_distribution boolean default true
)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_source_ids text[];
  v_bank_item_ids uuid[];
  v_changed_matchday_ids uuid[] := '{}'::uuid[];
  v_updated_count integer := 0;
  v_matchday_id uuid;
begin
  if p_source_ids is not null then
    select coalesce(pg_catalog.array_agg(distinct normalized_source.source_id), '{}'::text[])
    into v_source_ids
    from (
      select pg_catalog.lower(pg_catalog.btrim(source_row.source_id)) as source_id
      from pg_catalog.unnest(p_source_ids) as source_row(source_id)
      where nullif(pg_catalog.btrim(source_row.source_id), '') is not null
    ) as normalized_source;
  end if;

  select coalesce(pg_catalog.array_agg(target_row.id order by target_row.id), '{}'::uuid[])
  into v_bank_item_ids
  from (
    select bank_row.id
    from public.matchday_editorial_bank_items as bank_row
    where pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) = 'active'
      and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.source_type, ''))) = 'editorial_article'
      and bank_row.automatic_eligible = true
      and bank_row.classification_source is distinct from 'manual'
      and bank_row.classification_source is distinct from 'continuity_assisted'
      and (p_matchday_ids is null or bank_row.matchday_id = any(p_matchday_ids))
      and (p_bank_item_ids is null or bank_row.id = any(p_bank_item_ids))
      and (p_source_ids is null or pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.source_id, ''))) = any(v_source_ids))
    order by bank_row.id
    for update
  ) as target_row;

  if pg_catalog.cardinality(v_bank_item_ids) = 0 then return 0; end if;

  perform jornada_private.authorize_matchday_editorial_bank_classification_writes(v_bank_item_ids);

  begin
    with targets as materialized (
      select bank_row.id, bank_row.matchday_id,
        pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.source_id, ''))) as source_id
      from public.matchday_editorial_bank_items as bank_row
      where bank_row.id = any(v_bank_item_ids)
        and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) = 'active'
        and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.source_type, ''))) = 'editorial_article'
        and bank_row.automatic_eligible = true
        and bank_row.classification_source is distinct from 'manual'
        and bank_row.classification_source is distinct from 'continuity_assisted'
    ),
    target_matchdays as materialized (
      select distinct target_row.matchday_id from targets as target_row
    ),
    derived_raw as materialized (
      select target_matchday.matchday_id,
        pg_catalog.lower(pg_catalog.btrim(derived_row.source_type)) as source_type,
        pg_catalog.lower(pg_catalog.btrim(derived_row.source_id)) as source_id,
        derived_row.classified_zone_key as classification_key,
        derived_row.actuality_order
      from target_matchdays as target_matchday
      cross join lateral public.matchday_editorial_profile_derived_classification_plan_v1(target_matchday.matchday_id) as derived_row
    ),
    derived as materialized (
      select distinct on (derived_row.matchday_id, derived_row.source_type, derived_row.source_id)
        derived_row.matchday_id, derived_row.source_type, derived_row.source_id, derived_row.classification_key
      from derived_raw as derived_row
      join public.editorial_articles as article_row on article_row.id::text = derived_row.source_id and article_row.status = 'published'
      where derived_row.source_type = 'editorial_article'
      order by derived_row.matchday_id, derived_row.source_type, derived_row.source_id, derived_row.actuality_order nulls last
    ),
    resolved as materialized (
      select target_row.id, target_row.matchday_id, derived_row.classification_key,
        case when derived_row.classification_key is null then null else 'automatic'::text end as classification_source
      from targets as target_row
      left join derived as derived_row
        on derived_row.matchday_id = target_row.matchday_id
       and derived_row.source_type = 'editorial_article'
       and derived_row.source_id = target_row.source_id
    ),
    updated as (
      update public.matchday_editorial_bank_items as bank_row
      set classification_key = resolved_row.classification_key,
          classification_source = resolved_row.classification_source,
          classified_at = case when resolved_row.classification_key is null then null else pg_catalog.statement_timestamp() end
      from resolved as resolved_row
      where bank_row.id = resolved_row.id
        and bank_row.classification_source is distinct from 'manual'
        and bank_row.classification_source is distinct from 'continuity_assisted'
        and (bank_row.classification_key is distinct from resolved_row.classification_key
             or bank_row.classification_source is distinct from resolved_row.classification_source)
      returning bank_row.matchday_id
    )
    select pg_catalog.count(*)::integer,
      coalesce(pg_catalog.array_agg(distinct updated_row.matchday_id), '{}'::uuid[])
    into v_updated_count, v_changed_matchday_ids
    from updated as updated_row;

    perform jornada_private.revoke_matchday_editorial_bank_classification_writes(v_bank_item_ids);
  exception when others then
    perform jornada_private.revoke_matchday_editorial_bank_classification_writes(v_bank_item_ids);
    raise;
  end;

  if p_refresh_distribution then
    foreach v_matchday_id in array v_changed_matchday_ids loop
      if exists (select 1 from public.matchday_editorial_profile_assignments as assignment_row where assignment_row.matchday_id = v_matchday_id) then
        perform public.refresh_matchday_editorial_profile_distribution(v_matchday_id);
      end if;
    end loop;
  end if;

  return v_updated_count;
end;
$function$;

create or replace function public.refresh_matchday_editorial_bank_contextual_classification(p_bank_item_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_bank record;
  v_classification_key text;
  v_classification_source text;
begin
  select bank_row.* into v_bank
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = p_bank_item_id
  for update;

  if not found then return; end if;
  if v_bank.classification_source = 'manual' then return; end if;

  if pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.source_type, ''))) <> 'editorial_article' then
    v_classification_key := null;
    v_classification_source := null;
  elsif pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.status, ''))) <> 'active' then
    return;
  elsif v_bank.automatic_eligible then
    perform jornada_private.refresh_matchday_editorial_bank_automatic_classifications(
      p_bank_item_ids => array[p_bank_item_id],
      p_refresh_distribution => false
    );
    return;
  elsif v_bank.classification_source = 'continuity_assisted' and v_bank.classification_key is not null then
    return;
  elsif v_bank.continuity_source_matchday_id is not null and v_bank.continuity_source_composition_id is not null then
    with recursive matchday_chain as (
      select transition_row.source_matchday_id as lookup_matchday_id, 1 as depth
      from public.matchday_editorial_continuity_transitions as transition_row
      where transition_row.target_matchday_id = v_bank.matchday_id
        and transition_row.source_matchday_id = v_bank.continuity_source_matchday_id
        and transition_row.source_composition_id = v_bank.continuity_source_composition_id
      union all
      select transition_row.source_matchday_id, chain.depth + 1
      from matchday_chain as chain
      join public.matchday_editorial_continuity_transitions as transition_row
        on transition_row.target_matchday_id = chain.lookup_matchday_id
      where chain.depth < 100
    )
    select ancestor_row.classification_key
    into v_classification_key
    from matchday_chain as chain
    join public.matchday_editorial_bank_items as ancestor_row
      on ancestor_row.matchday_id = chain.lookup_matchday_id
     and pg_catalog.lower(pg_catalog.btrim(coalesce(ancestor_row.source_type, ''))) = 'editorial_article'
     and pg_catalog.lower(pg_catalog.btrim(coalesce(ancestor_row.source_id, ''))) = pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.source_id, '')))
    where ancestor_row.classification_key is not null
    order by chain.depth, ancestor_row.created_at, ancestor_row.id
    limit 1;

    if v_classification_key is not null then v_classification_source := 'continuity_assisted'; end if;
  end if;

  if v_classification_key is null then
    if v_bank.classification_key is null and v_bank.classification_source is null and v_bank.classified_at is null then return; end if;
  elsif v_bank.classification_key = v_classification_key
    and v_bank.classification_source = v_classification_source
    and v_bank.classified_at is not null
  then return;
  end if;

  perform jornada_private.write_matchday_editorial_bank_contextual_classification(
    p_bank_item_id,
    v_classification_key,
    v_classification_source
  );
end;
$function$;

