create or replace function public.materialize_matchday_editorial_bank_contextual_classification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_bank_item_ids uuid[];
  v_automatic_bank_item_ids uuid[];
  v_bank_item_id uuid;
begin
  if tg_op = 'INSERT' then
    select coalesce(pg_catalog.array_agg(new_row.id order by new_row.id), '{}'::uuid[]) into v_bank_item_ids from new_rows as new_row;
  else
    with changed_rows as (
      select new_row.id
      from old_rows as old_row
      full join new_rows as new_row on new_row.id = old_row.id
      where new_row.id is not null and (
        old_row.id is null
        or old_row.matchday_id is distinct from new_row.matchday_id
        or old_row.source_type is distinct from new_row.source_type
        or old_row.source_id is distinct from new_row.source_id
        or old_row.status is distinct from new_row.status
        or old_row.automatic_eligible is distinct from new_row.automatic_eligible
        or old_row.continuity_source_matchday_id is distinct from new_row.continuity_source_matchday_id
        or old_row.continuity_source_composition_id is distinct from new_row.continuity_source_composition_id
      )
    )
    select coalesce(pg_catalog.array_agg(changed_row.id order by changed_row.id), '{}'::uuid[]) into v_bank_item_ids from changed_rows as changed_row;
  end if;

  if pg_catalog.cardinality(v_bank_item_ids) = 0 then return null; end if;

  select coalesce(pg_catalog.array_agg(bank_row.id order by bank_row.id), '{}'::uuid[])
  into v_automatic_bank_item_ids
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = any(v_bank_item_ids)
    and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.source_type, ''))) = 'editorial_article'
    and bank_row.automatic_eligible = true
    and bank_row.classification_source is distinct from 'manual'
    and bank_row.classification_source is distinct from 'continuity_assisted';

  perform jornada_private.refresh_matchday_editorial_bank_automatic_classifications(
    p_bank_item_ids => v_automatic_bank_item_ids,
    p_refresh_distribution => false
  );

  for v_bank_item_id in
    select bank_row.id
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.id = any(v_bank_item_ids)
      and not (bank_row.id = any(v_automatic_bank_item_ids))
    order by bank_row.id
  loop
    perform public.refresh_matchday_editorial_bank_contextual_classification(v_bank_item_id);
  end loop;

  return null;
end;
$function$;

revoke all on function public.materialize_matchday_editorial_bank_contextual_classification() from public, anon, authenticated, service_role;

