create or replace function public.refresh_matchday_editorial_profile_distribution_from_bank()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_matchday_ids uuid[];
  v_matchday_id uuid;
begin
  if tg_op = 'UPDATE'
    and not exists (
      select 1 from new_rows as new_row
      where not exists (
        select 1
        from jornada_private.matchday_editorial_bank_classification_authorizations as authorization_row
        where authorization_row.backend_pid = pg_catalog.pg_backend_pid()
          and authorization_row.transaction_id = pg_catalog.pg_current_xact_id()
          and authorization_row.bank_item_id = new_row.id
      )
    )
  then
    return null;
  end if;

  if pg_catalog.current_setting('jornada.thematic_continuity_initialize', true) = 'on' then return null; end if;

  if tg_op = 'DELETE' then
    select coalesce(pg_catalog.array_agg(distinct old_row.matchday_id), '{}'::uuid[]) into v_matchday_ids from old_rows as old_row where old_row.automatic_eligible = true;
  elsif tg_op = 'INSERT' then
    select coalesce(pg_catalog.array_agg(distinct new_row.matchday_id), '{}'::uuid[]) into v_matchday_ids from new_rows as new_row where new_row.automatic_eligible = true;
  else
    with changed_rows as (
      select old_row.matchday_id as old_matchday_id,
             new_row.matchday_id as new_matchday_id,
             old_row.automatic_eligible as old_automatic_eligible,
             new_row.automatic_eligible as new_automatic_eligible
      from old_rows as old_row
      full join new_rows as new_row on new_row.id = old_row.id
      where old_row.id is null or new_row.id is null
        or old_row.matchday_id is distinct from new_row.matchday_id
        or pg_catalog.lower(pg_catalog.btrim(coalesce(old_row.source_type, ''))) is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(new_row.source_type, '')))
        or pg_catalog.lower(pg_catalog.btrim(coalesce(old_row.source_id, ''))) is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(new_row.source_id, '')))
        or pg_catalog.lower(pg_catalog.btrim(coalesce(old_row.status, ''))) is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(new_row.status, '')))
        or old_row.automatic_eligible is distinct from new_row.automatic_eligible
    ), changed_matchdays as (
      select changed_row.old_matchday_id as matchday_id
      from changed_rows as changed_row
      where changed_row.old_automatic_eligible = true and changed_row.old_matchday_id is not null
      union
      select changed_row.new_matchday_id
      from changed_rows as changed_row
      where changed_row.new_automatic_eligible = true and changed_row.new_matchday_id is not null
    )
    select coalesce(pg_catalog.array_agg(changed_matchday.matchday_id), '{}'::uuid[]) into v_matchday_ids from changed_matchdays as changed_matchday;
  end if;

  foreach v_matchday_id in array v_matchday_ids loop
    if exists (select 1 from public.matchday_editorial_profile_assignments as assignment_row where assignment_row.matchday_id = v_matchday_id) then
      perform public.refresh_matchday_editorial_profile_distribution(v_matchday_id);
    end if;
  end loop;
  return null;
end;
$function$;

