create or replace function public.matchday_editorial_profile_classification_plan(p_matchday_id uuid)
returns table(source_type text, source_id text, classified_zone_key text, actuality_order integer)
language sql stable security definer set search_path = '' as $function$
  with classified as materialized (
    select pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) as source_type,
           pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) as source_id,
           bank_row.classification_key as classified_zone_key
    from public.matchday_editorial_bank_items as bank_row
    join public.editorial_articles as article_row
      on article_row.id::text = pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
     and article_row.status = 'published'
    where bank_row.matchday_id = p_matchday_id
      and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
      and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) = 'editorial_article'
      and bank_row.automatic_eligible = true
      and bank_row.classification_key is not null
  ), entered as (
    select classified_row.*,
      (select pg_catalog.min(state_row.created_at)
       from public.matchday_editorial_profile_state_items as state_row
       where state_row.matchday_id = p_matchday_id
         and pg_catalog.lower(pg_catalog.btrim(state_row.source_type)) = classified_row.source_type
         and pg_catalog.lower(pg_catalog.btrim(state_row.source_id)) = classified_row.source_id) as entered_at
    from classified as classified_row
  )
  select entered_row.source_type, entered_row.source_id, entered_row.classified_zone_key,
         pg_catalog.row_number() over (
           order by entered_row.entered_at asc nulls last,
                    entered_row.source_type asc,
                    entered_row.source_id asc
         )::integer as actuality_order
  from entered as entered_row
  order by actuality_order, entered_row.source_type, entered_row.source_id;
$function$;

comment on function public.matchday_editorial_profile_classification_plan(uuid) is
  'Compatibility projection of the persisted contextual classification for active automatic editorial_article participations. classified_zone_key is a legacy output name; authority is matchday_editorial_bank_items.classification_key.';

create or replace function public.matchday_editorial_profile_continuity_classification_plan(p_matchday_id uuid)
returns table(source_type text, source_id text, classified_zone_key text)
language sql stable security definer set search_path = '' as $function$
  select pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) as source_type,
         pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) as source_id,
         bank_row.classification_key as classified_zone_key
  from public.matchday_editorial_bank_items as bank_row
  join public.editorial_articles as article_row
    on article_row.id::text = pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
   and article_row.status = 'published'
  join public.matchday_editorial_continuity_transitions as transition_row
    on transition_row.target_matchday_id = bank_row.matchday_id
   and transition_row.source_matchday_id = bank_row.continuity_source_matchday_id
   and transition_row.source_composition_id = bank_row.continuity_source_composition_id
  where bank_row.matchday_id = p_matchday_id
    and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) = 'editorial_article'
    and bank_row.automatic_eligible = false
    and bank_row.classification_key is not null
  order by pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
           pg_catalog.lower(pg_catalog.btrim(bank_row.source_id));
$function$;

comment on function public.matchday_editorial_profile_continuity_classification_plan(uuid) is
  'Compatibility projection of the classification already materialized on continuity bank participations. It no longer uses an ancestor matchday as live semantic authority.';

create or replace function public.matchday_editorial_profile_reconcile_token_uncached(p_matchday_id uuid, p_profile_key text)
returns table(state_token text)
language sql stable security definer set search_path = '' as $function$
  with classification as materialized (
    select classified_row.*
    from public.matchday_editorial_profile_classification_plan(p_matchday_id) as classified_row
  ), contextual_classification as materialized (
    select bank_row.id as bank_item_id,
           pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) as source_type,
           pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) as source_id,
           bank_row.classification_key,
           bank_row.classification_source
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
      and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) = 'active'
      and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.source_type, ''))) = 'editorial_article'
  )
  select pg_catalog.md5(pg_catalog.jsonb_build_object(
    'assignment', coalesce((select pg_catalog.to_jsonb(assignment_row) from public.matchday_editorial_profile_assignments as assignment_row where assignment_row.matchday_id = p_matchday_id), 'null'::jsonb),
    'classification', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(classified_row) order by classified_row.source_type, classified_row.source_id) from classification as classified_row), '[]'::jsonb),
    'contextual_classification', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(contextual_row) order by contextual_row.source_type, contextual_row.source_id, contextual_row.bank_item_id) from contextual_classification as contextual_row), '[]'::jsonb),
    'automatic_state', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(state_row) order by state_row.source_type, state_row.source_id) from public.matchday_editorial_profile_state_items as state_row where state_row.matchday_id = p_matchday_id and state_row.profile_key = p_profile_key), '[]'::jsonb),
    'articles', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(article_row) order by article_row.id) from public.editorial_articles as article_row where article_row.id = any(array(select case when classified_row.source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then classified_row.source_id::uuid else null end from classification as classified_row))), '[]'::jsonb),
    'overrides', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(override_row) order by override_row.source_type, override_row.source_id) from public.matchday_editorial_profile_manual_overrides as override_row where override_row.matchday_id = p_matchday_id and override_row.profile_key = p_profile_key), '[]'::jsonb),
    'zone_items', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(zone_row) order by zone_row.zone_key, zone_row.sort_order, zone_row.source_id) from public.matchday_editorial_profile_zone_items as zone_row where zone_row.matchday_id = p_matchday_id and zone_row.profile_key = p_profile_key), '[]'::jsonb),
    'control', coalesce((select pg_catalog.to_jsonb(control_row) from public.matchday_editorial_profile_reconcile_control as control_row where control_row.matchday_id = p_matchday_id and control_row.profile_key = p_profile_key), 'null'::jsonb),
    'faixa', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(faixa_row) order by faixa_row.sort_order, faixa_row.id) from public.matchday_horizontal_news as faixa_row where faixa_row.matchday_id = p_matchday_id), '[]'::jsonb)
  )::text) as state_token;
$function$;

