create or replace function public.publish_matchday_reference_composition_with_continuity(
  p_matchday_id uuid,
  p_composition_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_source_season_id uuid;
  v_source_number integer;
  v_next_matchday_id uuid;
  v_published_id uuid;
  v_materialized record;
begin
  if p_matchday_id is null or p_composition_id is null then raise exception 'composition_invalid'; end if;
  select matchday_row.season_id, matchday_row.number into v_source_season_id,v_source_number from public.matchdays as matchday_row where matchday_row.id=p_matchday_id;
  if not found then raise exception 'composition_matchday_not_found'; end if;
  select target_row.id into v_next_matchday_id from public.matchdays as target_row where target_row.season_id=v_source_season_id and target_row.number=v_source_number+1;
  if not found then raise exception 'composition_next_matchday_not_found'; end if;
  perform 1 from public.matchdays as lock_row where lock_row.id in (p_matchday_id,v_next_matchday_id) order by lock_row.id for update;
  if not exists (select 1 from public.matchday_editorial_desk_control as desk_row where desk_row.matchday_id=p_matchday_id and desk_row.is_managed=true) then raise exception 'composition_source_matchday_not_live'; end if;
  if exists (select 1 from public.matchday_reference_compositions as target_composition where target_composition.matchday_id=v_next_matchday_id and target_composition.status='published' and target_composition.is_current=true) then raise exception 'composition_next_matchday_already_published'; end if;
  v_published_id := public.activate_matchday_reference_composition(p_matchday_id,p_composition_id,true);
  select * into v_materialized from jornada_private.materialize_matchday_live_layout_continuity(p_matchday_id,v_next_matchday_id,v_published_id);
  if not coalesce(v_materialized.materialized,false) then raise exception 'composition_continuity_not_materialized'; end if;
  update public.matchday_editorial_desk_control as source_desk set is_managed=false,carryover_source_composition_id=null,carryover_snapshot=null,updated_at=pg_catalog.now() where source_desk.matchday_id=p_matchday_id;
  update public.matchday_editorial_desk_control as target_desk set is_managed=true,carryover_source_composition_id=null,carryover_snapshot=null,updated_at=pg_catalog.now() where target_desk.matchday_id=v_next_matchday_id;
  if not found then raise exception 'composition_next_matchday_control_missing'; end if;
  return pg_catalog.jsonb_build_object('publishedCompositionId',v_published_id,'sourceMatchdayId',p_matchday_id,'nextMatchdayId',v_next_matchday_id,'carryoverApplied',true,'materialized',true,'inheritedBankCount',v_materialized.inherited_bank_count,'inheritedZoneCount',v_materialized.inherited_zone_count,'inheritedPlacementCount',v_materialized.inherited_placement_count,'inheritedLatestCount',v_materialized.inherited_latest_count,'inheritedRoundupCount',v_materialized.inherited_roundup_count);
end;
$function$;

