create function jornada_private.guard_published_reference_composition()
returns trigger
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  if old.status='published' then
    if tg_op='DELETE'
      or new.status<>'published'
      or (pg_catalog.to_jsonb(new)-array['is_current','updated_at']::text[]) is distinct from (pg_catalog.to_jsonb(old)-array['is_current','updated_at']::text[])
    then raise exception 'published-reference-composition-immutable'; end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$;

