  into v_materialized
  from jornada_private.materialize_matchday_live_layout_continuity(
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id
  );

  if not coalesce(v_materialized.materialized, false) then
    raise exception 'matchday-live-continuity-recovery-not-materialized';
  end if;

  update public.matchday_editorial_desk_control as target_desk
  set carryover_source_composition_id = null,
      carryover_snapshot = null,
      updated_at = pg_catalog.now()
  where target_desk.matchday_id = p_target_matchday_id
    and target_desk.is_managed = true;

  v_retired := jornada_private.retire_matchday_live_layout_source(
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id
  );

  if not coalesce((v_retired ->> 'retired')::boolean, false) then
    raise exception 'matchday-live-continuity-recovery-source-not-retired';
  end if;

  return pg_catalog.jsonb_build_object(
    'recovered', true,
    'sourceRetired', true,
    'sourceMatchdayId', p_source_matchday_id,
    'targetMatchdayId', p_target_matchday_id,
    'sourceCompositionId', p_source_composition_id,
    'inheritedBankCount', v_materialized.inherited_bank_count,
    'inheritedZoneCount', v_materialized.inherited_zone_count,
    'inheritedPlacementCount', v_materialized.inherited_placement_count,
    'inheritedLatestCount', v_materialized.inherited_latest_count,
    'inheritedRoundupCount', v_materialized.inherited_roundup_count
  );
end;
$function$;

revoke all on function public.recover_matchday_live_layout_continuity(
  uuid, uuid, uuid
) from public, anon, authenticated;
grant execute on function public.recover_matchday_live_layout_continuity(
  uuid, uuid, uuid
) to service_role;

create temporary table matchday_live_layout_source_retirement_repair (
  source_matchday_id uuid primary key,
  target_matchday_id uuid not null unique,
  source_composition_id uuid not null,
  source_composition_hash text not null,
  source_items_hash text not null,
  source_bank_hash text not null,
  source_zones_hash text not null,
  source_blocks_hash text not null,
  target_placements_hash text not null,
  target_bank_hash text not null,
  target_zones_hash text not null,
  target_blocks_hash text not null,
  target_latest_hash text not null,
  target_roundup_hash text not null,
  target_memory_hash text not null
) on commit drop;

insert into matchday_live_layout_source_retirement_repair (
  source_matchday_id,
  target_matchday_id,
  source_composition_id,
  source_composition_hash,
  source_items_hash,
  source_bank_hash,
  source_zones_hash,
  source_blocks_hash,
  target_placements_hash,
  target_bank_hash,
  target_zones_hash,
  target_blocks_hash,
  target_latest_hash,
  target_roundup_hash,
  target_memory_hash
)
select
  transition_row.source_matchday_id,
  transition_row.target_matchday_id,
  transition_row.source_composition_id,
  pg_catalog.md5(pg_catalog.to_jsonb(composition_row)::text),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(item_row)
      order by item_row.id
    )::text
    from public.matchday_reference_composition_items as item_row
    where item_row.composition_id = transition_row.source_composition_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(bank_row)
      order by bank_row.id
    )::text
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = transition_row.source_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(zone_row)
      order by zone_row.id
    )::text
    from public.matchday_live_layout_zones as zone_row
    where zone_row.matchday_id = transition_row.source_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(block_row)
      order by block_row.id
    )::text
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = transition_row.source_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(placement_row)
      order by placement_row.id
    )::text
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = transition_row.target_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(bank_row)
      order by bank_row.id
    )::text
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = transition_row.target_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(zone_row)
      order by zone_row.id
    )::text
    from public.matchday_live_layout_zones as zone_row
    where zone_row.matchday_id = transition_row.target_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(block_row)
      order by block_row.id
    )::text
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = transition_row.target_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(latest_row)
      order by latest_row.id
    )::text
    from public.matchday_latest_news as latest_row
    where latest_row.matchday_id = transition_row.target_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(roundup_row)
      order by roundup_row.id
    )::text
    from public.matchday_roundup_items as roundup_row
    where roundup_row.matchday_id = transition_row.target_matchday_id
  ), '[]')),
  pg_catalog.md5(coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(memory_row)
      order by memory_row.matchday_id, memory_row.bank_item_id
    )::text
    from public.matchday_live_layout_bank_item_state_memory as memory_row
    where memory_row.matchday_id = transition_row.target_matchday_id
  ), '[]'))
from public.matchday_editorial_continuity_transitions as transition_row
join public.matchdays as source_matchday
  on source_matchday.id = transition_row.source_matchday_id
join public.matchdays as target_matchday
  on target_matchday.id = transition_row.target_matchday_id
join public.matchday_editorial_desk_control as source_desk
  on source_desk.matchday_id = transition_row.source_matchday_id
join public.matchday_editorial_desk_control as target_desk
  on target_desk.matchday_id = transition_row.target_matchday_id
join public.matchday_reference_compositions as composition_row
  on composition_row.id = transition_row.source_composition_id
 and composition_row.matchday_id = transition_row.source_matchday_id
where transition_row.continuity_version = 6
  and source_matchday.season_id = target_matchday.season_id
  and target_matchday.number = source_matchday.number + 1
  and source_desk.is_managed = false
  and target_desk.is_managed = true
  and composition_row.status = 'published'
  and composition_row.is_current = true
  and exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = transition_row.source_matchday_id
  );

do $repair_cardinality$
declare
  v_candidate_count integer;
begin
  select pg_catalog.count(*)::integer
  into v_candidate_count
  from matchday_live_layout_source_retirement_repair;

  if v_candidate_count <> 1 then
    raise exception
      'matchday-live-layout-retirement-repair-candidate-count:%',
      v_candidate_count;
  end if;
end;
$repair_cardinality$;

select jornada_private.retire_matchday_live_layout_source(
  repair_row.source_matchday_id,
  repair_row.target_matchday_id,
  repair_row.source_composition_id
)
from matchday_live_layout_source_retirement_repair as repair_row;

set constraints all immediate;

do $repair_postconditions$
begin
  if exists (
    select 1
    from matchday_live_layout_source_retirement_repair as repair_row
    where exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = repair_row.source_matchday_id
    )
       or exists (
         select 1
         from public.matchday_live_layout_bank_item_state_memory as memory_row
         where memory_row.matchday_id = repair_row.source_matchday_id
       )
       or not exists (
         select 1
         from public.matchday_editorial_desk_control as source_desk
         where source_desk.matchday_id = repair_row.source_matchday_id
           and source_desk.is_managed = false
       )
       or not exists (
         select 1
         from public.matchday_editorial_desk_control as target_desk
         where target_desk.matchday_id = repair_row.target_matchday_id
           and target_desk.is_managed = true
       )
  ) then
    raise exception 'matchday-live-layout-retirement-repair-state-failed';
  end if;

  if exists (
    select 1
    from matchday_live_layout_source_retirement_repair as repair_row
    join public.matchday_reference_compositions as composition_row
      on composition_row.id = repair_row.source_composition_id
    where repair_row.source_composition_hash <>
        pg_catalog.md5(pg_catalog.to_jsonb(composition_row)::text)
      or repair_row.source_items_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(item_row)
          order by item_row.id
        )::text
        from public.matchday_reference_composition_items as item_row
        where item_row.composition_id = repair_row.source_composition_id
      ), '[]'))
      or repair_row.source_bank_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(bank_row)
          order by bank_row.id
        )::text
        from public.matchday_editorial_bank_items as bank_row
        where bank_row.matchday_id = repair_row.source_matchday_id
      ), '[]'))
      or repair_row.source_zones_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(zone_row)
          order by zone_row.id
        )::text
        from public.matchday_live_layout_zones as zone_row
        where zone_row.matchday_id = repair_row.source_matchday_id
      ), '[]'))
      or repair_row.source_blocks_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(block_row)
          order by block_row.id
        )::text
        from public.matchday_live_layout_blocks as block_row
        where block_row.matchday_id = repair_row.source_matchday_id
      ), '[]'))
  ) then
    raise exception 'matchday-live-layout-retirement-repair-history-mutated';
  end if;

  if exists (
    select 1
    from matchday_live_layout_source_retirement_repair as repair_row
    where repair_row.target_placements_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(placement_row)
          order by placement_row.id
        )::text
        from public.matchday_live_layout_placements as placement_row
        where placement_row.matchday_id = repair_row.target_matchday_id
      ), '[]'))
      or repair_row.target_bank_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(bank_row)
          order by bank_row.id
        )::text
        from public.matchday_editorial_bank_items as bank_row
        where bank_row.matchday_id = repair_row.target_matchday_id
      ), '[]'))
      or repair_row.target_zones_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(zone_row)
          order by zone_row.id
        )::text
        from public.matchday_live_layout_zones as zone_row
        where zone_row.matchday_id = repair_row.target_matchday_id
      ), '[]'))
      or repair_row.target_blocks_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(block_row)
          order by block_row.id
        )::text
        from public.matchday_live_layout_blocks as block_row
        where block_row.matchday_id = repair_row.target_matchday_id
      ), '[]'))
      or repair_row.target_latest_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(latest_row)
          order by latest_row.id
        )::text
        from public.matchday_latest_news as latest_row
        where latest_row.matchday_id = repair_row.target_matchday_id
      ), '[]'))
      or repair_row.target_roundup_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(roundup_row)
          order by roundup_row.id
        )::text
        from public.matchday_roundup_items as roundup_row
        where roundup_row.matchday_id = repair_row.target_matchday_id
      ), '[]'))
      or repair_row.target_memory_hash <> pg_catalog.md5(coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(memory_row)
          order by memory_row.matchday_id, memory_row.bank_item_id
        )::text
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = repair_row.target_matchday_id
      ), '[]'))
  ) then
    raise exception 'matchday-live-layout-retirement-repair-target-mutated';
  end if;

  if exists (
    select 1
    from matchday_live_layout_source_retirement_repair as repair_row
    where not exists (
      select 1
      from public.matchday_editorial_continuity_transitions as transition_row
      where transition_row.source_matchday_id = repair_row.source_matchday_id
        and transition_row.target_matchday_id = repair_row.target_matchday_id
        and transition_row.source_composition_id =
          repair_row.source_composition_id
        and transition_row.continuity_version = 6
    )
  ) then
    raise exception 'matchday-live-layout-retirement-repair-transition-lost';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    group by placement_row.matchday_id, placement_row.bank_item_id
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-retirement-repair-duplicate';
  end if;

  if not exists (
    select 1
    from pg_catalog.pg_constraint as constraint_row
    where constraint_row.conrelid =
        'public.matchday_live_layout_placements'::regclass
      and constraint_row.conname =
        'matchday_live_layout_placements_matchday_bank_key'
      and constraint_row.contype = 'u'
      and constraint_row.condeferrable = true
      and constraint_row.condeferred = true
  ) then
    raise exception 'matchday-live-layout-retirement-repair-unique-lost';
  end if;

  if not exists (
    select 1
    from jornada_private.matchday_live_layout_cutover_control as control_row
    where control_row.scope = 'live_layout'
      and control_row.authority_mode = 'authoritative'
  ) then
    raise exception 'matchday-live-layout-retirement-repair-authority-lost';
  end if;

  if exists (
    select 1
    from jornada_private.matchday_live_layout_placement_shadow_sync_queue
  ) then
    raise exception 'matchday-live-layout-retirement-repair-queue-not-empty';
  end if;
end;
$repair_postconditions$;

notify pgrst, 'reload schema';

commit;

drop trigger if exists matchday_reference_compositions_published_immutable on public.matchday_reference_compositions;
drop trigger if exists matchday_reference_composition_items_published_immutable on public.matchday_reference_composition_items;
drop trigger if exists matchday_hierarchical_composition_slots_published_immutable on public.matchday_hierarchical_composition_slots;
drop trigger if exists matchday_historical_composition_zones_published_immutable on public.matchday_historical_composition_zones;
drop trigger if exists matchday_historical_composition_zone_items_published_immutable on public.matchday_historical_composition_zone_items;
drop function if exists jornada_private.guard_published_reference_composition();
drop function if exists jornada_private.guard_published_reference_composition_child();

create function public.reopen_matchday_reference_composition(
  p_matchday_id uuid,
  p_composition_id uuid
)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_source public.matchday_reference_compositions%rowtype;
  v_existing_draft_id uuid;
  v_draft_id uuid := pg_catalog.gen_random_uuid();
  v_target_matchday_id uuid;
  v_now timestamptz := pg_catalog.now();
  v_item public.matchday_reference_composition_items%rowtype;
  v_slot public.matchday_hierarchical_composition_slots%rowtype;
  v_zone public.matchday_historical_composition_zones%rowtype;
  v_zone_item public.matchday_historical_composition_zone_items%rowtype;
  v_draft_zone_id uuid;
begin
  if p_matchday_id is null or p_composition_id is null then
    raise exception 'composition_invalid';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_core_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'composition_matchday_not_found';
  end if;

  perform 1
  from public.matchday_reference_compositions as composition_row
  where composition_row.matchday_id = p_matchday_id
  for update;

  select composition_row.*
  into v_source
  from public.matchday_reference_compositions as composition_row
  where composition_row.id = p_composition_id
    and composition_row.matchday_id = p_matchday_id
    and composition_row.status = 'published'
    and composition_row.is_current = true;

  if not found then
    raise exception 'composition_current_published_not_found';
  end if;

  select transition_row.target_matchday_id
  into v_target_matchday_id
  from public.matchday_editorial_continuity_transitions as transition_row
  join public.matchdays as source_matchday
    on source_matchday.id = transition_row.source_matchday_id
  join public.matchdays as target_matchday
    on target_matchday.id = transition_row.target_matchday_id
   and target_matchday.season_id = source_matchday.season_id
   and target_matchday.number = source_matchday.number + 1
  where transition_row.source_matchday_id = p_matchday_id
    and transition_row.continuity_version = 6
  for key share of transition_row;

  if not found then
    raise exception 'composition_historical_transition_v6_not_found';
  end if;

  if not exists (
    select 1
    from jornada_private.matchday_live_layout_cutover_control as control_row
    where control_row.scope = 'live_layout'
      and control_row.authority_mode = 'authoritative'
  ) then
    raise exception 'composition_historical_authority_not_active';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as source_desk
    where source_desk.matchday_id = p_matchday_id
      and source_desk.is_managed = false
  ) or exists (
    select 1
    from public.matchday_live_layout_placements as source_placement
    where source_placement.matchday_id = p_matchday_id
  ) or exists (
    select 1
    from public.matchday_live_layout_bank_item_state_memory as source_memory
    where source_memory.matchday_id = p_matchday_id
  ) then
    raise exception 'composition_historical_source_not_retired';
  end if;

  select draft_row.id
  into v_existing_draft_id
  from public.matchday_reference_compositions as draft_row
  where draft_row.matchday_id = p_matchday_id
    and draft_row.presentation_mode = v_source.presentation_mode
    and draft_row.status = 'draft'
  order by draft_row.created_at desc, draft_row.id
  limit 1;

  if found then
    return v_existing_draft_id;
  end if;

  insert into public.matchday_reference_compositions (
    id,
    matchday_id,
    status,
    is_current,
    internal_name,
    use_roundup_items,
    created_at,
    updated_at,
    published_at,
    presentation_mode,
    hierarchical_editorial_title,
    hierarchical_editorial_text,
    hierarchical_editorial_author,
    hierarchical_editorial_excerpt,
    hierarchical_headline_title_color,
    hierarchical_zone_1_title,
    hierarchical_zone_2_title,
    hierarchical_block_order,
    hierarchical_editorial_source_type,
    hierarchical_editorial_source_id,
    hierarchical_video_position
  ) values (
    v_draft_id,
    v_source.matchday_id,
    'draft',
    false,
    v_source.internal_name,
    v_source.use_roundup_items,
    v_now,
    v_now,
    null,
    v_source.presentation_mode,
    v_source.hierarchical_editorial_title,
    v_source.hierarchical_editorial_text,
    v_source.hierarchical_editorial_author,
    v_source.hierarchical_editorial_excerpt,
    v_source.hierarchical_headline_title_color,
    v_source.hierarchical_zone_1_title,
    v_source.hierarchical_zone_2_title,
    v_source.hierarchical_block_order,
    v_source.hierarchical_editorial_source_type,
    v_source.hierarchical_editorial_source_id,
    v_source.hierarchical_video_position
  );

  for v_item in
    select item_row.*
    from public.matchday_reference_composition_items as item_row
    where item_row.composition_id = p_composition_id
    order by item_row.id
  loop
    insert into public.matchday_reference_composition_items (
      id,
      composition_id,
      slot_type,
      source_type,
      source_id,
      article_id,
      sort_order,
      title_snapshot,
      subtitle_snapshot,
      image_url_snapshot,
      link_url_snapshot,
      label_snapshot,
      status,
      created_at,
      updated_at,
      label_color_snapshot,
      media_kind_snapshot,
      media_embed_url_snapshot,
      media_video_url_snapshot
    ) values (
      pg_catalog.gen_random_uuid(),
      v_draft_id,
      v_item.slot_type,
      v_item.source_type,
      v_item.source_id,
      v_item.article_id,
      v_item.sort_order,
      v_item.title_snapshot,
      v_item.subtitle_snapshot,
      v_item.image_url_snapshot,
      v_item.link_url_snapshot,
      v_item.label_snapshot,
      v_item.status,
      v_now,
      v_now,
      v_item.label_color_snapshot,
      v_item.media_kind_snapshot,
      v_item.media_embed_url_snapshot,
      v_item.media_video_url_snapshot
    );
  end loop;

  for v_slot in
    select slot_row.*
    from public.matchday_hierarchical_composition_slots as slot_row
    where slot_row.composition_id = p_composition_id
    order by slot_row.id
  loop
    insert into public.matchday_hierarchical_composition_slots (
      id,
      composition_id,
      slot_key,
      bank_item_id,
      source_identity,
      label_snapshot,
      title_snapshot,
      subtitle_snapshot,
      image_url_snapshot,
      link_url_snapshot,
      created_at,
      updated_at,
      media_kind_snapshot,
      media_embed_url_snapshot,
      media_video_url_snapshot
    ) values (
      pg_catalog.gen_random_uuid(),
      v_draft_id,
      v_slot.slot_key,
      v_slot.bank_item_id,
      v_slot.source_identity,
      v_slot.label_snapshot,
      v_slot.title_snapshot,
      v_slot.subtitle_snapshot,
      v_slot.image_url_snapshot,
      v_slot.link_url_snapshot,
      v_now,
      v_now,
      v_slot.media_kind_snapshot,
      v_slot.media_embed_url_snapshot,
      v_slot.media_video_url_snapshot
    );
  end loop;

  for v_zone in
    select zone_row.*
    from public.matchday_historical_composition_zones as zone_row
    where zone_row.composition_id = p_composition_id
    order by zone_row.sort_order, zone_row.id
  loop
    v_draft_zone_id := pg_catalog.gen_random_uuid();

    insert into public.matchday_historical_composition_zones (
      id,
      composition_id,
      sort_order,
      public_title,
      visual_family,
      created_at,
      updated_at
    ) values (
      v_draft_zone_id,
      v_draft_id,
      v_zone.sort_order,
      v_zone.public_title,
      v_zone.visual_family,
      v_now,
      v_now
    );

    for v_zone_item in
      select zone_item_row.*
      from public.matchday_historical_composition_zone_items as zone_item_row
      where zone_item_row.composition_id = p_composition_id
        and zone_item_row.zone_id = v_zone.id
      order by zone_item_row.position, zone_item_row.id
    loop
      insert into public.matchday_historical_composition_zone_items (
        id,
        composition_id,
        zone_id,
        position,
        bank_item_id,
        source_identity,
        label_snapshot,
        title_snapshot,
        subtitle_snapshot,
        image_url_snapshot,
        link_url_snapshot,
        created_at,
        updated_at
      ) values (
        pg_catalog.gen_random_uuid(),
        v_draft_id,
        v_draft_zone_id,
        v_zone_item.position,
        v_zone_item.bank_item_id,
        v_zone_item.source_identity,
        v_zone_item.label_snapshot,
        v_zone_item.title_snapshot,
        v_zone_item.subtitle_snapshot,
        v_zone_item.image_url_snapshot,
        v_zone_item.link_url_snapshot,
        v_now,
        v_now
      );
    end loop;
  end loop;

  return v_draft_id;
end;
$function$;

revoke all on function public.reopen_matchday_reference_composition(uuid, uuid) from public, anon, authenticated;
grant execute on function public.reopen_matchday_reference_composition(uuid, uuid) to service_role;
comment on function public.reopen_matchday_reference_composition(uuid, uuid) is 'Clones the current public historical composition into an independent draft after a valid v6 transition; the public composition and every live surface remain unchanged.';

create function public.publish_matchday_reference_composition(
  p_matchday_id uuid,
  p_composition_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_source_season_id uuid;
  v_source_number integer;
  v_next_matchday_id uuid;
  v_source_is_managed boolean;
  v_transition public.matchday_editorial_continuity_transitions%rowtype;
  v_has_transition boolean := false;
  v_transition_before jsonb;
  v_transition_after jsonb;
  v_published_id uuid;
  v_first_publication jsonb;
begin
  if p_matchday_id is null or p_composition_id is null then
    raise exception 'composition_invalid';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_core_lock();

  select matchday_row.season_id, matchday_row.number
  into v_source_season_id, v_source_number
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id;

  if not found then
    raise exception 'composition_matchday_not_found';
  end if;

  select target_row.id
  into v_next_matchday_id
  from public.matchdays as target_row
  where target_row.season_id = v_source_season_id
    and target_row.number = v_source_number + 1;

  perform 1
  from public.matchdays as lock_row
  where lock_row.id = p_matchday_id
     or lock_row.id = v_next_matchday_id
  order by lock_row.id
  for update;

  select transition_row.*
  into v_transition
  from public.matchday_editorial_continuity_transitions as transition_row
  where transition_row.source_matchday_id = p_matchday_id
  for key share;

  v_has_transition := found;

  select source_desk.is_managed
  into v_source_is_managed
  from public.matchday_editorial_desk_control as source_desk
  where source_desk.matchday_id = p_matchday_id
  for update;

  if not found then
    raise exception 'composition_source_matchday_control_missing';
  end if;

  if v_has_transition then
    if v_transition.continuity_version <> 6
      or v_next_matchday_id is null
      or v_transition.target_matchday_id <> v_next_matchday_id
    then
      raise exception 'composition_historical_transition_v6_invalid';
    end if;

    if v_source_is_managed then
      raise exception 'composition_historical_source_still_live';
    end if;

    if not exists (
      select 1
      from jornada_private.matchday_live_layout_cutover_control as control_row
      where control_row.scope = 'live_layout'
        and control_row.authority_mode = 'authoritative'
    ) then
      raise exception 'composition_historical_authority_not_active';
    end if;

    if exists (
      select 1
      from public.matchday_live_layout_placements as source_placement
      where source_placement.matchday_id = p_matchday_id
    ) or exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory as source_memory
      where source_memory.matchday_id = p_matchday_id
    ) then
      raise exception 'composition_historical_source_not_retired';
    end if;

    v_transition_before := pg_catalog.to_jsonb(v_transition);

    v_published_id := public.activate_matchday_reference_composition(
      p_matchday_id,
      p_composition_id,
      true
    );

    select pg_catalog.to_jsonb(transition_row)
    into v_transition_after
    from public.matchday_editorial_continuity_transitions as transition_row
    where transition_row.source_matchday_id = p_matchday_id;

    if v_transition_after is distinct from v_transition_before then
      raise exception 'composition_historical_transition_changed';
    end if;

    if exists (
      select 1
      from public.matchday_editorial_desk_control as source_desk
      where source_desk.matchday_id = p_matchday_id
        and source_desk.is_managed = true
    ) or exists (
      select 1
      from public.matchday_live_layout_placements as source_placement
      where source_placement.matchday_id = p_matchday_id
    ) or exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory as source_memory
      where source_memory.matchday_id = p_matchday_id
    ) then
      raise exception 'composition_historical_republish_postcondition_failed';
    end if;

    return pg_catalog.jsonb_build_object(
      'publicationKind', 'historical_republish',
      'publishedCompositionId', v_published_id,
      'sourceMatchdayId', p_matchday_id,
      'nextMatchdayId', v_transition.target_matchday_id,
      'carryoverApplied', false,
      'materialized', false,
      'sourceRetired', true,
      'transitionPreserved', true
    );
  end if;

  if not v_source_is_managed then
    raise exception 'composition_first_publication_source_not_live';
  end if;

  v_first_publication := public.publish_matchday_reference_composition_with_continuity(
    p_matchday_id,
    p_composition_id
  );

  return v_first_publication || pg_catalog.jsonb_build_object(
    'publicationKind', 'first_publication'
  );
end;
$function$;

revoke all on function public.publish_matchday_reference_composition(uuid, uuid) from public, anon, authenticated;
grant execute on function public.publish_matchday_reference_composition(uuid, uuid) to service_role;
comment on function public.publish_matchday_reference_composition(uuid, uuid) is 'Dispatches atomically between first live publication with v6 continuity and later historical-only republication certified by the existing v6 transition.';

notify pgrst, 'reload schema';

begin;

-- LOTE 7C2
-- Movement semantics are explicit editorial decisions:
-- same-surface Zone/Abertura/Faixa can swap; cross-surface replacement
-- displaces only the target; Faixa top-entry is continuous and does not
-- displace. This wrapper also preserves the event clocks used by Tracking.

create function public.apply_matchday_editorial_profile_workspace_v12(
  p_matchday_id uuid,
  p_profile_key text,
  p_expected_revision bigint,
  p_expected_state_token text,
  p_overrides jsonb,
  p_zone_items jsonb,
  p_faixa_source_ids jsonb,
  p_opening jsonb,
  p_page_controls jsonb,
  p_selection_bank_item_ids jsonb,
  p_video_module jsonb,
  p_worked_source_ids jsonb,
  p_authoritative_zone_items jsonb,
  p_authoritative_faixa_items jsonb,
  p_displaced_bank_item_ids jsonb,
  p_faixa_arrival_bank_item_ids jsonb,
  p_displaced_arrival_bank_item_ids jsonb
)
returns table (
  revision bigint,
  state_token text,
  applied_override_count integer,
  applied_zone_item_count integer,
  applied_faixa_count integer,
  applied_opening_count integer,
  applied_selection_count integer
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_apply record;
  v_faixa_before jsonb := '[]'::jsonb;
  v_faixa_anchor timestamptz;
  v_displaced_anchor timestamptz;
  v_final_state_token text;
begin
  if p_matchday_id is null
    or p_displaced_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_bank_item_ids) <> 'array'
    or p_faixa_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_faixa_arrival_bank_item_ids) <> 'array'
    or p_displaced_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_arrival_bank_item_ids) <> 'array'
  then
    raise exception
      'matchday-editorial-profile-workspace-v12-invalid-input';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or (raw_row.value #>> '{}')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) or exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or (raw_row.value #>> '{}')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) or exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or (raw_row.value #>> '{}')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-invalid-events';
  end if;

  if (
    select pg_catalog.count(*)
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
  ) <> (
    select pg_catalog.count(distinct pg_catalog.lower(
      pg_catalog.btrim(raw_row.value #>> '{}')
    ))
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
      as raw_row(value)
  ) or (
    select pg_catalog.count(*)
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
  ) <> (
    select pg_catalog.count(distinct pg_catalog.lower(
      pg_catalog.btrim(raw_row.value #>> '{}')
    ))
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
      as raw_row(value)
  ) or (
    select pg_catalog.count(*)
    from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
  ) <> (
    select pg_catalog.count(distinct pg_catalog.lower(
      pg_catalog.btrim(raw_row.value #>> '{}')
    ))
    from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
      as raw_row(value)
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-duplicate-events';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
      as arrival_row(value)
    where not exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
        as displaced_row(value)
      where pg_catalog.lower(pg_catalog.btrim(
              displaced_row.value #>> '{}'
            )) =
            pg_catalog.lower(pg_catalog.btrim(
              arrival_row.value #>> '{}'
            ))
    )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-displaced-event-not-final';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
      as faixa_row(value)
    join pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
      as displaced_row(value)
      on pg_catalog.lower(pg_catalog.btrim(
           faixa_row.value #>> '{}'
         )) =
         pg_catalog.lower(pg_catalog.btrim(
           displaced_row.value #>> '{}'
         ))
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-event-conflict';
  end if;

  perform
    jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  if exists (
    with requested as (
      select pg_catalog.lower(pg_catalog.btrim(
               raw_row.value #>> '{}'
             )) as bank_item_id
      from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
        as raw_row(value)

      union

      select pg_catalog.lower(pg_catalog.btrim(
               raw_row.value #>> '{}'
             ))
      from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
        as raw_row(value)

      union

      select pg_catalog.lower(pg_catalog.btrim(
               raw_row.value #>> '{}'
             ))
      from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
        as raw_row(value)
    )
    select 1
    from requested as requested_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.matchday_id = p_matchday_id
     and bank_row.id::text = requested_row.bank_item_id
     and pg_catalog.lower(
           pg_catalog.btrim(coalesce(bank_row.status, ''))
         ) = 'active'
    where bank_row.id is null
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-event-source-not-active';
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'bank_item_id', placement_row.bank_item_id,
        'created_at', placement_row.created_at
      )
      order by placement_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_faixa_before
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa';

  select *
  into v_apply
  from jornada_private.apply_matchday_editorial_profile_workspace_v11_pre_handoff(
    p_matchday_id,
    p_profile_key,
    p_expected_revision,
    p_expected_state_token,
    p_overrides,
    p_zone_items,
    p_faixa_source_ids,
    p_opening,
    p_page_controls,
    p_selection_bank_item_ids,
    p_video_module,
    p_worked_source_ids,
    p_authoritative_zone_items,
    p_authoritative_faixa_items,
    '[]'::jsonb
  );

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
      as displaced_row(value)
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.matchday_id = p_matchday_id
     and bank_row.id::text = pg_catalog.lower(
       pg_catalog.btrim(displaced_row.value #>> '{}')
     )
    where exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.bank_item_id = bank_row.id
    )
      or exists (
        select 1
        from public.matchday_editorial_profile_manual_overrides
          as override_row
        where override_row.matchday_id = p_matchday_id
          and override_row.profile_key = p_profile_key
          and override_row.placement_target = 'bank'
          and pg_catalog.lower(
                pg_catalog.btrim(override_row.source_type)
              ) = pg_catalog.lower(
                pg_catalog.btrim(bank_row.source_type)
              )
          and pg_catalog.lower(
                pg_catalog.btrim(override_row.source_id)
              ) = pg_catalog.lower(
                pg_catalog.btrim(bank_row.source_id)
              )
      )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-displaced-placement-conflict';
  end if;

  insert into public.matchday_live_layout_bank_item_state_memory
    as memory_row (
      matchday_id,
      bank_item_id,
      memory_kind,
      recorded_at
    )
  select
    p_matchday_id,
    pg_catalog.lower(
      pg_catalog.btrim(displaced_row.value #>> '{}')
    )::uuid,
    'displaced',
    pg_catalog.statement_timestamp()
  from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
    as displaced_row(value)
  on conflict (matchday_id, bank_item_id)
  do update
  set memory_kind = 'displaced',
      recorded_at = coalesce(
        case
          when memory_row.memory_kind = 'displaced'
            then memory_row.recorded_at
        end,
        excluded.recorded_at
      );

  with previous as materialized (
    select
      (raw_row.value ->> 'bank_item_id')::uuid as bank_item_id,
      (raw_row.value ->> 'created_at')::timestamptz as created_at
    from pg_catalog.jsonb_array_elements(v_faixa_before)
      as raw_row(value)
  )
  update public.matchday_live_layout_placements as placement_row
  set created_at = previous.created_at
  from previous
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa'
    and placement_row.bank_item_id = previous.bank_item_id
    and not exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
        as arrival_row(value)
      where pg_catalog.lower(pg_catalog.btrim(
              arrival_row.value #>> '{}'
            )) = placement_row.bank_item_id::text
    );

  v_faixa_anchor := pg_catalog.clock_timestamp();

  with arrivals as materialized (
    select
      pg_catalog.lower(pg_catalog.btrim(
        raw_row.value #>> '{}'
      ))::uuid as bank_item_id,
      raw_row.ordinality
    from pg_catalog.jsonb_array_elements(
      p_faixa_arrival_bank_item_ids
    ) with ordinality as raw_row(value, ordinality)
  )
  update public.matchday_live_layout_placements as placement_row
  set created_at =
      v_faixa_anchor
      - ((arrivals.ordinality - 1) * interval '1 microsecond')
  from arrivals
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa'
    and placement_row.bank_item_id = arrivals.bank_item_id;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
      as arrival_row(value)
    where not exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.placement_type = 'faixa'
        and placement_row.bank_item_id =
          pg_catalog.lower(pg_catalog.btrim(
            arrival_row.value #>> '{}'
          ))::uuid
    )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-faixa-event-not-final';
  end if;

  if exists (
    select 1
    from (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.min(placement_row.slot_position) as min_position,
        pg_catalog.max(placement_row.slot_position) as max_position
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.placement_type = 'faixa'
    ) as faixa_state
    where faixa_state.item_count > 0
      and (
        faixa_state.min_position <> 1
        or faixa_state.max_position <> faixa_state.item_count
      )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-faixa-not-contiguous';
  end if;

  v_displaced_anchor := pg_catalog.clock_timestamp();

  with arrivals as materialized (
    select
      pg_catalog.lower(pg_catalog.btrim(
        raw_row.value #>> '{}'
      ))::uuid as bank_item_id,
      raw_row.ordinality
    from pg_catalog.jsonb_array_elements(
      p_displaced_arrival_bank_item_ids
    ) with ordinality as raw_row(value, ordinality)
  )
  update public.matchday_live_layout_bank_item_state_memory as memory_row
  set memory_kind = 'displaced',
      recorded_at =
        v_displaced_anchor
        - ((arrivals.ordinality - 1) * interval '1 microsecond')
  from arrivals
  where memory_row.matchday_id = p_matchday_id
    and memory_row.bank_item_id = arrivals.bank_item_id;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
      as displaced_row(value)
    where not exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory
        as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.bank_item_id =
          pg_catalog.lower(pg_catalog.btrim(
            displaced_row.value #>> '{}'
          ))::uuid
        and memory_row.memory_kind = 'displaced'
    )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-displaced-memory-incomplete';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_bank_item_state_memory as memory_row
    join public.matchday_live_layout_placements as placement_row
      on placement_row.matchday_id = memory_row.matchday_id
     and placement_row.bank_item_id = memory_row.bank_item_id
    where memory_row.matchday_id = p_matchday_id
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-memory-placement-conflict';
  end if;

  select token_row.state_token
  into v_final_state_token
  from public.matchday_editorial_profile_workspace_token_uncached(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  return query
  select
    v_apply.revision,
    v_final_state_token,
    v_apply.applied_override_count,
    v_apply.applied_zone_item_count,
    v_apply.applied_faixa_count,
    v_apply.applied_opening_count,
    v_apply.applied_selection_count;
end;
$function$;

