  end if;

  if pg_catalog.has_function_privilege(
    'service_role',
    'jornada_private.apply_matchday_live_layout_physical_state_v13_shadow(uuid,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb)',
