    raise exception 'editorial-content-live-snapshot-v15-content-required';
  end if;

  select
    nullif(pg_catalog.btrim(content_row.slug), ''),
    coalesce(
      nullif(pg_catalog.btrim(content_row.label), ''),
      nullif(pg_catalog.btrim(content_row.content_type), ''),
      'Conteudo'
    ),
