    references public.newsroom_editorial_source_packages(id)
    on delete restrict
);

create index newsroom_mesa_output_usage_source_v2
  on public.newsroom_mesa_output_source_usage(dossier_source_id, editorial_article_id);
create index newsroom_mesa_output_usage_newsroom_v2
  on public.newsroom_mesa_output_source_usage(newsroom_article_id, newsroom_snapshot_id);

do $security$
declare v_table text;
begin
  foreach v_table in array array[
    'newsroom_mesa_output_origins',
    'newsroom_mesa_output_publications',
    'newsroom_mesa_output_source_usage'
  ] loop
    execute format('alter table public.%I enable row level security', v_table);
    execute format('alter table public.%I force row level security', v_table);
    execute format('revoke all on public.%I from public,anon,authenticated,service_role', v_table);
    execute format('grant select on public.%I to service_role', v_table);
  end loop;
end;
$security$;

create function public.newsroom_set_mesa_output_origin_v2(
  p_dossier_id uuid,
  p_article_plan_id uuid,
  p_origin_kind text,
  p_origin_dossier_source_id uuid,
  p_material_key text,
  p_material_version_id uuid
)
returns table(origin_action text)
language plpgsql security definer set search_path = '' as $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_existing public.newsroom_mesa_output_origins%rowtype;
  v_source public.newsroom_editorial_dossier_sources%rowtype;
begin
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id = p_dossier_id for update;
  if not found or v_context.workspace_role <> 'technical'
    or v_context.workspace_contract_version <> 2
    or v_context.workspace_state <> 'active' then
    raise exception 'mesa-output-origin-invalid';
  end if;
  perform 1 from public.newsroom_editorial_dossier_article_plans p
    where p.dossier_id=p_dossier_id and p.id=p_article_plan_id
      and p.editorial_article_id is null and p.status<>'cancelled' for update;
  if not found then raise exception 'mesa-output-origin-invalid'; end if;

  if p_origin_kind='source' then
    if p_material_key is not null or p_material_version_id is not null
      or p_origin_dossier_source_id is null then raise exception 'mesa-output-origin-invalid'; end if;
    select * into v_source from public.newsroom_editorial_dossier_sources s
      where s.dossier_id=p_dossier_id and s.id=p_origin_dossier_source_id and s.included;
    if not found or not exists (
      select 1 from jsonb_array_elements(coalesce(v_context.selection_payload->'sources','[]'::jsonb)) r
      where lower(r->>'newsroomArticleId')=v_source.newsroom_article_id::text
        and lower(r->>'newsroomSnapshotId')=v_source.newsroom_snapshot_id::text
    ) then raise exception 'mesa-output-origin-invalid'; end if;
  elsif p_origin_kind='material' then
    if p_origin_dossier_source_id is not null or p_material_key is null or p_material_version_id is null
      or not exists (
        select 1 from jsonb_array_elements(v_context.material_refs) r
        where lower(r->>'key')=lower(p_material_key)
          and lower(r->>'versionId')=p_material_version_id::text
      ) then raise exception 'mesa-output-origin-invalid'; end if;
  else raise exception 'mesa-output-origin-invalid'; end if;

  select * into v_existing from public.newsroom_mesa_output_origins o
    where o.dossier_id=p_dossier_id and o.article_plan_id=p_article_plan_id;
  if found then
    if v_existing.origin_kind is distinct from p_origin_kind
      or v_existing.origin_dossier_source_id is distinct from p_origin_dossier_source_id
      or v_existing.material_key is distinct from lower(p_material_key)
      or v_existing.material_version_id is distinct from p_material_version_id then
      raise exception 'mesa-output-origin-conflict';
    end if;
    return query select 'reused'::text; return;
  end if;
  insert into public.newsroom_mesa_output_origins(
    dossier_id,article_plan_id,origin_kind,origin_dossier_source_id,material_key,material_version_id
  ) values (
    p_dossier_id,p_article_plan_id,p_origin_kind,p_origin_dossier_source_id,lower(p_material_key),p_material_version_id
  );
  return query select 'created'::text;
end;
$function$;
revoke all on function public.newsroom_set_mesa_output_origin_v2(uuid,uuid,text,uuid,text,uuid)
  from public,anon,authenticated,service_role;
grant execute on function public.newsroom_set_mesa_output_origin_v2(uuid,uuid,text,uuid,text,uuid)
  to service_role;

create or replace function public.newsroom_prepare_mesa_materials_v2(
  p_preparation_key uuid,p_theme_id uuid,p_title text,p_source_refs jsonb,p_material_refs jsonb
)
returns table(dossier_id uuid,preparation_action text,source_count integer,published_context_count integer,image_count integer)
language plpgsql security definer set search_path = '' as $function$
declare
  v_payload jsonb; v_existing public.newsroom_mesa_production_contexts%rowtype; v_result record;
  v_ref jsonb; v_version public.newsroom_mesa_material_versions%rowtype;
  v_refs jsonb; v_materials jsonb:='[]'::jsonb; v_context_ids uuid[]:='{}'::uuid[];
begin
  if p_preparation_key is null or nullif(btrim(p_title),'') is null or length(btrim(p_title))>180
    or p_material_refs is null or jsonb_typeof(p_material_refs)<>'array' or jsonb_array_length(p_material_refs)>50 then
    raise exception 'mesa-material-selection-invalid'; end if;
  if exists(select 1 from jsonb_array_elements(p_material_refs) r group by lower(r->>'key') having count(*)>1) then
    raise exception 'mesa-material-selection-invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1',0));
  update public.newsroom_mesa_containment_guard set revision=not revision where singleton;
  if not found then raise exception 'mesa-organization-containment-guard-missing'; end if;
  v_payload:=jsonb_build_object('contractVersion',2,'theme',p_theme_id,'title',btrim(p_title),
    'sources',p_source_refs,'materials',p_material_refs);
  select * into v_existing from public.newsroom_mesa_production_contexts c
    where c.preparation_key=p_preparation_key;
  if found then
    if v_existing.selection_payload is distinct from v_payload
      or v_existing.workspace_contract_version is distinct from 2::smallint
      or v_existing.workspace_state is distinct from 'active' then
      raise exception 'mesa-material-preparation-conflict'; end if;
    return query select v_existing.dossier_id,'reused'::text,jsonb_array_length(v_existing.source_refs),
      (select count(*)::integer from public.newsroom_editorial_dossier_published_contexts pc where pc.dossier_id=v_existing.dossier_id),
      (select count(*)::integer from public.newsroom_editorial_dossier_images i where i.dossier_id=v_existing.dossier_id);
    return;
  end if;
  if exists(select 1 from public.newsroom_editorial_dossiers d where d.preparation_key=p_preparation_key) then
    raise exception 'mesa-material-prepared-before-v2'; end if;
  if p_theme_id is not null then
    perform 1 from public.newsroom_editorial_themes t where t.id=p_theme_id and t.status='open' for update;
    if not found then raise exception 'mesa-organization-theme-unavailable'; end if;
  end if;
  v_refs:=public.newsroom_mesa_normalize_refs_v2(p_source_refs);
  for v_ref in select r from jsonb_array_elements(p_material_refs) r loop
    v_version:=public.newsroom_mesa_capture_material_v2(v_ref);
    v_refs:=v_refs || v_version.source_refs;
    v_context_ids:=v_context_ids || v_version.article_ids;
    v_materials:=v_materials || jsonb_build_array(jsonb_build_object(
      'key',v_version.material_key,'versionId',v_version.id,'sources',v_version.source_refs));
  end loop;
  v_refs:=public.newsroom_mesa_normalize_refs_v2(v_refs);
  v_context_ids:=array(select distinct a from unnest(v_context_ids) a order by a);
  if cardinality(v_context_ids)>20 then raise exception 'mesa-material-context-limit'; end if;
  if exists(select 1 from unnest(v_context_ids) requested(id) where not exists(
    select 1 from public.editorial_articles a where a.id=requested.id and a.status='published')) then
    raise exception 'mesa-material-context-unavailable'; end if;
  if jsonb_array_length(v_refs)<1 or jsonb_array_length(v_refs)>20 then raise exception 'mesa-material-selection-invalid'; end if;
  if exists(select 1 from jsonb_array_elements(v_refs) r where not exists(
    select 1 from public.newsroom_editorial_article_classifications c
      where c.newsroom_article_id=(r->>'newsroomArticleId')::uuid)) then
    raise exception 'mesa-material-classification-required'; end if;
  select * into v_result from public.newsroom_prepare_editorial_dossier_workspace_v1(
    p_preparation_key,btrim(p_title),
    array(select (r->>'newsroomArticleId')::uuid from jsonb_array_elements(v_refs) r),
    array(select (r->>'newsroomSnapshotId')::uuid from jsonb_array_elements(v_refs) r),v_context_ids);
  insert into public.newsroom_mesa_production_contexts(
    dossier_id,theme_id,preparation_key,selection_payload,source_refs,material_refs,
    workspace_role,workspace_contract_version,workspace_state
  ) values (
    v_result.dossier_id,p_theme_id,p_preparation_key,v_payload,v_refs,v_materials,
    'technical',2,'active'
  );
  return query select v_result.dossier_id,v_result.preparation_action,v_result.source_count,
    v_result.published_context_count,v_result.image_count;
end;
$function$;

create function public.newsroom_preview_abandon_mesa_production_v2(p_dossier_id uuid)
returns table(
  dossier_id uuid,
  workspace_state text,
  publication_count integer,
  source_count integer,
  removable_theme_memberships jsonb
)
language sql stable security definer set search_path = '' as $function$
  select c.dossier_id,
    coalesce(c.workspace_state,'active'),
    (
      (select count(*) from public.newsroom_mesa_output_publications p where p.dossier_id=c.dossier_id)
      + (select count(*) from public.newsroom_mesa_publication_events e where e.dossier_id=c.dossier_id)
      + (select count(*) from public.newsroom_editorial_dossier_article_plans p
          join public.editorial_articles a on a.id=p.editorial_article_id and a.status='published'
          where p.dossier_id=c.dossier_id)
    )::integer,
    jsonb_array_length(c.source_refs),
    coalesce((select jsonb_agg(jsonb_build_object(
      'themeId',m.theme_id,'newsroomArticleId',m.newsroom_article_id,'addedAt',m.added_at
    ) order by m.theme_id,m.newsroom_article_id)
    from public.newsroom_editorial_theme_sources m
    where m.theme_id=c.theme_id and m.added_at=c.created_at
      and exists(select 1 from jsonb_array_elements(c.source_refs) r
        where lower(r->>'newsroomArticleId')=m.newsroom_article_id::text)
      and not exists(select 1 from public.newsroom_mesa_theme_materials tm
        join public.newsroom_mesa_version_source_refs vs on vs.version_id=tm.version_id
        where tm.theme_id=m.theme_id and vs.newsroom_article_id=m.newsroom_article_id)
    ),'[]'::jsonb)
  from public.newsroom_mesa_production_contexts c
  where c.dossier_id=p_dossier_id;
$function$;
revoke all on function public.newsroom_preview_abandon_mesa_production_v2(uuid)
  from public,anon,authenticated,service_role;
grant execute on function public.newsroom_preview_abandon_mesa_production_v2(uuid) to service_role;

create function public.newsroom_abandon_mesa_production_v2(p_dossier_id uuid)
returns table(abandonment_action text,restored_theme_membership_count integer)
language plpgsql security definer set search_path = '' as $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_publications integer; v_removed integer:=0; v_snapshot jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-abandon:'||p_dossier_id::text,0));
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id=p_dossier_id for update;
  if not found then raise exception 'mesa-production-not-found'; end if;
  if v_context.workspace_state='consolidated' then raise exception 'mesa-production-already-published'; end if;
  if v_context.workspace_state='abandoned' then return query select 'reused'::text,0; return; end if;
  select publication_count into v_publications
    from public.newsroom_preview_abandon_mesa_production_v2(p_dossier_id);
  if v_publications>0 then raise exception 'mesa-production-already-published'; end if;
  select jsonb_build_object(
    'context',to_jsonb(v_context),
    'themeMemberships',removable_theme_memberships,
    'capturedAt',now()
  ) into v_snapshot from public.newsroom_preview_abandon_mesa_production_v2(p_dossier_id);
  delete from public.newsroom_editorial_theme_sources m
    where m.theme_id=v_context.theme_id and m.added_at=v_context.created_at
      and exists(select 1 from jsonb_array_elements(v_context.source_refs) r
        where lower(r->>'newsroomArticleId')=m.newsroom_article_id::text)
      and not exists(select 1 from public.newsroom_mesa_theme_materials tm
        join public.newsroom_mesa_version_source_refs vs on vs.version_id=tm.version_id
        where tm.theme_id=m.theme_id and vs.newsroom_article_id=m.newsroom_article_id);
  get diagnostics v_removed=row_count;
  update public.newsroom_mesa_production_contexts set
    workspace_role='technical',workspace_state='abandoned',abandoned_at=now(),
    consolidated_at=null,abandonment_snapshot=v_snapshot
    where dossier_id=p_dossier_id;
  return query select 'abandoned'::text,v_removed;
end;
$function$;
revoke all on function public.newsroom_abandon_mesa_production_v2(uuid)
  from public,anon,authenticated,service_role;
grant execute on function public.newsroom_abandon_mesa_production_v2(uuid) to service_role;

create function public.newsroom_mesa_consolidate_publication_v3(p_dossier_id uuid)
returns boolean language plpgsql security definer set search_path = '' as $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_payload jsonb; v_fingerprint text; v_event uuid; v_title text;
  v_group record; v_origin public.newsroom_mesa_material_versions%rowtype;
  v_refs jsonb; v_articles uuid[]; v_version uuid; v_key text;
begin
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id=p_dossier_id for update;
  if not found or v_context.workspace_contract_version<>2 or v_context.workspace_role<>'technical'
    or v_context.workspace_state<>'active' then return false; end if;
  if not exists(select 1 from public.newsroom_editorial_dossier_article_plans p
      where p.dossier_id=p_dossier_id and p.status<>'cancelled') then return false; end if;
  if exists(select 1 from public.newsroom_editorial_dossier_article_plans p
      left join public.newsroom_mesa_output_publications op
        on op.dossier_id=p.dossier_id and op.article_plan_id=p.id
      left join public.editorial_articles a on a.id=op.editorial_article_id
      where p.dossier_id=p_dossier_id and p.status<>'cancelled'
        and (op.article_plan_id is null or a.status<>'published')) then return false; end if;
  select jsonb_build_object(
    'contractVersion',2,
    'outputs',coalesce(jsonb_agg(output_row.payload order by output_row.article_plan_id),'[]'::jsonb)
  ) into v_payload
  from (
    select op.article_plan_id,jsonb_build_object(
      'outputId',op.article_plan_id,'articleId',op.editorial_article_id,
      'sources',coalesce((select jsonb_agg(u.dossier_source_id order by u.dossier_source_id)
        from public.newsroom_mesa_output_source_usage u
        where u.dossier_id=op.dossier_id and u.article_plan_id=op.article_plan_id),'[]'::jsonb),
      'origin',jsonb_build_object('kind',op.origin_kind,'sourceId',op.origin_dossier_source_id,
        'materialKey',op.material_key,'versionId',op.material_version_id)
    ) as payload
    from public.newsroom_mesa_output_publications op
    where op.dossier_id=p_dossier_id
  ) as output_row;
  v_fingerprint:=md5(v_payload::text);
  select e.id into v_event from public.newsroom_mesa_publication_events e
    where e.dossier_id=p_dossier_id and e.fingerprint=v_fingerprint;
  if found then return false; end if;
  insert into public.newsroom_mesa_publication_events(dossier_id,fingerprint,payload)
    values(p_dossier_id,v_fingerprint,v_payload) returning id into v_event;
  select d.title into v_title from public.newsroom_editorial_dossiers d where d.id=p_dossier_id;

  for v_group in
    select op.origin_kind,op.origin_dossier_source_id,op.material_key,op.material_version_id,
      array_agg(distinct op.article_plan_id order by op.article_plan_id) plan_ids
    from public.newsroom_mesa_output_publications op where op.dossier_id=p_dossier_id
    group by op.origin_kind,op.origin_dossier_source_id,op.material_key,op.material_version_id,
      case when op.origin_kind='source' then op.article_plan_id else null end
  loop
    select public.newsroom_mesa_normalize_refs_v2(coalesce(jsonb_agg(jsonb_build_object(
      'newsroomArticleId',u.newsroom_article_id,'newsroomSnapshotId',u.newsroom_snapshot_id)
      order by u.newsroom_article_id),'[]'::jsonb)),
      array_agg(distinct u.editorial_article_id order by u.editorial_article_id)
      into v_refs,v_articles
      from public.newsroom_mesa_output_source_usage u
      where u.dossier_id=p_dossier_id and u.article_plan_id=any(v_group.plan_ids);
    if v_group.origin_kind='material' then
      select * into strict v_origin from public.newsroom_mesa_material_versions v
        where v.material_key=v_group.material_key and v.id=v_group.material_version_id;
      v_refs:=public.newsroom_mesa_normalize_refs_v2(v_origin.source_refs || v_refs);
      v_articles:=array(select distinct a from unnest(v_origin.article_ids || v_articles) a order by a);
      insert into public.newsroom_mesa_material_versions(
        material_key,title,source_refs,article_ids,parent_version_id,production_dossier_id,publication_event_id
      ) values (
        v_origin.material_key,v_origin.title,v_refs,v_articles,v_origin.id,p_dossier_id,v_event
      ) returning id into v_version;
      if v_context.theme_id is not null then
        update public.newsroom_mesa_theme_materials set version_id=v_version
          where theme_id=v_context.theme_id and material_key=v_origin.material_key
            and version_id=v_origin.id;
        if not found then
          insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
            values(v_context.theme_id,v_origin.material_key,v_version) on conflict do nothing;
        end if;
      end if;
    elsif jsonb_array_length(v_refs)>=2 then
      v_key:='output:'||(v_group.plan_ids)[1]::text;
      insert into public.newsroom_mesa_material_versions(
        material_key,title,source_refs,article_ids,production_dossier_id,publication_event_id
      ) values (v_key,v_title,v_refs,v_articles,p_dossier_id,v_event)
      returning id into v_version;
      if v_context.theme_id is not null then
        insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
          values(v_context.theme_id,v_key,v_version) on conflict do nothing;
      end if;
    end if;
  end loop;
  if v_context.theme_id is not null then
    insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
      select v_context.theme_id,op.editorial_article_id
      from public.newsroom_mesa_output_publications op where op.dossier_id=p_dossier_id
      on conflict(theme_id,editorial_article_id) do nothing;
  end if;
  update public.newsroom_mesa_production_contexts set workspace_state='consolidated',consolidated_at=now()
    where dossier_id=p_dossier_id;
  return true;
end;
$function$;
revoke all on function public.newsroom_mesa_consolidate_publication_v3(uuid)
  from public,anon,authenticated,service_role;

create or replace function public.newsroom_mesa_consolidate_publication_v2(p_dossier_id uuid)
returns boolean language sql security definer set search_path = '' as $function$
  select public.newsroom_mesa_consolidate_publication_v3(p_dossier_id);
$function$;

create function public.newsroom_publish_mesa_output_v2(
  p_dossier_id uuid,
  p_output_id uuid,
  p_package_id uuid,
  p_dossier_source_ids uuid[],
  p_article jsonb
)
returns table(editorial_article_id uuid,article_slug text,publication_action text,consolidated boolean)
language plpgsql security definer set search_path = '' as $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_plan public.newsroom_editorial_dossier_article_plans%rowtype;
  v_origin public.newsroom_mesa_output_origins%rowtype;
  v_manifest jsonb; v_existing public.newsroom_mesa_output_publications%rowtype;
  v_article_id uuid; v_slug text; v_label text; v_title text; v_subtitle text; v_body text;
  v_image text; v_author text; v_published_at timestamptz; v_matchday uuid; v_mode text;
  v_previous_slug text;
  v_payload jsonb; v_fingerprint text; v_consolidated boolean; v_now timestamptz:=now();
begin
  if p_dossier_id is null or p_output_id is null or p_package_id is null
    or p_dossier_source_ids is null or cardinality(p_dossier_source_ids)<1
    or cardinality(p_dossier_source_ids)>20 or array_position(p_dossier_source_ids,null) is not null
    or (select count(distinct x) from unnest(p_dossier_source_ids) x)<>cardinality(p_dossier_source_ids)
    or p_article is null or jsonb_typeof(p_article)<>'object' then raise exception 'mesa-publication-input-invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-output:'||p_output_id::text,0));
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id=p_dossier_id for update;
  if not found or v_context.workspace_role<>'technical' or v_context.workspace_contract_version<>2
    or v_context.workspace_state not in ('active','consolidated') then
    raise exception 'mesa-publication-workspace-invalid'; end if;
  select * into v_plan from public.newsroom_editorial_dossier_article_plans p
    where p.dossier_id=p_dossier_id and p.id=p_output_id and p.status<>'cancelled' for update;
  if not found then raise exception 'mesa-publication-output-invalid'; end if;
  select * into strict v_origin from public.newsroom_mesa_output_origins o
    where o.dossier_id=p_dossier_id and o.article_plan_id=p_output_id;
  select p.manifest into v_manifest from public.newsroom_editorial_source_packages p
    where p.id=p_package_id for update;
  if not found or (v_manifest->>'version')::integer<>5 or v_manifest->>'provenanceContract'<>'mesa-v2'
    or not exists(select 1 from jsonb_array_elements(v_manifest->'outputs') o
      where lower(o->>'outputId')=p_output_id::text
        and lower(o->'articlePlan'->>'articlePlanId')=p_output_id::text
        and lower(o->'articlePlan'->>'dossierId')=p_dossier_id::text) then
    raise exception 'mesa-publication-package-invalid'; end if;
  if exists(select 1 from unnest(p_dossier_source_ids) requested(id)
    left join public.newsroom_editorial_dossier_sources s
      on s.id=requested.id and s.dossier_id=p_dossier_id and s.included
    where s.id is null
      or not exists(select 1 from jsonb_array_elements(v_context.source_refs) r
        where lower(r->>'newsroomArticleId')=s.newsroom_article_id::text
          and lower(r->>'newsroomSnapshotId')=s.newsroom_snapshot_id::text)
      or not exists(select 1 from jsonb_array_elements(v_manifest->'entries') e
        where e->>'status'='prepared' and lower(e->>'provenanceSourceId')=requested.id::text
          and lower(e->>'newsroomArticleId')=s.newsroom_article_id::text
          and lower(e->>'newsroomSnapshotId')=s.newsroom_snapshot_id::text)
  ) then raise exception 'mesa-publication-source-invalid'; end if;

  begin v_article_id:=(p_article->>'id')::uuid; exception when others then raise exception 'mesa-publication-article-invalid'; end;
  v_slug:=btrim(coalesce(p_article->>'slug','')); v_label:=btrim(coalesce(p_article->>'label',''));
  v_title:=btrim(coalesce(p_article->>'title','')); v_subtitle:=btrim(coalesce(p_article->>'subtitle',''));
  v_body:=btrim(coalesce(p_article->>'body','')); v_image:=nullif(btrim(coalesce(p_article->>'imageUrl','')),'');
  v_author:=btrim(coalesce(p_article->>'author','')); v_mode:=lower(btrim(coalesce(p_article->>'mode','')));
  begin v_published_at:=(p_article->>'publishedAt')::timestamptz; v_matchday:=(p_article->>'matchdayId')::uuid;
    exception when others then raise exception 'mesa-publication-article-invalid'; end;
  if v_slug='' or v_label='' or v_title='' or v_subtitle='' or v_body='' or v_author=''
    or v_mode not in ('create','update') then raise exception 'mesa-publication-article-invalid'; end if;
  v_payload:=jsonb_build_object(
    'article',jsonb_build_object('id',v_article_id,'slug',v_slug,'label',v_label,'title',v_title,
      'subtitle',v_subtitle,'body',v_body,'imageUrl',v_image,'author',v_author,
      'publishedAt',v_published_at,'matchdayId',v_matchday,'mode',v_mode),
    'sources',(select to_jsonb(array_agg(x order by x)) from unnest(p_dossier_source_ids) x),
    'packageId',p_package_id,'outputId',p_output_id
  );
  v_fingerprint:=md5(v_payload::text);
  select * into v_existing from public.newsroom_mesa_output_publications op
    where op.dossier_id=p_dossier_id and op.article_plan_id=p_output_id;
  if found then
    if v_existing.fingerprint<>v_fingerprint or v_existing.editorial_article_id<>v_article_id
      or not exists(select 1 from public.editorial_articles a where a.id=v_article_id and a.status='published') then
      raise exception 'mesa-publication-provenance-conflict'; end if;
    return query select v_article_id,v_slug,'reused'::text,
      v_context.workspace_state='consolidated'; return;
  end if;
  if v_context.workspace_state='consolidated' then raise exception 'mesa-publication-provenance-conflict'; end if;

  if v_mode='create' then
    if v_plan.destination<>'new' or v_plan.update_target_editorial_article_id is not null or v_image is null
      or exists(select 1 from public.editorial_articles a where a.id=v_article_id or a.slug=v_slug) then
      raise exception 'mesa-publication-article-conflict'; end if;
    insert into public.editorial_articles(
      id,status,scope,author,label,title,subtitle,body,slug,image_url,image_caption,published_at,
      competition_id,season_id,matchday_id,created_at,updated_at
    ) values (
      v_article_id,'published','matchday',v_author,v_label,v_title,v_subtitle,v_body,v_slug,v_image,null,v_published_at,
      null,null,v_matchday,v_now,v_now
    );
  else
    if v_plan.destination<>'update' or v_plan.update_target_editorial_article_id<>v_article_id then
      raise exception 'mesa-publication-update-target-invalid'; end if;
    select a.slug into v_previous_slug from public.editorial_articles a
      where a.id=v_article_id and a.status='published' and a.matchday_id=v_matchday for update;
    if not found or v_previous_slug<>v_slug then raise exception 'mesa-publication-update-target-invalid'; end if;
    update public.editorial_articles a set label=v_label,title=v_title,subtitle=v_subtitle,body=v_body,
      author=v_author,image_url=coalesce(v_image,a.image_url),status='published',scope='matchday',
      competition_id=null,season_id=null,updated_at=v_now
      where a.id=v_article_id and a.status='published' and a.matchday_id=v_matchday and a.slug=v_slug;
    if not found then raise exception 'mesa-publication-update-target-invalid'; end if;
  end if;

  insert into public.newsroom_mesa_output_publications(
    dossier_id,article_plan_id,package_id,editorial_article_id,origin_kind,
    origin_dossier_source_id,material_key,material_version_id,fingerprint,payload
  ) values (
    p_dossier_id,p_output_id,p_package_id,v_article_id,v_origin.origin_kind,
    v_origin.origin_dossier_source_id,v_origin.material_key,v_origin.material_version_id,v_fingerprint,v_payload
  );
  insert into public.newsroom_mesa_output_source_usage(
    dossier_id,article_plan_id,dossier_source_id,newsroom_article_id,newsroom_snapshot_id,
    editorial_article_id,package_id
  ) select p_dossier_id,p_output_id,s.id,s.newsroom_article_id,s.newsroom_snapshot_id,v_article_id,p_package_id
    from public.newsroom_editorial_dossier_sources s
    where s.dossier_id=p_dossier_id and s.id=any(p_dossier_source_ids);
  update public.newsroom_editorial_dossier_article_plans as plan_row
    set editorial_article_id=v_article_id,updated_at=v_now
    where plan_row.dossier_id=p_dossier_id and plan_row.id=p_output_id
      and plan_row.editorial_article_id is null;
  if not found then raise exception 'mesa-publication-output-conflict'; end if;
  v_consolidated:=public.newsroom_mesa_consolidate_publication_v3(p_dossier_id);
  if v_mode='update' then
    perform * from public.sync_editorial_article_live_snapshots_v15(v_article_id,v_previous_slug);
  end if;
  return query select v_article_id,v_slug,case when v_mode='update' then 'updated' else 'created' end,v_consolidated;
end;
$function$;
revoke all on function public.newsroom_publish_mesa_output_v2(uuid,uuid,uuid,uuid[],jsonb)
  from public,anon,authenticated,service_role;
grant execute on function public.newsroom_publish_mesa_output_v2(uuid,uuid,uuid,uuid[],jsonb)
  to service_role;

comment on table public.newsroom_mesa_output_source_usage is
  'Final AI-validated output provenance. Technical Article Plan assignments are not publication proof.';

notify pgrst, 'reload schema';
commit;

-- Source Package manifest v5 for Mesa workspace contract v2.
-- Forward-only: preserves the historical v2/v4 predicate verbatim and adds
-- a closed validator for the v5 structure emitted by the real package writer.
begin;

do $preflight$
begin
  if to_regclass('public.newsroom_editorial_source_packages') is null then
    raise exception 'source-package-manifest-v5-table-missing';
  end if;
  if not exists (
    select 1
    from pg_constraint
    where conrelid = 'public.newsroom_editorial_source_packages'::regclass
      and conname = 'newsroom_editorial_source_packages_manifest_check'
      and contype = 'c'
  ) then
    raise exception 'source-package-manifest-v5-previous-check-missing';
  end if;
end;
$preflight$;

create function public.newsroom_editorial_source_package_manifest_v5_valid(
  p_id uuid,
  p_package_year text,
  p_package_month text,
  p_manifest jsonb
)
returns boolean
language plpgsql
immutable
strict
parallel safe
set search_path = ''
as $function$
declare
  v_entries jsonb;
  v_outputs jsonb;
  v_entry jsonb;
  v_output jsonb;
  v_plan jsonb;
  v_item jsonb;
  v_ordinality bigint;
  v_selected_count integer;
  v_article_count integer;
  v_prepared_count integer;
  v_failed_count integer;
  v_image_count integer;
  v_actual_prepared integer := 0;
  v_actual_failed integer := 0;
  v_position integer;
  v_article_position integer;
  v_output_id text;
  v_dossier_id text;
  v_first_dossier_id text;
  v_provenance_source_id text;
  v_newsroom_snapshot_id text;
  v_published_context_id text;
  v_output_ids text[] := '{}'::text[];
  v_provenance_source_ids text[] := '{}'::text[];
  v_snapshot_ids text[] := '{}'::text[];
  v_published_context_ids text[] := '{}'::text[];
  v_uuid_pattern constant text :=
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  if pg_catalog.jsonb_typeof(p_manifest) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_manifest -> 'version') is distinct from 'number'
    or p_manifest ->> 'version' is distinct from '5'
    or pg_catalog.jsonb_typeof(p_manifest -> 'provenanceContract') is distinct from 'string'
    or p_manifest ->> 'provenanceContract' is distinct from 'mesa-v2'
    or pg_catalog.jsonb_typeof(p_manifest -> 'packageId') is distinct from 'string'
    or p_manifest ->> 'packageId' is distinct from p_id::text
    or pg_catalog.jsonb_typeof(p_manifest -> 'year') is distinct from 'string'
    or p_manifest ->> 'year' is distinct from p_package_year
    or pg_catalog.jsonb_typeof(p_manifest -> 'month') is distinct from 'string'
    or p_manifest ->> 'month' is distinct from p_package_month
    or pg_catalog.jsonb_typeof(p_manifest -> 'createdAt') is distinct from 'string'
    or nullif(pg_catalog.btrim(p_manifest ->> 'createdAt'), '') is null
    or pg_catalog.jsonb_typeof(p_manifest -> 'markdownFileName') is distinct from 'string'
    or nullif(pg_catalog.btrim(p_manifest ->> 'markdownFileName'), '') is null
    or pg_catalog.length(p_manifest ->> 'markdownFileName') > 240
    or p_manifest ->> 'markdownFileName' !~ '\.md$'
    or pg_catalog.jsonb_typeof(p_manifest -> 'genre') is distinct from 'string'
    or p_manifest ->> 'genre' not in ('news', 'brief', 'analysis', 'editorial')
    or pg_catalog.jsonb_typeof(p_manifest -> 'genreLabel') is distinct from 'string'
    or nullif(pg_catalog.btrim(p_manifest ->> 'genreLabel'), '') is null
    or pg_catalog.length(p_manifest ->> 'genreLabel') > 80
    or not (p_manifest ? 'suggestedTitle')
    or not coalesce(
      pg_catalog.jsonb_typeof(p_manifest -> 'suggestedTitle') in ('string', 'null'),
      false
    )
    or (
      pg_catalog.jsonb_typeof(p_manifest -> 'suggestedTitle') = 'string'
      and (
        nullif(pg_catalog.btrim(p_manifest ->> 'suggestedTitle'), '') is null
        or pg_catalog.length(p_manifest ->> 'suggestedTitle') > 240
      )
    )
    or not (p_manifest ? 'additionalInstructions')
    or not coalesce(
      pg_catalog.jsonb_typeof(p_manifest -> 'additionalInstructions') in ('string', 'null'),
      false
    )
    or (
      pg_catalog.jsonb_typeof(p_manifest -> 'additionalInstructions') = 'string'
      and (
        nullif(pg_catalog.btrim(p_manifest ->> 'additionalInstructions'), '') is null
        or pg_catalog.length(p_manifest ->> 'additionalInstructions') > 4000
      )
    )
    or pg_catalog.jsonb_typeof(p_manifest -> 'selectedCount') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p_manifest -> 'articleCount') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p_manifest -> 'preparedCount') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p_manifest -> 'failedCount') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p_manifest -> 'imageCount') is distinct from 'number'
    or not (p_manifest ? 'localDirectory')
    or not coalesce(
      pg_catalog.jsonb_typeof(p_manifest -> 'localDirectory') in ('string', 'null'),
      false
    )
    or (
      pg_catalog.jsonb_typeof(p_manifest -> 'localDirectory') = 'string'
      and nullif(pg_catalog.btrim(p_manifest ->> 'localDirectory'), '') is null
    )
    or pg_catalog.jsonb_typeof(p_manifest -> 'entries') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest -> 'outputs') is distinct from 'array'
  then
    return false;
  end if;

  perform (p_manifest ->> 'createdAt')::timestamptz;
  v_selected_count := (p_manifest ->> 'selectedCount')::integer;
  v_article_count := (p_manifest ->> 'articleCount')::integer;
  v_prepared_count := (p_manifest ->> 'preparedCount')::integer;
  v_failed_count := (p_manifest ->> 'failedCount')::integer;
  v_image_count := (p_manifest ->> 'imageCount')::integer;
  v_entries := p_manifest -> 'entries';
  v_outputs := p_manifest -> 'outputs';

  if pg_catalog.jsonb_array_length(v_entries) not between 1 and 20
    or pg_catalog.jsonb_array_length(v_outputs) not between 1 and 30
    or v_selected_count is distinct from pg_catalog.jsonb_array_length(v_entries)
    or v_article_count is distinct from pg_catalog.jsonb_array_length(v_outputs)
    or v_prepared_count < 0
    or v_failed_count < 0
    or v_image_count < 0
    or v_prepared_count + v_failed_count <> v_selected_count
  then
    return false;
  end if;

  for v_entry, v_ordinality in
    select item.value, item.ordinality
    from pg_catalog.jsonb_array_elements(v_entries)
      with ordinality as item(value, ordinality)
  loop
    if pg_catalog.jsonb_typeof(v_entry) is distinct from 'object'
      or pg_catalog.jsonb_typeof(v_entry -> 'position') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_entry -> 'articlePosition') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_entry -> 'newsroomArticleId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_entry -> 'newsroomSnapshotId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_entry -> 'provenanceSourceId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_entry -> 'status') is distinct from 'string'
      or v_entry ->> 'status' not in ('prepared', 'failed')
      or not (v_entry ? 'sourceCode')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'sourceCode') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'sourceName')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'sourceName') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'title')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'title') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'errorCode')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'errorCode') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'imageUrl')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'imageUrl') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'publishedAt')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'publishedAt') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'publishedAtPrecision')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'publishedAtPrecision') in ('string', 'null'),
        false
      )
      or (
        v_entry ? 'imagePreferred'
        and pg_catalog.jsonb_typeof(v_entry -> 'imagePreferred') is distinct from 'boolean'
      )
    then
      return false;
    end if;

    v_position := (v_entry ->> 'position')::integer;
    v_article_position := (v_entry ->> 'articlePosition')::integer;
    v_provenance_source_id := pg_catalog.lower(v_entry ->> 'provenanceSourceId');
    v_newsroom_snapshot_id := pg_catalog.lower(v_entry ->> 'newsroomSnapshotId');
    if v_position is distinct from v_ordinality::integer
      or v_article_position is distinct from 1
      or pg_catalog.lower(v_entry ->> 'newsroomArticleId') !~ v_uuid_pattern
      or v_newsroom_snapshot_id !~ v_uuid_pattern
      or v_provenance_source_id !~ v_uuid_pattern
      or v_provenance_source_id = any(v_provenance_source_ids)
      or v_newsroom_snapshot_id = any(v_snapshot_ids)
    then
      return false;
    end if;
    v_provenance_source_ids := v_provenance_source_ids || v_provenance_source_id;
    v_snapshot_ids := v_snapshot_ids || v_newsroom_snapshot_id;

    if v_entry ->> 'status' = 'prepared' then
      v_actual_prepared := v_actual_prepared + 1;
      if pg_catalog.jsonb_typeof(v_entry -> 'sourceCode') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_entry ->> 'sourceCode'), '') is null
        or pg_catalog.jsonb_typeof(v_entry -> 'sourceName') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_entry ->> 'sourceName'), '') is null
        or pg_catalog.jsonb_typeof(v_entry -> 'title') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_entry ->> 'title'), '') is null
        or pg_catalog.jsonb_typeof(v_entry -> 'errorCode') is distinct from 'null'
        or not coalesce(
          pg_catalog.jsonb_typeof(v_entry -> 'publishedAtPrecision') in ('null', 'string'),
          false
        )
        or (
          pg_catalog.jsonb_typeof(v_entry -> 'publishedAtPrecision') = 'string'
          and v_entry ->> 'publishedAtPrecision' not in ('date', 'instant')
        )
      then
        return false;
      end if;
    else
      v_actual_failed := v_actual_failed + 1;
      if pg_catalog.jsonb_typeof(v_entry -> 'errorCode') is distinct from 'string'
        or v_entry ->> 'errorCode' not in (
          'source_not_found',
          'snapshot_not_found',
          'snapshot_mismatch',
          'source_body_unavailable'
        )
      then
        return false;
      end if;
    end if;
  end loop;

  if v_actual_prepared is distinct from v_prepared_count
    or v_actual_failed is distinct from v_failed_count
  then
    return false;
  end if;

  for v_output, v_ordinality in
    select item.value, item.ordinality
    from pg_catalog.jsonb_array_elements(v_outputs)
      with ordinality as item(value, ordinality)
  loop
    if pg_catalog.jsonb_typeof(v_output) is distinct from 'object'
      or pg_catalog.jsonb_typeof(v_output -> 'position') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_output -> 'outputId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_output -> 'sourceArticlePosition') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_output -> 'focus') is distinct from 'string'
      or nullif(pg_catalog.btrim(v_output ->> 'focus'), '') is null
      or pg_catalog.length(v_output ->> 'focus') > 240
      or not (v_output ? 'imageNewsroomArticleId')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_output -> 'imageNewsroomArticleId') in ('string', 'null'),
        false
      )
      or pg_catalog.jsonb_typeof(v_output -> 'articlePlan') is distinct from 'object'
    then
      return false;
    end if;

    v_position := (v_output ->> 'position')::integer;
    v_article_position := (v_output ->> 'sourceArticlePosition')::integer;
    v_output_id := pg_catalog.lower(v_output ->> 'outputId');
    v_plan := v_output -> 'articlePlan';
    v_dossier_id := pg_catalog.lower(v_plan ->> 'dossierId');

    if v_position is distinct from v_ordinality::integer
      or v_output_id !~ v_uuid_pattern
      or v_output_id = any(v_output_ids)
      or v_article_position is distinct from 1
      or not exists (
        select 1
        from pg_catalog.jsonb_array_elements(v_entries) as entry_item(value)
        where (entry_item.value ->> 'articlePosition')::integer = v_article_position
      )
      or pg_catalog.jsonb_typeof(v_plan -> 'dossierId') is distinct from 'string'
      or v_dossier_id !~ v_uuid_pattern
      or pg_catalog.jsonb_typeof(v_plan -> 'articlePlanId') is distinct from 'string'
      or pg_catalog.lower(v_plan ->> 'articlePlanId') is distinct from v_output_id
      or pg_catalog.jsonb_typeof(v_plan -> 'workingTitle') is distinct from 'string'
      or nullif(pg_catalog.btrim(v_plan ->> 'workingTitle'), '') is null
      or pg_catalog.length(v_plan ->> 'workingTitle') > 180
      or pg_catalog.jsonb_typeof(v_plan -> 'articleKind') is distinct from 'string'
      or v_plan ->> 'articleKind' not in ('news', 'analysis', 'preview', 'summary')
      or pg_catalog.jsonb_typeof(v_plan -> 'articleKindLabel') is distinct from 'string'
      or nullif(pg_catalog.btrim(v_plan ->> 'articleKindLabel'), '') is null
      or pg_catalog.length(v_plan ->> 'articleKindLabel') > 80
      or pg_catalog.jsonb_typeof(v_plan -> 'lengthMode') is distinct from 'string'
      or v_plan ->> 'lengthMode' not in ('brief', 'standard', 'developed')
      or pg_catalog.jsonb_typeof(v_plan -> 'lengthModeLabel') is distinct from 'string'
      or nullif(pg_catalog.btrim(v_plan ->> 'lengthModeLabel'), '') is null
      or pg_catalog.length(v_plan ->> 'lengthModeLabel') > 80
      or pg_catalog.jsonb_typeof(v_plan -> 'editorialInstructions') is distinct from 'string'
      or pg_catalog.length(v_plan ->> 'editorialInstructions') > 12000
      or pg_catalog.jsonb_typeof(v_plan -> 'destination') is distinct from 'string'
      or v_plan ->> 'destination' not in ('new', 'update')
      or pg_catalog.jsonb_typeof(v_plan -> 'workspaceContractVersion') is distinct from 'number'
      or (v_plan ->> 'workspaceContractVersion')::integer is distinct from 2
      or pg_catalog.jsonb_typeof(v_plan -> 'sourceScope') is distinct from 'string'
      or v_plan ->> 'sourceScope' is distinct from 'workspace'
      or v_plan ? 'origin'
    then
      return false;
    end if;

    if v_first_dossier_id is null then
      v_first_dossier_id := v_dossier_id;
    elsif v_dossier_id is distinct from v_first_dossier_id then
      return false;
    end if;
    v_output_ids := v_output_ids || v_output_id;

    if pg_catalog.jsonb_typeof(v_output -> 'imageNewsroomArticleId') = 'string' then
      if pg_catalog.lower(v_output ->> 'imageNewsroomArticleId') !~ v_uuid_pattern
        or not exists (
          select 1
          from pg_catalog.jsonb_array_elements(v_entries) as entry_item(value)
          where (entry_item.value ->> 'articlePosition')::integer = v_article_position
            and entry_item.value ->> 'status' = 'prepared'
            and pg_catalog.lower(entry_item.value ->> 'newsroomArticleId') =
              pg_catalog.lower(v_output ->> 'imageNewsroomArticleId')
            and pg_catalog.jsonb_typeof(entry_item.value -> 'imageUrl') = 'string'
            and nullif(pg_catalog.btrim(entry_item.value ->> 'imageUrl'), '') is not null
        )
      then
        return false;
      end if;
    end if;

    if v_output ? 'externalImage' then
      if pg_catalog.jsonb_typeof(v_output -> 'externalImage') is distinct from 'object'
        or pg_catalog.jsonb_typeof(v_output -> 'externalImage' -> 'url') is distinct from 'string'
        or (v_output -> 'externalImage' ->> 'url') !~ '^https?://'
        or pg_catalog.jsonb_typeof(v_output -> 'externalImage' -> 'fileName') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_output -> 'externalImage' ->> 'fileName'), '') is null
        or pg_catalog.length(v_output -> 'externalImage' ->> 'fileName') > 240
        or pg_catalog.jsonb_typeof(v_output -> 'imageNewsroomArticleId') is distinct from 'null'
      then
        return false;
      end if;
    end if;

    if (v_output ? 'publishedArticleId') or (v_output ? 'publishedSlug') then
      if pg_catalog.jsonb_typeof(v_output -> 'publishedArticleId') is distinct from 'string'
        or pg_catalog.lower(v_output ->> 'publishedArticleId') !~ v_uuid_pattern
        or pg_catalog.jsonb_typeof(v_output -> 'publishedSlug') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_output ->> 'publishedSlug'), '') is null
      then
        return false;
      end if;
    end if;

    if v_output ? 'usedAt' then
      if pg_catalog.jsonb_typeof(v_output -> 'usedAt') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_output ->> 'usedAt'), '') is null
      then
        return false;
      end if;
      perform (v_output ->> 'usedAt')::timestamptz;
    end if;
  end loop;

  if p_manifest ? 'publishedContextArticleIds' then
    if pg_catalog.jsonb_typeof(p_manifest -> 'publishedContextArticleIds') is distinct from 'array'
      or pg_catalog.jsonb_array_length(p_manifest -> 'publishedContextArticleIds') > 20
    then
      return false;
    end if;
    for v_item in
      select item.value
      from pg_catalog.jsonb_array_elements(p_manifest -> 'publishedContextArticleIds') as item(value)
    loop
      if pg_catalog.jsonb_typeof(v_item) is distinct from 'string' then
        return false;
      end if;
      v_published_context_id := pg_catalog.lower(v_item #>> '{}');
      if v_published_context_id !~ v_uuid_pattern
        or v_published_context_id = any(v_published_context_ids)
      then
        return false;
      end if;
      v_published_context_ids := v_published_context_ids || v_published_context_id;
    end loop;
  end if;

  return true;
exception
  when others then
    return false;
end;
$function$;

revoke all on function public.newsroom_editorial_source_package_manifest_v5_valid(
  uuid,
  text,
  text,
  jsonb
) from public, anon, authenticated, service_role;
grant execute on function public.newsroom_editorial_source_package_manifest_v5_valid(
  uuid,
  text,
  text,
  jsonb
) to service_role;

alter table public.newsroom_editorial_source_packages
  drop constraint newsroom_editorial_source_packages_manifest_check;

alter table public.newsroom_editorial_source_packages
  add constraint newsroom_editorial_source_packages_manifest_check
  check (
    case
      when manifest ->> 'version' = '5' then
        public.newsroom_editorial_source_package_manifest_v5_valid(
          id,
          package_year,
          package_month,
          manifest
        )
      when manifest ->> 'version' in ('2', '4') then
        -- Historical predicate preserved verbatim for manifests v2 and v4.
        jsonb_typeof(manifest) = 'object'
        and manifest ->> 'version' in ('2', '4')
        and manifest ->> 'packageId' = id::text
        and manifest ->> 'year' = package_year
        and manifest ->> 'month' = package_month
        and jsonb_typeof(manifest -> 'entries') = 'array'
        and (
          manifest ->> 'version' = '2'
          or (
            manifest ->> 'version' = '4'
            and jsonb_typeof(manifest -> 'outputs') = 'array'
            and jsonb_array_length(manifest -> 'outputs')
              between 1 and 30
          )
        )
      else false
    end
  );

comment on function public.newsroom_editorial_source_package_manifest_v5_valid(
  uuid,
  text,
  text,
  jsonb
) is
  'Closed structural validator for Mesa v2 Source Package manifests. Historical v2/v4 validation remains in the table constraint.';

notify pgrst, 'reload schema';
commit;

-- Mesa v2 shared source scope.
-- Forward-only: existing exclusive output origins remain untouched and keep
-- source_scope NULL. New Mesa v2 outputs use the frozen workspace as the
-- availability scope; only final AI-validated usage drives consolidation.
begin;

do $preflight$
begin
  if to_regclass('public.newsroom_mesa_production_contexts') is null
    or to_regclass('public.newsroom_mesa_output_origins') is null
    or to_regclass('public.newsroom_mesa_output_publications') is null
    or to_regclass('public.newsroom_mesa_output_source_usage') is null
    or to_regprocedure('public.newsroom_publish_mesa_output_v2(uuid,uuid,uuid,uuid[],jsonb)') is null
    or to_regprocedure('public.newsroom_mesa_consolidate_publication_v3(uuid)') is null then
    raise exception 'mesa-shared-output-scope-preflight-missing';
  end if;
  if exists (
    select 1 from information_schema.columns
    where table_schema='public' and table_name='newsroom_mesa_output_publications'
      and column_name='source_scope'
  ) then
    raise exception 'mesa-shared-output-scope-already-present';
  end if;
end;
$preflight$;

alter table public.newsroom_mesa_output_publications
  add column source_scope text;

alter table public.newsroom_mesa_output_publications
  alter column origin_kind drop not null;

do $drop_old_origin_check$
declare
  v_constraint_name text;
begin
  select c.conname into v_constraint_name
  from pg_constraint c
  where c.conrelid='public.newsroom_mesa_output_publications'::regclass
    and c.contype='c'
    and pg_get_constraintdef(c.oid) like '%origin_kind%'
    and pg_get_constraintdef(c.oid) like '%material_version_id%';
  if v_constraint_name is null then
    raise exception 'mesa-shared-output-origin-check-missing';
  end if;
  execute format(
    'alter table public.newsroom_mesa_output_publications drop constraint %I',
    v_constraint_name
  );
end;
$drop_old_origin_check$;

alter table public.newsroom_mesa_output_publications
  add constraint newsroom_mesa_output_publications_source_scope_check check (
    (
      source_scope is null
      and origin_kind is not null
      and (
        (origin_kind='source' and origin_dossier_source_id is not null
          and material_key is null and material_version_id is null)
        or
        (origin_kind='material' and origin_dossier_source_id is null
          and material_key is not null and material_version_id is not null)
      )
    )
    or
    (
      source_scope is not null
      and source_scope='workspace'
      and origin_kind is null
      and origin_dossier_source_id is null
      and material_key is null
      and material_version_id is null
    )
  );

comment on column public.newsroom_mesa_output_publications.source_scope is
  'NULL preserves the historical exclusive-origin contract. workspace means all frozen dossier sources were available; usage is only newsroom_mesa_output_source_usage.';

create function public.newsroom_set_mesa_shared_outputs_v2(
  p_dossier_id uuid,
  p_article_plan_ids uuid[]
)
returns table(output_count integer,cancelled_count integer)
language plpgsql security definer set search_path='' as $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_cancelled integer:=0;
begin
  if p_dossier_id is null or p_article_plan_ids is null
    or cardinality(p_article_plan_ids) not between 1 and 30
    or array_position(p_article_plan_ids,null) is not null
    or (select count(distinct id) from unnest(p_article_plan_ids) id)<>cardinality(p_article_plan_ids) then
    raise exception 'mesa-shared-outputs-input-invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-shared-outputs:'||p_dossier_id::text,0));
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id=p_dossier_id for update;
  if not found or v_context.workspace_role<>'technical'
    or v_context.workspace_contract_version<>2 or v_context.workspace_state<>'active'
    or exists(select 1 from public.newsroom_mesa_output_publications op where op.dossier_id=p_dossier_id) then
    raise exception 'mesa-shared-outputs-workspace-invalid';
  end if;
  if exists(
    select 1 from unnest(p_article_plan_ids) requested(id)
    left join public.newsroom_editorial_dossier_article_plans p
      on p.dossier_id=p_dossier_id and p.id=requested.id
        and p.status<>'cancelled' and p.editorial_article_id is null
    where p.id is null
  ) then
    raise exception 'mesa-shared-outputs-plan-invalid';
  end if;

  update public.newsroom_editorial_dossier_article_plans p set
    status='cancelled',updated_at=now()
    where p.dossier_id=p_dossier_id and p.status<>'cancelled'
      and p.editorial_article_id is null and not (p.id=any(p_article_plan_ids));
  get diagnostics v_cancelled=row_count;

  update public.newsroom_editorial_dossiers d set
    output_mode=case when cardinality(p_article_plan_ids)=1 then 'single' else 'multiple' end,
    output_count=cardinality(p_article_plan_ids),updated_at=now()
    where d.id=p_dossier_id;
  if not found then raise exception 'mesa-shared-outputs-workspace-invalid'; end if;

  return query select cardinality(p_article_plan_ids),v_cancelled;
end;
$function$;
revoke all on function public.newsroom_set_mesa_shared_outputs_v2(uuid,uuid[])
  from public,anon,authenticated,service_role;
grant execute on function public.newsroom_set_mesa_shared_outputs_v2(uuid,uuid[])
  to service_role;

create function public.newsroom_mesa_consolidate_publication_v4(p_dossier_id uuid)
returns boolean language plpgsql security definer set search_path='' as $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_payload jsonb; v_fingerprint text; v_event uuid; v_title text;
  v_material jsonb; v_origin public.newsroom_mesa_material_versions%rowtype;
  v_group record; v_articles uuid[]; v_version uuid; v_key text;
begin
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id=p_dossier_id for update;
  if not found or v_context.workspace_contract_version<>2 or v_context.workspace_role<>'technical'
    or v_context.workspace_state<>'active' then return false; end if;
  if not exists(select 1 from public.newsroom_editorial_dossier_article_plans p
      where p.dossier_id=p_dossier_id and p.status<>'cancelled') then return false; end if;
  if exists(select 1 from public.newsroom_editorial_dossier_article_plans p
      left join public.newsroom_mesa_output_publications op
        on op.dossier_id=p.dossier_id and op.article_plan_id=p.id
      left join public.editorial_articles a on a.id=op.editorial_article_id
      where p.dossier_id=p_dossier_id and p.status<>'cancelled'
        and (op.article_plan_id is null or a.status<>'published')) then return false; end if;

  if exists(select 1 from public.newsroom_mesa_output_publications op
      where op.dossier_id=p_dossier_id and op.source_scope is null) then
    return public.newsroom_mesa_consolidate_publication_v3(p_dossier_id);
  end if;
  if exists(select 1 from public.newsroom_mesa_output_publications op
      where op.dossier_id=p_dossier_id and op.source_scope<>'workspace') then
    return false;
  end if;

  select jsonb_build_object(
    'contractVersion',2,'sourceScope','workspace',
    'outputs',coalesce(jsonb_agg(output_row.payload order by output_row.article_plan_id),'[]'::jsonb)
  ) into v_payload
  from (
    select op.article_plan_id,jsonb_build_object(
      'outputId',op.article_plan_id,'articleId',op.editorial_article_id,
      'sources',coalesce((select jsonb_agg(jsonb_build_object(
        'dossierSourceId',u.dossier_source_id,
        'newsroomArticleId',u.newsroom_article_id,
        'newsroomSnapshotId',u.newsroom_snapshot_id
      ) order by u.dossier_source_id)
        from public.newsroom_mesa_output_source_usage u
        where u.dossier_id=op.dossier_id and u.article_plan_id=op.article_plan_id),'[]'::jsonb)
    ) payload
    from public.newsroom_mesa_output_publications op
    where op.dossier_id=p_dossier_id
  ) output_row;
  v_fingerprint:=md5(v_payload::text);
  select e.id into v_event from public.newsroom_mesa_publication_events e
    where e.dossier_id=p_dossier_id and e.fingerprint=v_fingerprint;
  if found then return false; end if;
  insert into public.newsroom_mesa_publication_events(dossier_id,fingerprint,payload)
    values(p_dossier_id,v_fingerprint,v_payload) returning id into v_event;
  select d.title into v_title from public.newsroom_editorial_dossiers d where d.id=p_dossier_id;

  for v_material in
    select value from jsonb_array_elements(coalesce(v_context.material_refs,'[]'::jsonb))
  loop
    if jsonb_typeof(v_material->'sources')<>'array'
      or nullif(v_material->>'key','') is null or nullif(v_material->>'versionId','') is null then
      raise exception 'mesa-publication-workspace-invalid';
    end if;
    select array_agg(distinct u.editorial_article_id order by u.editorial_article_id)
      into v_articles
      from public.newsroom_mesa_output_source_usage u
      where u.dossier_id=p_dossier_id and exists(
        select 1 from jsonb_array_elements(v_material->'sources') r
        where lower(r->>'newsroomArticleId')=u.newsroom_article_id::text
          and lower(r->>'newsroomSnapshotId')=u.newsroom_snapshot_id::text
      );
    if coalesce(cardinality(v_articles),0)=0 then continue; end if;
    select * into strict v_origin from public.newsroom_mesa_material_versions mv
      where mv.material_key=lower(v_material->>'key')
        and mv.id=(v_material->>'versionId')::uuid;
    v_articles:=array(select distinct article_id
      from unnest(v_origin.article_ids||v_articles) article_id order by article_id);
    if v_articles=v_origin.article_ids then continue; end if;
    insert into public.newsroom_mesa_material_versions(
      material_key,title,source_refs,article_ids,parent_version_id,production_dossier_id,publication_event_id
    ) values (
      v_origin.material_key,v_origin.title,v_origin.source_refs,v_articles,v_origin.id,p_dossier_id,v_event
    ) returning id into v_version;
    if v_context.theme_id is not null then
      update public.newsroom_mesa_theme_materials set version_id=v_version
        where theme_id=v_context.theme_id and material_key=v_origin.material_key
          and version_id=v_origin.id;
      if not found then insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
        values(v_context.theme_id,v_origin.material_key,v_version) on conflict do nothing; end if;
    end if;
  end loop;

  for v_group in
    select array_agg(distinct u.dossier_source_id order by u.dossier_source_id) source_ids,
      array_agg(distinct u.editorial_article_id order by u.editorial_article_id) article_ids,
      min(u.article_plan_id::text) plan_key
    from public.newsroom_mesa_output_source_usage u
    where u.dossier_id=p_dossier_id
      and not exists(
        select 1 from jsonb_array_elements(coalesce(v_context.material_refs,'[]'::jsonb)) mr
        where exists(select 1 from jsonb_array_elements(mr->'sources') r
          where lower(r->>'newsroomArticleId')=u.newsroom_article_id::text
            and lower(r->>'newsroomSnapshotId')=u.newsroom_snapshot_id::text)
      )
    group by u.article_plan_id
  loop
    if coalesce(cardinality(v_group.source_ids),0)<2 then continue; end if;
    v_key:='output:'||v_group.plan_key;
    insert into public.newsroom_mesa_material_versions(
      material_key,title,source_refs,article_ids,production_dossier_id,publication_event_id
    ) select v_key,v_title,
      public.newsroom_mesa_normalize_refs_v2(jsonb_agg(jsonb_build_object(
        'newsroomArticleId',u.newsroom_article_id,'newsroomSnapshotId',u.newsroom_snapshot_id)
        order by u.newsroom_article_id)),
      v_group.article_ids,p_dossier_id,v_event
      from public.newsroom_mesa_output_source_usage u
      where u.dossier_id=p_dossier_id and u.dossier_source_id=any(v_group.source_ids)
    returning id into v_version;
    if v_context.theme_id is not null then
      insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
        values(v_context.theme_id,v_key,v_version) on conflict do nothing;
    end if;
  end loop;

  if v_context.theme_id is not null then
    insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
      select v_context.theme_id,op.editorial_article_id
      from public.newsroom_mesa_output_publications op where op.dossier_id=p_dossier_id
      on conflict(theme_id,editorial_article_id) do nothing;
  end if;
  update public.newsroom_mesa_production_contexts set
    workspace_state='consolidated',consolidated_at=now()
    where dossier_id=p_dossier_id;
  return true;
end;
$function$;
revoke all on function public.newsroom_mesa_consolidate_publication_v4(uuid)
  from public,anon,authenticated,service_role;

create or replace function public.newsroom_mesa_consolidate_publication_v2(p_dossier_id uuid)
returns boolean language sql security definer set search_path='' as $function$
  select public.newsroom_mesa_consolidate_publication_v4(p_dossier_id);
$function$;

create or replace function public.newsroom_publish_mesa_output_v2(
  p_dossier_id uuid,p_output_id uuid,p_package_id uuid,
  p_dossier_source_ids uuid[],p_article jsonb
)
returns table(editorial_article_id uuid,article_slug text,publication_action text,consolidated boolean)
language plpgsql security definer set search_path='' as $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_plan public.newsroom_editorial_dossier_article_plans%rowtype;
  v_manifest jsonb; v_existing public.newsroom_mesa_output_publications%rowtype;
  v_article_id uuid; v_slug text; v_label text; v_title text; v_subtitle text; v_body text;
  v_image text; v_author text; v_published_at timestamptz; v_matchday uuid; v_mode text;
  v_previous_slug text;
  v_payload jsonb; v_fingerprint text; v_consolidated boolean; v_now timestamptz:=now();
begin
  if p_dossier_id is null or p_output_id is null or p_package_id is null
    or p_dossier_source_ids is null or cardinality(p_dossier_source_ids)<1
    or cardinality(p_dossier_source_ids)>20 or array_position(p_dossier_source_ids,null) is not null
    or (select count(distinct x) from unnest(p_dossier_source_ids) x)<>cardinality(p_dossier_source_ids)
    or p_article is null or jsonb_typeof(p_article)<>'object' then
    raise exception 'mesa-publication-input-invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-output:'||p_output_id::text,0));
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id=p_dossier_id for update;
  if not found or v_context.workspace_role<>'technical' or v_context.workspace_contract_version<>2
    or v_context.workspace_state not in ('active','consolidated') then
    raise exception 'mesa-publication-workspace-invalid'; end if;
  select * into v_plan from public.newsroom_editorial_dossier_article_plans p
    where p.dossier_id=p_dossier_id and p.id=p_output_id and p.status<>'cancelled' for update;
  if not found then raise exception 'mesa-publication-output-invalid'; end if;
  select p.manifest into v_manifest from public.newsroom_editorial_source_packages p
    where p.id=p_package_id for update;
  if not found or (v_manifest->>'version')::integer<>5
    or v_manifest->>'provenanceContract'<>'mesa-v2'
    or not exists(select 1 from jsonb_array_elements(v_manifest->'outputs') o
      where lower(o->>'outputId')=p_output_id::text
        and lower(o->'articlePlan'->>'articlePlanId')=p_output_id::text
        and lower(o->'articlePlan'->>'dossierId')=p_dossier_id::text
        and o->'articlePlan'->>'sourceScope'='workspace'
        and not (o->'articlePlan' ? 'origin')) then
    raise exception 'mesa-publication-package-invalid'; end if;
  if exists(select 1 from unnest(p_dossier_source_ids) requested(id)
    left join public.newsroom_editorial_dossier_sources s
      on s.id=requested.id and s.dossier_id=p_dossier_id and s.included
    where s.id is null
      or not exists(select 1 from jsonb_array_elements(v_context.source_refs) r
        where lower(r->>'newsroomArticleId')=s.newsroom_article_id::text
          and lower(r->>'newsroomSnapshotId')=s.newsroom_snapshot_id::text)
      or not exists(select 1 from jsonb_array_elements(v_manifest->'entries') e
        where e->>'status'='prepared' and lower(e->>'provenanceSourceId')=requested.id::text
          and lower(e->>'newsroomArticleId')=s.newsroom_article_id::text
          and lower(e->>'newsroomSnapshotId')=s.newsroom_snapshot_id::text)
  ) then raise exception 'mesa-publication-source-invalid'; end if;

  begin v_article_id:=(p_article->>'id')::uuid;
    exception when others then raise exception 'mesa-publication-article-invalid'; end;
  v_slug:=btrim(coalesce(p_article->>'slug','')); v_label:=btrim(coalesce(p_article->>'label',''));
  v_title:=btrim(coalesce(p_article->>'title','')); v_subtitle:=btrim(coalesce(p_article->>'subtitle',''));
  v_body:=btrim(coalesce(p_article->>'body','')); v_image:=nullif(btrim(coalesce(p_article->>'imageUrl','')),'');
  v_author:=btrim(coalesce(p_article->>'author','')); v_mode:=lower(btrim(coalesce(p_article->>'mode','')));
  begin v_published_at:=(p_article->>'publishedAt')::timestamptz; v_matchday:=(p_article->>'matchdayId')::uuid;
    exception when others then raise exception 'mesa-publication-article-invalid'; end;
  if v_slug='' or v_label='' or v_title='' or v_subtitle='' or v_body='' or v_author=''
    or v_mode not in ('create','update') then raise exception 'mesa-publication-article-invalid'; end if;
  v_payload:=jsonb_build_object(
    'article',jsonb_build_object('id',v_article_id,'slug',v_slug,'label',v_label,'title',v_title,
      'subtitle',v_subtitle,'body',v_body,'imageUrl',v_image,'author',v_author,
      'publishedAt',v_published_at,'matchdayId',v_matchday,'mode',v_mode),
    'sources',(select to_jsonb(array_agg(x order by x)) from unnest(p_dossier_source_ids) x),
    'packageId',p_package_id,'outputId',p_output_id,'sourceScope','workspace'
  );
  v_fingerprint:=md5(v_payload::text);
  select * into v_existing from public.newsroom_mesa_output_publications op
    where op.dossier_id=p_dossier_id and op.article_plan_id=p_output_id;
  if found then
    if v_existing.fingerprint<>v_fingerprint or v_existing.editorial_article_id<>v_article_id
      or v_existing.source_scope is distinct from 'workspace'
      or not exists(select 1 from public.editorial_articles a where a.id=v_article_id and a.status='published') then
      raise exception 'mesa-publication-provenance-conflict'; end if;
    return query select v_article_id,v_slug,'reused'::text,
      v_context.workspace_state='consolidated'; return;
  end if;
  if v_context.workspace_state='consolidated' then raise exception 'mesa-publication-provenance-conflict'; end if;

  if v_mode='create' then
    if v_plan.destination<>'new' or v_plan.update_target_editorial_article_id is not null or v_image is null
      or exists(select 1 from public.editorial_articles a where a.id=v_article_id or a.slug=v_slug) then
      raise exception 'mesa-publication-article-conflict'; end if;
    insert into public.editorial_articles(
      id,status,scope,author,label,title,subtitle,body,slug,image_url,image_caption,published_at,
      competition_id,season_id,matchday_id,created_at,updated_at
    ) values (
      v_article_id,'published','matchday',v_author,v_label,v_title,v_subtitle,v_body,v_slug,v_image,null,v_published_at,
      null,null,v_matchday,v_now,v_now
    );
  else
    if v_plan.destination<>'update' or v_plan.update_target_editorial_article_id<>v_article_id then
      raise exception 'mesa-publication-update-target-invalid'; end if;
    select a.slug into v_previous_slug from public.editorial_articles a
      where a.id=v_article_id and a.status='published' and a.matchday_id=v_matchday for update;
    if not found or v_previous_slug<>v_slug then raise exception 'mesa-publication-update-target-invalid'; end if;
    update public.editorial_articles a set label=v_label,title=v_title,subtitle=v_subtitle,body=v_body,
      author=v_author,image_url=coalesce(v_image,a.image_url),status='published',scope='matchday',
      competition_id=null,season_id=null,updated_at=v_now
      where a.id=v_article_id and a.status='published' and a.matchday_id=v_matchday and a.slug=v_slug;
    if not found then raise exception 'mesa-publication-update-target-invalid'; end if;
  end if;

  insert into public.newsroom_mesa_output_publications(
    dossier_id,article_plan_id,package_id,editorial_article_id,source_scope,
    origin_kind,origin_dossier_source_id,material_key,material_version_id,fingerprint,payload
  ) values (
    p_dossier_id,p_output_id,p_package_id,v_article_id,'workspace',
    null,null,null,null,v_fingerprint,v_payload
  );
  insert into public.newsroom_mesa_output_source_usage(
    dossier_id,article_plan_id,dossier_source_id,newsroom_article_id,newsroom_snapshot_id,
    editorial_article_id,package_id
  ) select p_dossier_id,p_output_id,s.id,s.newsroom_article_id,s.newsroom_snapshot_id,v_article_id,p_package_id
    from public.newsroom_editorial_dossier_sources s
    where s.dossier_id=p_dossier_id and s.id=any(p_dossier_source_ids);
  update public.newsroom_editorial_dossier_article_plans p set
    editorial_article_id=v_article_id,updated_at=v_now
    where p.dossier_id=p_dossier_id and p.id=p_output_id and p.editorial_article_id is null;
  if not found then raise exception 'mesa-publication-output-conflict'; end if;
  v_consolidated:=public.newsroom_mesa_consolidate_publication_v4(p_dossier_id);
  if v_mode='update' then
    perform * from public.sync_editorial_article_live_snapshots_v15(v_article_id,v_previous_slug);
  end if;
  return query select v_article_id,v_slug,
    case when v_mode='update' then 'updated' else 'created' end,v_consolidated;
end;
$function$;
revoke all on function public.newsroom_publish_mesa_output_v2(uuid,uuid,uuid,uuid[],jsonb)
  from public,anon,authenticated,service_role;
grant execute on function public.newsroom_publish_mesa_output_v2(uuid,uuid,uuid,uuid[],jsonb)
  to service_role;

notify pgrst,'reload schema';
commit;

begin;

create or replace function public.apply_matchday_agenda_tv_sync_v2(
  p_matchday_id uuid,
  p_rows jsonb
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_expected_count integer;
  v_received_count integer;
  v_updated_count integer;
begin
  if p_matchday_id is null then
    raise exception 'agenda-tv-v2-missing-matchday';
  end if;

  if jsonb_typeof(p_rows) is distinct from 'array' then
    raise exception 'agenda-tv-v2-invalid-payload';
  end if;

  select count(*)
  into v_expected_count
  from public.matches
  where matchday_id = p_matchday_id;

  if v_expected_count = 0 then
    raise exception 'agenda-tv-v2-empty-matchday';
  end if;

  v_received_count := jsonb_array_length(p_rows);

  if v_received_count <> v_expected_count then
    raise exception 'agenda-tv-v2-incomplete-matchday';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      item ? 'preserve'
      and jsonb_typeof(item -> 'preserve') is distinct from 'boolean'
  ) then
    raise exception 'agenda-tv-v2-invalid-preserve';
  end if;

  if exists (
    select 1
    from (
      select
        (item ->> 'match_id')::uuid as match_id,
        count(*) as occurrences
      from jsonb_array_elements(p_rows) as item
      group by 1
    ) as duplicated
    where duplicated.occurrences <> 1
  ) then
    raise exception 'agenda-tv-v2-duplicate-match';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      nullif(item ->> 'match_id', '') is null
      or (
        not coalesce((item ->> 'preserve')::boolean, false)
        and (
          nullif(item ->> 'scheduled_date', '') is null
          or nullif(item ->> 'kickoff_at', '') is null
        )
      )
  ) then
    raise exception 'agenda-tv-v2-incomplete-row';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where not exists (
      select 1
      from public.matches as m
      where
        m.id = (item ->> 'match_id')::uuid
        and m.matchday_id = p_matchday_id
    )
  ) then
    raise exception 'agenda-tv-v2-match-outside-matchday';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      not coalesce((item ->> 'preserve')::boolean, false)
      and nullif(item ->> 'broadcast_channel_id', '') is not null
      and not exists (
        select 1
        from public.broadcast_channels as channel
        where
          channel.id =
            (item ->> 'broadcast_channel_id')::uuid
      )
  ) then
    raise exception 'agenda-tv-v2-channel-not-found';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      not coalesce((item ->> 'preserve')::boolean, false)
      and (
        (
          (item ->> 'kickoff_at')::timestamptz
          at time zone 'Europe/Lisbon'
        )::date
      )
      is distinct from
      (item ->> 'scheduled_date')::date
  ) then
    raise exception 'agenda-tv-v2-date-kickoff-mismatch';
  end if;

  if exists (
    with requested as (
      select
        (item ->> 'match_id')::uuid as match_id,
        nullif(
          item ->> 'expected_scheduled_date',
          ''
        )::date as expected_scheduled_date,
        nullif(
          item ->> 'expected_kickoff_at',
          ''
        )::timestamptz as expected_kickoff_at,
        nullif(
          item ->> 'expected_broadcast_channel_id',
          ''
        )::uuid as expected_broadcast_channel_id
      from jsonb_array_elements(p_rows) as item
    )
    select 1
    from requested
    join public.matches as m
      on m.id = requested.match_id
    where
      m.scheduled_date
        is distinct from
        requested.expected_scheduled_date
      or m.kickoff_at
        is distinct from
        requested.expected_kickoff_at
      or m.broadcast_channel_id
        is distinct from
        requested.expected_broadcast_channel_id
  ) then
    raise exception 'agenda-tv-v2-stale-state';
  end if;

  with requested as (
    select
      (item ->> 'match_id')::uuid as match_id,
      coalesce(
        (item ->> 'preserve')::boolean,
        false
      ) as preserve,
      nullif(
        item ->> 'scheduled_date',
        ''
      )::date as scheduled_date,
      nullif(
        item ->> 'kickoff_at',
        ''
      )::timestamptz as kickoff_at,
      nullif(
        item ->> 'broadcast_channel_id',
        ''
      )::uuid as broadcast_channel_id
    from jsonb_array_elements(p_rows) as item
  )
  update public.matches as m
  set
    scheduled_date = requested.scheduled_date,
    kickoff_at = requested.kickoff_at,
    broadcast_channel_id = case
      when requested.broadcast_channel_id is null
        then m.broadcast_channel_id
      else requested.broadcast_channel_id
    end
  from requested
  where
    m.id = requested.match_id
    and m.matchday_id = p_matchday_id
    and not requested.preserve
    and (
      m.scheduled_date
        is distinct from
        requested.scheduled_date
      or m.kickoff_at
        is distinct from
        requested.kickoff_at
      or (
        requested.broadcast_channel_id is not null
        and m.broadcast_channel_id
          is distinct from
          requested.broadcast_channel_id
      )
    );

  get diagnostics v_updated_count = row_count;

  return v_updated_count;
end;
$$;

