-- Normalize before idempotency checks; this also makes array order irrelevant.
-- No identifiers or UPDATE targets supplied in a plan are trusted by the writer.
create function public.newsroom_mesa_normalize_intent_v1(p_request jsonb)
returns jsonb language plpgsql immutable set search_path = '' as $function$
declare
  v_item jsonb; v_themes jsonb := '[]'; v_sources jsonb := '[]';
  v_uuid constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  if jsonb_typeof(p_request) is distinct from 'object'
    or not (p_request ?& array['version','preparationKey','title','themes','sources'])
    or p_request - array['version','preparationKey','title','themes','sources'] <> '{}'
    or p_request -> 'version' is distinct from '1'::jsonb
    or jsonb_typeof(p_request -> 'preparationKey') is distinct from 'string'
    or lower(p_request ->> 'preparationKey') !~ v_uuid
    or jsonb_typeof(p_request -> 'title') is distinct from 'string'
    or length(btrim(p_request ->> 'title')) not between 1 and 180
    or jsonb_typeof(p_request -> 'themes') is distinct from 'array'
    or jsonb_typeof(p_request -> 'sources') is distinct from 'array'
  then raise exception 'mesa-intent-input-invalid'; end if;
  if jsonb_array_length(p_request -> 'themes') > 20
    or jsonb_array_length(p_request -> 'sources') > 200
  then raise exception 'mesa-intent-input-invalid'; end if;
  for v_item in select value from jsonb_array_elements(p_request -> 'themes') loop
    if jsonb_typeof(v_item) is distinct from 'object'
      or not (v_item ?& array['themeId','action'])
      or jsonb_typeof(v_item -> 'themeId') is distinct from 'string'
      or lower(v_item ->> 'themeId') !~ v_uuid
      or coalesce(v_item ->> 'action','') not in ('defer','prepare')
    then raise exception 'mesa-intent-theme-invalid'; end if;
    if v_item ->> 'action' = 'defer' then
      if v_item - array['themeId','action'] <> '{}' then raise exception 'mesa-intent-theme-invalid'; end if;
    else
      if not (v_item ?& array['reviewPublished','newArticleCount'])
        or v_item - array['themeId','action','reviewPublished','newArticleCount'] <> '{}'
        or jsonb_typeof(v_item -> 'reviewPublished') is distinct from 'boolean'
        or jsonb_typeof(v_item -> 'newArticleCount') is distinct from 'number'
        or (v_item ->> 'newArticleCount') !~ '^[0-9]+$'
      then raise exception 'mesa-intent-theme-invalid'; end if;
      if (v_item ->> 'newArticleCount')::numeric not between 0 and 30 then raise exception 'mesa-intent-theme-invalid'; end if;
    end if;
    v_themes := v_themes || jsonb_build_array(v_item || jsonb_build_object('themeId',lower(v_item ->> 'themeId')));
  end loop;
  for v_item in select value from jsonb_array_elements(p_request -> 'sources') loop
    if jsonb_typeof(v_item) is distinct from 'object'
      or not (v_item ?& array['sourceId','destination'])
      or jsonb_typeof(v_item -> 'sourceId') is distinct from 'string'
      or lower(v_item ->> 'sourceId') !~ v_uuid
      or coalesce(v_item ->> 'destination','') not in ('defer','independent','theme')
    then raise exception 'mesa-intent-source-invalid'; end if;
    case v_item ->> 'destination'
    when 'defer' then
      if v_item - array['sourceId','destination'] <> '{}' then raise exception 'mesa-intent-source-invalid'; end if;
    when 'theme' then
      if not (v_item ? 'themeId') or v_item - array['sourceId','destination','themeId'] <> '{}'
        or jsonb_typeof(v_item -> 'themeId') is distinct from 'string' or lower(v_item ->> 'themeId') !~ v_uuid
      then raise exception 'mesa-intent-source-invalid'; end if;
      v_item := v_item || jsonb_build_object('themeId',lower(v_item ->> 'themeId'));
      if not exists (select 1 from jsonb_array_elements(v_themes) t
        where t ->> 'themeId' = v_item ->> 'themeId' and t ->> 'action' = 'prepare')
      then raise exception 'mesa-intent-incorporation-target-invalid'; end if;
    else
      if not (v_item ? 'newArticleCount') or v_item - array['sourceId','destination','newArticleCount'] <> '{}'
        or jsonb_typeof(v_item -> 'newArticleCount') is distinct from 'number'
        or (v_item ->> 'newArticleCount') !~ '^[0-9]+$'
      then raise exception 'mesa-intent-source-invalid'; end if;
      if (v_item ->> 'newArticleCount')::numeric not between 1 and 30 then raise exception 'mesa-intent-source-invalid'; end if;
    end case;
    v_sources := v_sources || jsonb_build_array(v_item || jsonb_build_object('sourceId',lower(v_item ->> 'sourceId')));
  end loop;
  if exists (select 1 from jsonb_array_elements(v_themes) t group by t ->> 'themeId' having count(*) > 1)
    or exists (select 1 from jsonb_array_elements(v_sources) s group by s ->> 'sourceId' having count(*) > 1)
  then raise exception 'mesa-intent-selection-duplicate'; end if;
  return jsonb_build_object('version',1,'preparationKey',lower(p_request ->> 'preparationKey'),
    'title',btrim(p_request ->> 'title'),
    'themes',(select coalesce(jsonb_agg(t order by t ->> 'themeId'),'[]') from jsonb_array_elements(v_themes) t),
    'sources',(select coalesce(jsonb_agg(s order by s ->> 'sourceId'),'[]') from jsonb_array_elements(v_sources) s));
end;
$function$;
revoke all on function public.newsroom_mesa_normalize_intent_v1(jsonb) from public, anon, authenticated, service_role;

-- Private helper: capture identity plus a hash of metadata AND body, so changes
-- under the same snapshot ID cannot evade the final transaction comparison.
create function public.newsroom_mesa_intent_source_v1(p_source_id uuid)
returns jsonb language sql stable security definer set search_path = '' as $function$
  select jsonb_build_object('newsroomArticleId',a.id,'newsroomSnapshotId',s.id,
    'capturedAt',to_char(s.extracted_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'contentFingerprint',encode(sha256(convert_to(jsonb_build_object('article',to_jsonb(a),
      'snapshot',to_jsonb(s),'classification',to_jsonb(c))::text,'UTF8')),'hex'),
    'usable',jsonb_typeof(s.body) = 'array' and exists (
      select 1 from jsonb_array_elements(case when jsonb_typeof(s.body) = 'array' then s.body else '[]' end) b
      where b ->> 'type' in ('paragraph','heading') and nullif(btrim(b ->> 'text'),'') is not null),
    'classificationKey',c.classification_key)
  from public.newsroom_articles a
  left join lateral (select * from public.newsroom_article_snapshots x where x.article_id = a.id
    order by x.extracted_at desc, x.created_at desc, x.id desc limit 1) s on true
  left join public.newsroom_editorial_article_classifications c on c.newsroom_article_id = a.id
  where a.id = p_source_id;
$function$;
revoke all on function public.newsroom_mesa_intent_source_v1(uuid) from public, anon, authenticated, service_role;

create function public.newsroom_mesa_preview_intents_v1(p_request jsonb)
returns table(plan jsonb) language plpgsql stable security definer set search_path = '' as $function$
declare
  v_request jsonb := public.newsroom_mesa_normalize_intent_v1(p_request);
  v_intent jsonb; v_theme public.newsroom_editorial_themes%rowtype;
  v_id uuid; v_key text; v_source jsonb; v_sources jsonb; v_history jsonb;
  v_contexts jsonb := '[]'; v_outputs jsonb := '[]'; v_incorporations jsonb := '[]';
  v_context jsonb; v_article jsonb; v_review_count integer := 0; v_new_count integer := 0;
  v_source_count integer; v_i integer; v_material jsonb;
begin
  for v_intent in select t from jsonb_array_elements(v_request -> 'themes') t where t ->> 'action' = 'prepare' loop
    select * into v_theme from public.newsroom_editorial_themes t where t.id = (v_intent ->> 'themeId')::uuid and t.status = 'open';
    if not found then raise exception 'mesa-intent-theme-unavailable' using detail = v_intent ->> 'themeId'; end if;
    v_key := 'theme:' || v_theme.id::text;
    v_sources := '[]';
    for v_id in
      select m.newsroom_article_id from public.newsroom_editorial_theme_sources m where m.theme_id = v_theme.id
      union select (s ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') s
        where s ->> 'destination' = 'theme' and s ->> 'themeId' = v_theme.id::text
      order by 1
    loop
      v_source := public.newsroom_mesa_intent_source_v1(v_id);
      if v_source is null or v_source ->> 'newsroomSnapshotId' is null or v_source -> 'usable' is distinct from 'true'::jsonb then
        raise exception 'mesa-intent-source-snapshot-unavailable' using detail = v_key || ':' || v_id::text;
      end if;
      if v_source ->> 'classificationKey' is null then raise exception 'mesa-intent-classification-required' using detail = v_id::text; end if;
      v_sources := v_sources || jsonb_build_array(v_source);
      if not exists (select 1 from public.newsroom_editorial_theme_sources m where m.theme_id = v_theme.id and m.newsroom_article_id = v_id) then
        v_incorporations := v_incorporations || jsonb_build_array(jsonb_build_object('themeId',v_theme.id,'sourceId',v_id));
      end if;
    end loop;
    if jsonb_array_length(v_sources) = 0 then raise exception 'mesa-intent-theme-sources-missing' using detail = v_key; end if;
    select coalesce(jsonb_agg(jsonb_build_object('editorialArticleId',a.id,'slug',a.slug,'title',a.title,
      'matchdayId',a.matchday_id,'contentFingerprint',encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),
      'article',to_jsonb(a)) order by a.id),'[]') into v_history
    from public.newsroom_editorial_theme_articles m join public.editorial_articles a on a.id = m.editorial_article_id
    where m.theme_id = v_theme.id and a.status = 'published';
    if exists (select 1 from jsonb_array_elements(v_history) a where nullif(btrim(a ->> 'slug'),'') is null or nullif(btrim(a ->> 'title'),'') is null) then
      raise exception 'mesa-intent-published-history-invalid' using detail = v_key;
    end if;
    if (v_intent ->> 'reviewPublished')::boolean and jsonb_array_length(v_history) = 0 then
      raise exception 'mesa-intent-nothing-to-review' using detail = v_key;
    end if;
    if not (v_intent ->> 'reviewPublished')::boolean and (v_intent ->> 'newArticleCount')::integer = 0 then
      raise exception 'mesa-intent-theme-work-missing' using detail = v_key;
    end if;
    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object('key',v_key,'kind','theme',
      'themeId',v_theme.id,'sourceId',null,'title',v_theme.title,'theme',to_jsonb(v_theme),
      'reviewPublished',v_intent -> 'reviewPublished','newArticleCount',v_intent -> 'newArticleCount',
      'sources',v_sources,'publishedArticles',v_history));
  end loop;
  for v_intent in select s from jsonb_array_elements(v_request -> 'sources') s where s ->> 'destination' = 'independent' loop
    v_id := (v_intent ->> 'sourceId')::uuid; v_key := 'source:' || v_id::text;
    if exists (select 1 from public.newsroom_editorial_theme_sources m where m.newsroom_article_id = v_id) then
      raise exception 'mesa-intent-independent-source-not-loose' using detail = v_key;
    end if;
    v_source := public.newsroom_mesa_intent_source_v1(v_id);
    if v_source is null or v_source ->> 'newsroomSnapshotId' is null or v_source -> 'usable' is distinct from 'true'::jsonb then
      raise exception 'mesa-intent-source-snapshot-unavailable' using detail = v_key;
    end if;
    if v_source ->> 'classificationKey' is null then raise exception 'mesa-intent-classification-required' using detail = v_key; end if;
    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object('key',v_key,'kind','source',
      'themeId',null,'sourceId',v_id,'title','Fonte independente','reviewPublished',false,
      'newArticleCount',v_intent -> 'newArticleCount','sources',jsonb_build_array(v_source),'publishedArticles','[]'::jsonb));
  end loop;
  select coalesce(jsonb_agg(c order by c ->> 'key'),'[]') into v_contexts from jsonb_array_elements(v_contexts) c;
  for v_context in select c from jsonb_array_elements(v_contexts) c where (c ->> 'reviewPublished')::boolean loop
    for v_article in select a from jsonb_array_elements(v_context -> 'publishedArticles') a loop
      if exists (select 1 from jsonb_array_elements(v_outputs) o where o -> 'target' ->> 'editorialArticleId' = v_article ->> 'editorialArticleId') then
        raise exception 'mesa-intent-review-target-conflict';
      end if;
      v_review_count := v_review_count + 1;
      v_outputs := v_outputs || jsonb_build_array(jsonb_build_object('slot','EXISTING_' || lpad(v_review_count::text,2,'0'),
        'contextKey',v_context ->> 'key','kind','existing','target',v_article));
    end loop;
  end loop;
  for v_context in select value from jsonb_array_elements(v_contexts) loop
    for v_i in 1..(v_context ->> 'newArticleCount')::integer loop
      v_new_count := v_new_count + 1;
      v_outputs := v_outputs || jsonb_build_array(jsonb_build_object('slot','NEW_' || lpad(v_new_count::text,2,'0'),
        'contextKey',v_context ->> 'key','kind','new','target',null));
    end loop;
  end loop;
  select count(distinct s ->> 'newsroomArticleId')::integer into v_source_count
    from jsonb_array_elements(v_contexts) c cross join lateral jsonb_array_elements(c -> 'sources') s;
  if jsonb_array_length(v_contexts) > 20 then raise exception 'mesa-intent-context-limit'; end if;
  if v_source_count > 20 then raise exception 'mesa-intent-source-limit'; end if;
  if v_review_count + v_new_count = 0 then raise exception 'mesa-intent-no-work-requested'; end if;
  if v_review_count + v_new_count > 30 then raise exception 'mesa-intent-output-limit'; end if;
  v_material := jsonb_build_object('contractVersion',1,'request',v_request,
    'preparationKey',v_request ->> 'preparationKey','title',v_request ->> 'title',
    'contexts',v_contexts,'outputs',v_outputs,'incorporations',v_incorporations,
    'deferred',jsonb_build_object(
      'themeIds',(select coalesce(jsonb_agg(t -> 'themeId'),'[]') from jsonb_array_elements(v_request -> 'themes') t where t ->> 'action' = 'defer'),
      'sourceIds',(select coalesce(jsonb_agg(s -> 'sourceId'),'[]') from jsonb_array_elements(v_request -> 'sources') s where s ->> 'destination' = 'defer')),
    'totals',jsonb_build_object('contexts',jsonb_array_length(v_contexts),'sources',v_source_count,'reviews',v_review_count,'newArticles',v_new_count));
  return query select v_material || jsonb_build_object('capturedAt',to_char(statement_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'authorityFingerprint',encode(sha256(convert_to(v_material::text,'UTF8')),'hex'));
end;
$function$;
revoke all on function public.newsroom_mesa_preview_intents_v1(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.newsroom_mesa_preview_intents_v1(jsonb) to service_role;

create function public.newsroom_prepare_mesa_intents_v1(p_request jsonb, p_expected_authority_fingerprint text)
returns table(result jsonb) language plpgsql volatile security definer set search_path = '' as $function$
declare
  v_request jsonb := public.newsroom_mesa_normalize_intent_v1(p_request);
  v_key uuid := (v_request ->> 'preparationKey')::uuid;
  v_existing public.newsroom_mesa_intent_preparations%rowtype;
  v_preview jsonb; v_contexts jsonb := '[]'; v_context jsonb; v_item jsonb;
  v_result record; v_context_id uuid; v_plan_id uuid; v_ids uuid[]; v_plan_ids uuid[] := '{}';
  v_frozen_contexts jsonb := '[]'; v_outputs jsonb := '[]'; v_frozen jsonb; v_i integer := 0;
begin
  if p_expected_authority_fingerprint is null or p_expected_authority_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'mesa-intent-fingerprint-invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1',0));
  -- Test idempotency before current-state reads: a retry must not be invalidated
  -- by memberships created by its own first successful call.
  select * into v_existing from public.newsroom_mesa_intent_preparations p where p.preparation_key = v_key;
  if found then
    if v_existing.request is distinct from v_request or v_existing.authority_fingerprint is distinct from p_expected_authority_fingerprint then
      raise exception 'mesa-intent-preparation-conflict';
    end if;
    return query select jsonb_build_object('dossierId',v_existing.dossier_id,'preparationAction','reused','plan',v_existing.frozen_plan);
    return;
  end if;
  if exists (select 1 from public.newsroom_mesa_production_contexts w where w.preparation_key = v_key)
    or exists (select 1 from public.newsroom_editorial_dossiers d where d.preparation_key = v_key)
  then raise exception 'mesa-intent-preparation-key-used'; end if;
  update public.newsroom_mesa_containment_guard set revision = not revision where singleton;
  if not found then raise exception 'mesa-organization-containment-guard-missing'; end if;
  perform 1 from public.newsroom_editorial_themes t where t.id in (
    select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
  ) order by t.id for update;
  -- Parent FOR UPDATE locks also block an ingest inserting a new snapshot through
  -- its FK while sources are frozen. Existing snapshot rows are locked as well.
  perform 1 from public.newsroom_articles a where a.id in (
    select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
    union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m
      where m.theme_id in (select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare')
  ) order by a.id for update;
  perform 1 from public.newsroom_article_snapshots s where s.article_id in (
    select a.id from public.newsroom_articles a where a.id in (
      select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
      union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m where m.theme_id in (
        select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'))
  ) order by s.id for share;
  perform 1 from public.newsroom_editorial_article_classifications c where c.newsroom_article_id in (
    select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
    union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m where m.theme_id in (
      select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare')
  ) order by c.newsroom_article_id for share;
  perform 1 from public.editorial_articles a where a.id in (
    select m.editorial_article_id from public.newsroom_editorial_theme_articles m where m.theme_id in (
      select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare')
  ) order by a.id for share;
  select p.plan into strict v_preview from public.newsroom_mesa_preview_intents_v1(v_request) p;
  if v_preview ->> 'authorityFingerprint' is distinct from p_expected_authority_fingerprint then
    raise exception 'mesa-intent-authority-stale';
  end if;
  -- Incorporations and all workspaces/plans share THIS transaction. Any later
  -- exception rolls everything back; previewing the request never associates.
  for v_item in select value from jsonb_array_elements(v_preview -> 'incorporations') loop
    perform public.newsroom_set_editorial_theme_source_membership_v1((v_item ->> 'themeId')::uuid,(v_item ->> 'sourceId')::uuid,true);
  end loop;
  for v_context in select value from jsonb_array_elements(v_preview -> 'contexts') loop
    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object('kind',v_context -> 'kind',
      'themeId',v_context -> 'themeId','sourceId',v_context -> 'sourceId',
      'sources',(select jsonb_agg(jsonb_build_object('newsroomArticleId',s -> 'newsroomArticleId',
        'newsroomSnapshotId',s -> 'newsroomSnapshotId') order by s ->> 'newsroomArticleId') from jsonb_array_elements(v_context -> 'sources') s)));
  end loop;
  select * into strict v_result from public.newsroom_prepare_mesa_contexts_v3(v_key,v_request ->> 'title',v_contexts,null,'{}');
  for v_context in select value from jsonb_array_elements(v_preview -> 'contexts') loop
    select c.id into strict v_context_id from public.newsroom_mesa_production_context_items c
      where c.dossier_id = v_result.dossier_id and c.context_kind = v_context ->> 'kind'
        and c.theme_id is not distinct from (v_context ->> 'themeId')::uuid
        and c.source_newsroom_article_id is not distinct from (v_context ->> 'sourceId')::uuid;
    v_frozen_contexts := v_frozen_contexts || jsonb_build_array(v_context || jsonb_build_object('productionContextId',v_context_id));
  end loop;
  for v_item in select value from jsonb_array_elements(v_preview -> 'outputs') loop
    v_i := v_i + 1;
    select c into strict v_context from jsonb_array_elements(v_frozen_contexts) c where c ->> 'key' = v_item ->> 'contextKey';
    v_context_id := (v_context ->> 'productionContextId')::uuid;
    select array_agg(s.dossier_source_id order by s.sort_order) into v_ids
      from public.newsroom_mesa_production_context_sources s where s.dossier_id = v_result.dossier_id and s.production_context_id = v_context_id;
    select p.article_plan_id into strict v_plan_id from public.newsroom_save_mesa_context_article_plan_v1(
      v_result.dossier_id,null,left((v_item ->> 'slot') || ' — ' || coalesce(v_item -> 'target' ->> 'title','novo artigo'),180),
      'planned',v_i*10,'news','standard',case when v_item ->> 'kind' = 'existing' then 'Rever o artigo: UPDATE ou SEM ALTERAÇÃO.'
        else 'Produzir artigo novo apenas com as fontes deste contexto; não rever os artigos de referência.' end,v_ids,v_context_id) p;
    perform public.newsroom_save_dossier_article_plan_state_v1(v_result.dossier_id,v_plan_id,
      case when v_item ->> 'kind' = 'existing' then 'update' else 'new' end,
      (v_item -> 'target' ->> 'editorialArticleId')::uuid,'{}',
      case when v_item ->> 'kind' = 'existing' then 'preserve_published' else 'unselected' end,null);
    v_plan_ids := v_plan_ids || v_plan_id;
    v_outputs := v_outputs || jsonb_build_array(v_item || jsonb_build_object('outputId',v_plan_id,'productionContextId',v_context_id));
  end loop;
  perform public.newsroom_set_mesa_shared_outputs_v2(v_result.dossier_id,v_plan_ids);
  v_frozen := v_preview || jsonb_build_object('dossierId',v_result.dossier_id,'contexts',v_frozen_contexts,'outputs',v_outputs);
  insert into public.newsroom_mesa_intent_preparations(preparation_key,dossier_id,request,authority_fingerprint,captured_at,frozen_plan)
    values(v_key,v_result.dossier_id,v_request,p_expected_authority_fingerprint,(v_preview ->> 'capturedAt')::timestamptz,v_frozen);
  update public.newsroom_mesa_production_contexts set selection_payload = selection_payload || jsonb_build_object('productionIntents',v_frozen)
    where dossier_id = v_result.dossier_id;
  return query select jsonb_build_object('dossierId',v_result.dossier_id,'preparationAction','created','plan',v_frozen);
end;
$function$;
revoke all on function public.newsroom_prepare_mesa_intents_v1(jsonb,text) from public, anon, authenticated, service_role;
grant execute on function public.newsroom_prepare_mesa_intents_v1(jsonb,text) to service_role;

-- Receipts are intentionally not written here. Preparing or publishing NEW must
-- never mean that the old articles were reviewed. Completion needs its own gate.
commit;

-- Opt-in intent publication. Legacy data/routes are unchanged. The deferred
-- consolidation dispatcher gains an opt-in guard; legacy work still delegates to V4.
-- Apply only together with the verified application integration; not enabled yet.
begin;
do $preflight$
begin
  if to_regclass('public.newsroom_mesa_intent_preparations') is null
    or to_regclass('public.newsroom_mesa_output_publications') is null
    or to_regprocedure('public.newsroom_mesa_plan_context_sources_valid_v1(uuid,uuid,uuid)') is null
    or to_regprocedure('public.sync_editorial_article_live_snapshots_v15(uuid,text)') is null
    or to_regprocedure('public.set_matchday_latest_news_settings_v15(uuid,text,text,text,boolean)') is null
    or to_regprocedure('public.normalize_matchday_latest_news_order(uuid)') is null
    or to_regprocedure('jornada_private.acquire_matchday_live_layout_cutover_writer_lock()') is null
    or to_regclass('public.matchday_latest_news') is null
  then raise exception 'mesa-intent-publication-authority-missing'; end if;
  if (select regexp_replace(p.prosrc,'\s','','g') from pg_proc p
      where p.oid=to_regprocedure('public.newsroom_mesa_consolidate_publication_v2(uuid)'))
      is distinct from 'selectpublic.newsroom_mesa_consolidate_publication_v4(p_dossier_id);' then
    raise exception 'mesa-intent-consolidation-dispatcher-drift';
  end if;
end;
$preflight$;

-- Adds a hash of the exact frozen snapshot for publication-time integrity.
create or replace function public.newsroom_mesa_intent_source_v1(p_source_id uuid)
returns jsonb language sql stable security definer set search_path = '' as $function$
  select jsonb_build_object('newsroomArticleId',a.id,'newsroomSnapshotId',s.id,
    'capturedAt',to_char(s.extracted_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'snapshotFingerprint',encode(sha256(convert_to(to_jsonb(s)::text,'UTF8')),'hex'),
    'contentFingerprint',encode(sha256(convert_to(jsonb_build_object('article',to_jsonb(a),
      'snapshot',to_jsonb(s),'classification',to_jsonb(c))::text,'UTF8')),'hex'),
    'usable',jsonb_typeof(s.body) = 'array' and exists (
      select 1 from jsonb_array_elements(case when jsonb_typeof(s.body) = 'array' then s.body else '[]' end) b
      where b ->> 'type' in ('paragraph','heading') and nullif(btrim(b ->> 'text'),'') is not null),
    'classificationKey',c.classification_key)
  from public.newsroom_articles a
  left join lateral (select * from public.newsroom_article_snapshots x where x.article_id = a.id
    order by x.extracted_at desc, x.created_at desc, x.id desc limit 1) s on true
  left join public.newsroom_editorial_article_classifications c on c.newsroom_article_id = a.id
  where a.id = p_source_id;
$function$;
revoke all on function public.newsroom_mesa_intent_source_v1(uuid) from public, anon, authenticated, service_role;

create table public.newsroom_mesa_intent_finalizations (
  dossier_id uuid primary key references public.newsroom_mesa_intent_preparations(dossier_id) on delete restrict,
  package_id uuid not null references public.newsroom_editorial_source_packages(id) on delete restrict,
  publication_event_id uuid not null unique references public.newsroom_mesa_publication_events(id) on delete restrict,
  no_change_output_ids uuid[] not null,
  updated_count integer not null check (updated_count>=0),
  new_count integer not null check (new_count>=0),
  no_change_count integer not null check (no_change_count>=0),
  completed_at timestamptz not null default clock_timestamp(),
  check (updated_count+new_count+no_change_count between 1 and 30)
);

create table public.newsroom_mesa_intent_article_receipts (
  dossier_id uuid not null references public.newsroom_mesa_intent_finalizations(dossier_id) on delete restrict,
  output_id uuid not null references public.newsroom_editorial_dossier_article_plans(id) on delete restrict,
  theme_id uuid not null references public.newsroom_editorial_themes(id) on delete restrict,
  editorial_article_id uuid not null references public.editorial_articles(id) on delete restrict,
  slot text not null check (slot ~ '^(EXISTING|NEW)_[0-9]{2}$'),
  decision text not null check (decision in ('UPDATE','SEM_ALTERAÇÃO','NEW')),
  captured_at timestamptz not null,
  completed_at timestamptz not null default clock_timestamp(),
  sources jsonb not null check (jsonb_typeof(sources)='array' and jsonb_array_length(sources) between 1 and 20),
  result_fingerprint text not null check (result_fingerprint ~ '^[0-9a-f]{64}$'),
  primary key (dossier_id,output_id)
);
create index newsroom_mesa_intent_receipt_article_capture_idx
  on public.newsroom_mesa_intent_article_receipts(theme_id,editorial_article_id,captured_at desc);

alter table public.newsroom_mesa_intent_finalizations enable row level security;
alter table public.newsroom_mesa_intent_finalizations force row level security;
alter table public.newsroom_mesa_intent_article_receipts enable row level security;
alter table public.newsroom_mesa_intent_article_receipts force row level security;
revoke all on public.newsroom_mesa_intent_finalizations, public.newsroom_mesa_intent_article_receipts
  from public, anon, authenticated, service_role;
grant select on public.newsroom_mesa_intent_finalizations, public.newsroom_mesa_intent_article_receipts to service_role;

-- The existing deferred plan/assignment triggers call this V2 dispatcher.
-- Without this guard, the last materialized output would consolidate before
-- the explicit receipt transaction. The legacy V4 implementation is untouched.
create or replace function public.newsroom_mesa_consolidate_publication_v2(p_dossier_id uuid)
returns boolean language sql security definer set search_path='' as $function$
  select case when exists (select 1 from public.newsroom_mesa_intent_preparations p where p.dossier_id=p_dossier_id)
    then false else public.newsroom_mesa_consolidate_publication_v4(p_dossier_id) end;
$function$;

-- Refuse the legacy publisher for opt-in plans, rather than silently bypassing
-- snapshot/target guards and recording an uncertified write.
create function public.newsroom_assert_mesa_intent_write_boundary_v1()
returns trigger language plpgsql security definer set search_path='' as $function$
begin
  if exists(select 1 from public.newsroom_mesa_intent_preparations p where p.dossier_id=new.dossier_id)
    and (jsonb_typeof(new.payload -> 'intentResultFingerprint') is distinct from 'string'
      or coalesce(new.payload ->> 'intentResultFingerprint','') !~ '^[0-9a-f]{64}$') then
    raise exception 'mesa-intent-publication-path-required';
  end if;
  return new;
end;
$function$;
revoke all on function public.newsroom_assert_mesa_intent_write_boundary_v1() from public,anon,authenticated,service_role;
create trigger newsroom_mesa_intent_write_boundary_v1 before insert or update on public.newsroom_mesa_output_publications
  for each row execute function public.newsroom_assert_mesa_intent_write_boundary_v1();

-- Private transactional gate. The DB-frozen plan, NOT the browser, fixes every
-- output, context, UPDATE target and exact source set. Lock workspace first in
-- both writers to serialize finalization against in-flight per-output writes.
create function public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id uuid,p_package_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $function$
declare
  v_workspace public.newsroom_mesa_production_contexts%rowtype;
  v_plan jsonb; v_manifest jsonb; v_output jsonb; v_context jsonb; v_item jsonb;
  v_ids uuid[]; v_expected uuid[]; v_source jsonb;
begin
  if p_dossier_id is null or p_package_id is null then raise exception 'mesa-intent-publication-input-invalid'; end if;
  select * into v_workspace from public.newsroom_mesa_production_contexts w where w.dossier_id=p_dossier_id for update;
  if not found or v_workspace.workspace_role<>'technical' or v_workspace.workspace_contract_version<>2
    or v_workspace.workspace_state not in ('active','consolidated') then
    raise exception 'mesa-intent-publication-workspace-invalid';
  end if;
  select p.frozen_plan into v_plan from public.newsroom_mesa_intent_preparations p where p.dossier_id=p_dossier_id for share;
  if not found or v_workspace.selection_payload -> 'productionIntents' is distinct from v_plan
    or v_plan ->> 'contractVersion' is distinct from '1'
    or jsonb_typeof(v_plan -> 'outputs') is distinct from 'array'
    or jsonb_array_length(v_plan -> 'outputs') not between 1 and 30
    or jsonb_typeof(v_plan -> 'contexts') is distinct from 'array' then
    raise exception 'mesa-intent-publication-plan-invalid';
  end if;
  select p.manifest into v_manifest from public.newsroom_editorial_source_packages p where p.id=p_package_id for share;
  if not found or v_manifest ->> 'version' is distinct from '5'
    or v_manifest ->> 'provenanceContract' is distinct from 'mesa-v2'
    or v_manifest -> 'productionIntents' is distinct from v_plan
    or jsonb_typeof(v_manifest -> 'outputs') is distinct from 'array'
    or jsonb_array_length(v_manifest -> 'outputs')<>jsonb_array_length(v_plan -> 'outputs') then
    raise exception 'mesa-intent-publication-package-invalid';
  end if;
  -- A second package may not take over a partially published preparation.
  if exists (select 1 from public.newsroom_mesa_output_publications p
    where p.dossier_id=p_dossier_id and p.package_id<>p_package_id) then
    raise exception 'mesa-intent-publication-package-conflict';
  end if;
  if (select count(*) from public.newsroom_editorial_dossier_article_plans p
      where p.dossier_id=p_dossier_id and p.status<>'cancelled')<>jsonb_array_length(v_plan -> 'outputs') then
    raise exception 'mesa-intent-publication-plan-invalid';
  end if;
  for v_output in select value from jsonb_array_elements(v_plan -> 'outputs') loop
    if not exists (select 1 from public.newsroom_editorial_dossier_article_plans p
      join public.newsroom_mesa_article_plan_contexts a on a.dossier_id=p.dossier_id and a.article_plan_id=p.id
      where p.dossier_id=p_dossier_id and p.id=(v_output ->> 'outputId')::uuid and p.status<>'cancelled'
        and a.production_context_id=(v_output ->> 'productionContextId')::uuid
        and p.destination=case when v_output ->> 'kind'='existing' then 'update' else 'new' end
        and p.update_target_editorial_article_id is not distinct from (v_output -> 'target' ->> 'editorialArticleId')::uuid
        and public.newsroom_mesa_plan_context_sources_valid_v1(p_dossier_id,p.id,a.production_context_id)) then
      raise exception 'mesa-intent-publication-output-invalid';
    end if;
    select value into v_context from jsonb_array_elements(v_plan -> 'contexts')
      where value ->> 'key'=v_output ->> 'contextKey'
        and value ->> 'productionContextId'=v_output ->> 'productionContextId';
    if not found or (v_output ->> 'kind'='existing' and v_context -> 'reviewPublished' is distinct from 'true'::jsonb) then
      raise exception 'mesa-intent-publication-context-invalid';
    end if;
    if (select count(*) from jsonb_array_elements(v_manifest -> 'outputs') o
      where o ->> 'outputId'=v_output ->> 'outputId')<>1 then
      raise exception 'mesa-intent-publication-package-invalid';
    end if;
    select o into strict v_item from jsonb_array_elements(v_manifest -> 'outputs') o where o ->> 'outputId'=v_output ->> 'outputId';
    if v_item -> 'articlePlan' ->> 'articlePlanId' is distinct from v_output ->> 'outputId'
      or v_item -> 'articlePlan' ->> 'dossierId' is distinct from p_dossier_id::text
      or v_item -> 'articlePlan' ->> 'contextId' is distinct from v_output ->> 'productionContextId'
      or v_item -> 'articlePlan' ->> 'sourceScope' is distinct from 'context'
      or jsonb_typeof(v_item -> 'contextSourceIds') is distinct from 'array' then
      raise exception 'mesa-intent-publication-package-invalid';
    end if;
    select array_agg((s #>> '{}')::uuid order by (s #>> '{}')::uuid) into v_ids from jsonb_array_elements(v_item -> 'contextSourceIds') s;
    select array_agg(c.dossier_source_id order by c.dossier_source_id) into v_expected
      from public.newsroom_mesa_production_context_sources c where c.dossier_id=p_dossier_id and c.production_context_id=(v_output ->> 'productionContextId')::uuid;
    if v_ids is distinct from v_expected then raise exception 'mesa-intent-publication-source-invalid'; end if;
  end loop;
  -- A later snapshot is valid new material for a future production; it must not
  -- invalidate THIS frozen package. Mutation of its original snapshot does.
  for v_context in select value from jsonb_array_elements(v_plan -> 'contexts') loop
    for v_source in select value from jsonb_array_elements(v_context -> 'sources') loop
      select to_jsonb(s) into v_item from public.newsroom_article_snapshots s
        where s.id=(v_source ->> 'newsroomSnapshotId')::uuid
          and s.article_id=(v_source ->> 'newsroomArticleId')::uuid for share;
      if not found or encode(sha256(convert_to(v_item::text,'UTF8')),'hex') is distinct from v_source ->> 'snapshotFingerprint' then
        raise exception 'mesa-intent-frozen-source-stale';
      end if;
    end loop;
  end loop;
  return v_plan;
end;
$function$;
revoke all on function public.newsroom_mesa_lock_intent_publication_v1(uuid,uuid) from public,anon,authenticated,service_role;
create function public.newsroom_publish_mesa_intent_output_v1(
  p_dossier_id uuid,
  p_output_id uuid,
  p_package_id uuid,
  p_dossier_source_ids uuid[],
  p_article jsonb
)
returns table(
  editorial_article_id uuid,
  article_slug text,
  publication_action text,
  consolidated boolean
)
language plpgsql security definer set search_path = '' as $function$
declare
  v_intent jsonb; v_slot jsonb; v_expected jsonb; v_current jsonb;
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_plan public.newsroom_editorial_dossier_article_plans%rowtype;
  v_manifest jsonb; v_manifest_output jsonb;
  v_existing public.newsroom_mesa_output_publications%rowtype;
  v_article_id uuid; v_slug text; v_label text; v_title text; v_subtitle text; v_body text;
  v_image text; v_author text; v_published_at timestamptz; v_matchday uuid; v_mode text;
  v_previous_slug text; v_source_scope text := 'workspace'; v_production_context_id uuid;
  v_declared_context_source_ids uuid[]; v_frozen_context_source_ids uuid[];
  v_is_2c boolean;
  v_payload jsonb; v_fingerprint text; v_consolidated boolean; v_now timestamptz := now();
begin
  if p_dossier_id is null or p_output_id is null or p_package_id is null
    or p_dossier_source_ids is null or cardinality(p_dossier_source_ids) < 1
    or cardinality(p_dossier_source_ids) > 20 or array_position(p_dossier_source_ids, null) is not null
    or (select count(distinct source_id) from unnest(p_dossier_source_ids) source_id) <> cardinality(p_dossier_source_ids)
    or p_article is null or jsonb_typeof(p_article) <> 'object' then
    raise exception 'mesa-publication-input-invalid';
  end if;

  -- All intent writers/finalizers acquire the workspace first, then canonical
  -- articles in ID order. Publication never calls the generic consolidator.
  v_intent := public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  select o into v_slot from jsonb_array_elements(v_intent -> 'outputs') o
    where o ->> 'outputId' = p_output_id::text;
  if not found then raise exception 'mesa-intent-output-invalid'; end if;
  v_expected := v_slot -> 'target';
  select * into v_context from public.newsroom_mesa_production_contexts context
    where context.dossier_id = p_dossier_id for update;
  if not found or v_context.workspace_role <> 'technical' or v_context.workspace_contract_version <> 2
    or v_context.workspace_state not in ('active', 'consolidated') then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  v_is_2c := coalesce(
    v_context.selection_payload ->> 'contractVersion' = '3'
      and v_context.selection_payload ->> 'contextContractVersion' = '1',
    false
  );
  if coalesce(
    v_context.selection_payload ->> 'contractVersion' = '3'
      or v_context.selection_payload ? 'contextContractVersion',
    false
  ) and not v_is_2c then
    raise exception 'mesa-publication-workspace-invalid';
  end if;
  if v_is_2c is distinct from (exists (
      select 1 from public.newsroom_mesa_production_context_items context_item
      where context_item.dossier_id = p_dossier_id
    )) then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  select * into v_plan from public.newsroom_editorial_dossier_article_plans plan
    where plan.dossier_id = p_dossier_id and plan.id = p_output_id
      and plan.status <> 'cancelled' for update;
  if not found then raise exception 'mesa-publication-output-invalid'; end if;

  if v_is_2c then
    select assignment.production_context_id
    into v_production_context_id
    from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id = p_dossier_id
      and assignment.article_plan_id = p_output_id;
    if not found or not public.newsroom_mesa_plan_context_sources_valid_v1(
      p_dossier_id, p_output_id, v_production_context_id
    ) then
      raise exception 'mesa-publication-output-invalid';
    end if;
    v_source_scope := 'context';
  elsif exists (
    select 1 from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id = p_dossier_id
      and assignment.article_plan_id = p_output_id
  ) then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  select package.manifest into v_manifest from public.newsroom_editorial_source_packages package
    where package.id = p_package_id for update;
  if not found or (v_manifest ->> 'version')::integer <> 5
    or v_manifest ->> 'provenanceContract' <> 'mesa-v2' then
    raise exception 'mesa-publication-package-invalid';
  end if;

  select output.value into v_manifest_output
  from jsonb_array_elements(v_manifest -> 'outputs') output(value)
  where lower(output.value ->> 'outputId') = p_output_id::text
    and lower(output.value -> 'articlePlan' ->> 'articlePlanId') = p_output_id::text
    and lower(output.value -> 'articlePlan' ->> 'dossierId') = p_dossier_id::text;
  if not found
    or v_manifest_output -> 'articlePlan' ->> 'sourceScope' is distinct from v_source_scope
    or v_manifest_output -> 'articlePlan' ? 'origin' then
    raise exception 'mesa-publication-package-invalid';
  end if;

  if v_source_scope = 'context' then
    if lower(v_manifest_output -> 'articlePlan' ->> 'contextId')
      is distinct from v_production_context_id::text
      or jsonb_typeof(v_manifest_output -> 'contextSourceIds') is distinct from 'array'
    then
      raise exception 'mesa-publication-package-invalid';
    end if;
    begin
      select array_agg((source_id.value #>> '{}')::uuid order by (source_id.value #>> '{}')::uuid)
      into v_declared_context_source_ids
      from jsonb_array_elements(v_manifest_output -> 'contextSourceIds') source_id(value);
    exception when others then
      raise exception 'mesa-publication-package-invalid';
    end;
    select array_agg(context_source.dossier_source_id order by context_source.dossier_source_id)
    into v_frozen_context_source_ids
    from public.newsroom_mesa_production_context_sources context_source
    where context_source.dossier_id = p_dossier_id
      and context_source.production_context_id = v_production_context_id;
    if v_declared_context_source_ids is distinct from v_frozen_context_source_ids
      or exists (
        select 1 from unnest(p_dossier_source_ids) requested(id)
        where not (requested.id = any(v_frozen_context_source_ids))
      )
    then
      raise exception 'mesa-publication-source-invalid';
    end if;
  end if;

  if exists(select 1 from unnest(p_dossier_source_ids) requested(id)
    left join public.newsroom_editorial_dossier_sources dossier_source
      on dossier_source.id = requested.id
      and dossier_source.dossier_id = p_dossier_id
      and dossier_source.included
    where dossier_source.id is null
      or not exists(select 1 from jsonb_array_elements(v_context.source_refs) ref
        where lower(ref ->> 'newsroomArticleId') = dossier_source.newsroom_article_id::text
          and lower(ref ->> 'newsroomSnapshotId') = dossier_source.newsroom_snapshot_id::text)
      or not exists(select 1 from jsonb_array_elements(v_manifest -> 'entries') entry
        where entry ->> 'status' = 'prepared'
          and lower(entry ->> 'provenanceSourceId') = requested.id::text
          and lower(entry ->> 'newsroomArticleId') = dossier_source.newsroom_article_id::text
          and lower(entry ->> 'newsroomSnapshotId') = dossier_source.newsroom_snapshot_id::text)
  ) then raise exception 'mesa-publication-source-invalid'; end if;

  begin
    v_article_id := (p_article ->> 'id')::uuid;
  exception when others then
    raise exception 'mesa-publication-article-invalid';
  end;
  v_slug := btrim(coalesce(p_article ->> 'slug', ''));
  v_label := btrim(coalesce(p_article ->> 'label', ''));
  v_title := btrim(coalesce(p_article ->> 'title', ''));
  v_subtitle := btrim(coalesce(p_article ->> 'subtitle', ''));
  v_body := btrim(coalesce(p_article ->> 'body', ''));
  v_image := nullif(btrim(coalesce(p_article ->> 'imageUrl', '')), '');
  v_author := btrim(coalesce(p_article ->> 'author', ''));
  v_mode := lower(btrim(coalesce(p_article ->> 'mode', '')));
  begin
    v_published_at := (p_article ->> 'publishedAt')::timestamptz;
    v_matchday := (p_article ->> 'matchdayId')::uuid;
  exception when others then
    raise exception 'mesa-publication-article-invalid';
  end;
  if v_article_id is null or v_published_at is null
    or v_slug = '' or v_label = '' or v_title = '' or v_subtitle = '' or v_body = '' or v_author = ''
    or v_mode not in ('create', 'update') then
    raise exception 'mesa-publication-article-invalid';
  end if;

  v_payload := jsonb_build_object(
    'article', jsonb_build_object(
      'id', v_article_id, 'slug', v_slug, 'label', v_label, 'title', v_title,
      'subtitle', v_subtitle, 'body', v_body, 'imageUrl', v_image, 'author', v_author,
      'publishedAt', v_published_at, 'matchdayId', v_matchday, 'mode', v_mode
    ),
    'sources', (select to_jsonb(array_agg(source_id order by source_id)) from unnest(p_dossier_source_ids) source_id),
    'packageId', p_package_id,
    'outputId', p_output_id,
    'sourceScope', v_source_scope
  ) || case when v_source_scope = 'context'
    then jsonb_build_object('contextId', v_production_context_id)
    else '{}'::jsonb end;
  v_fingerprint := md5(v_payload::text);

  select * into v_existing from public.newsroom_mesa_output_publications publication
    where publication.dossier_id = p_dossier_id and publication.article_plan_id = p_output_id;
  if found then
    if v_existing.fingerprint <> v_fingerprint or v_existing.editorial_article_id <> v_article_id
      or v_existing.source_scope is distinct from v_source_scope
      or v_existing.production_context_id is distinct from v_production_context_id
      or not exists(select 1 from public.editorial_articles article
        where article.id = v_article_id and article.status = 'published') then
      raise exception 'mesa-publication-provenance-conflict';
    end if;
    -- Retry never overwrites a later manual edit, even after the first write.
    select to_jsonb(a) into v_current from public.editorial_articles a where a.id=v_article_id for update;
    if encode(sha256(convert_to(v_current::text,'UTF8')),'hex')
        is distinct from v_existing.payload ->> 'intentResultFingerprint' then
      raise exception 'mesa-intent-published-result-stale';
    end if;
    return query select v_article_id, v_slug, 'reused'::text,
      v_context.workspace_state = 'consolidated';
    return;
  end if;
  if v_context.workspace_state = 'consolidated' then
    raise exception 'mesa-publication-provenance-conflict';
  end if;

  if v_mode = 'create' then
    if v_slot ->> 'kind' <> 'new' or v_matchday is null
      or v_plan.destination <> 'new' or v_plan.update_target_editorial_article_id is not null
      or v_image is null
      or exists(select 1 from public.editorial_articles article
        where article.id = v_article_id or article.slug = v_slug) then
      raise exception 'mesa-publication-article-conflict';
    end if;
    insert into public.editorial_articles(
      id, status, scope, author, label, title, subtitle, body, slug, image_url,
      image_caption, published_at, competition_id, season_id, matchday_id, created_at, updated_at
    ) values (
      v_article_id, 'published', 'matchday', v_author, v_label, v_title, v_subtitle,
      v_body, v_slug, v_image, null, v_published_at, null, null, v_matchday, v_now, v_now
    );
  else
    if v_slot ->> 'kind' <> 'existing' or v_plan.destination <> 'update'
      or v_plan.update_target_editorial_article_id is distinct from v_article_id
      or v_expected ->> 'editorialArticleId' is distinct from v_article_id::text
      or v_expected ->> 'slug' is distinct from v_slug
      or (v_expected ->> 'matchdayId')::uuid is distinct from v_matchday then
      raise exception 'mesa-publication-update-target-invalid';
    end if;
    select to_jsonb(article), article.slug into v_current, v_previous_slug
      from public.editorial_articles article
      where article.id=v_article_id and article.status='published' for update;
    if not found or encode(sha256(convert_to(v_current::text,'UTF8')),'hex')
        is distinct from v_expected ->> 'contentFingerprint' then
      raise exception 'mesa-intent-update-target-stale';
    end if;
    -- Preserve scope, competition, season, matchday (including NULL), slug,
    -- publication date, caption and all other non-editorial identity fields.
    update public.editorial_articles article
      set label=v_label, title=v_title, subtitle=v_subtitle, body=v_body,
        author=v_author, image_url=coalesce(v_image,article.image_url), updated_at=v_now
      where article.id=v_article_id and article.status='published'
        and article.matchday_id is not distinct from v_matchday and article.slug=v_slug;
    if not found then raise exception 'mesa-publication-update-target-invalid'; end if;
  end if;

  insert into public.newsroom_mesa_output_publications(
    dossier_id, article_plan_id, package_id, editorial_article_id, source_scope,
    production_context_id, origin_kind, origin_dossier_source_id, material_key,
    material_version_id, fingerprint, payload
  ) values (
    p_dossier_id, p_output_id, p_package_id, v_article_id, v_source_scope,
    v_production_context_id, null, null, null, null, v_fingerprint,
    v_payload || jsonb_build_object('intentResultFingerprint',(
      select encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')
      from public.editorial_articles a where a.id=v_article_id
    ))
  );
  insert into public.newsroom_mesa_output_source_usage(
    dossier_id, article_plan_id, dossier_source_id, newsroom_article_id,
    newsroom_snapshot_id, editorial_article_id, package_id
  ) select p_dossier_id, p_output_id, dossier_source.id, dossier_source.newsroom_article_id,
      dossier_source.newsroom_snapshot_id, v_article_id, p_package_id
    from public.newsroom_editorial_dossier_sources dossier_source
    where dossier_source.dossier_id = p_dossier_id
      and dossier_source.id = any(p_dossier_source_ids);
  update public.newsroom_editorial_dossier_article_plans plan
    set editorial_article_id = v_article_id, updated_at = v_now
    where plan.dossier_id = p_dossier_id and plan.id = p_output_id
      and plan.editorial_article_id is null;
  if not found then raise exception 'mesa-publication-output-conflict'; end if;
  v_consolidated := false; -- only the explicit intent finalizer completes this cycle
  if v_mode = 'update' then
    perform * from public.sync_editorial_article_live_snapshots_v15(v_article_id, v_previous_slug);
  end if;
  return query select v_article_id, v_slug,
    case when v_mode = 'update' then 'updated' else 'created' end, v_consolidated;
end;
$function$;

revoke all on function public.newsroom_publish_mesa_intent_output_v1(uuid, uuid, uuid, uuid[], jsonb)
  from public, anon, authenticated, service_role;
grant execute on function public.newsroom_publish_mesa_intent_output_v1(uuid, uuid, uuid, uuid[], jsonb)
  to service_role;

-- Atomic Latest projection for the opt-in circuit only. The old publication
-- paths keep their existing writer. Workspace and matchday locks close the
-- read/insert race between identical or overlapping publication attempts.
create function public.newsroom_place_mesa_intent_latest_v1(
  p_dossier_id uuid, p_package_id uuid, p_article_ids uuid[]
)
returns table(result jsonb) language plpgsql volatile security definer set search_path='' as $function$
declare
  v_plan jsonb; v_expected uuid[]; v_requested uuid[]; v_days uuid[];
  v_day uuid; v_article public.editorial_articles%rowtype; v_existing uuid;
  v_count integer; v_path text; v_label text; v_now timestamptz:=clock_timestamp();
begin
  if p_article_ids is null or cardinality(p_article_ids) not between 1 and 30
    or array_position(p_article_ids,null) is not null
    or (select count(distinct x) from unnest(p_article_ids) x)<>cardinality(p_article_ids) then
    raise exception 'mesa-intent-latest-input-invalid';
  end if;
  v_plan:=public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  select array_agg(x order by x) into v_requested from unnest(p_article_ids) x;
  select array_agg(a.id order by a.id) into v_expected
    from public.newsroom_mesa_output_publications p
    join public.editorial_articles a on a.id=p.editorial_article_id
    where p.dossier_id=p_dossier_id and p.package_id=p_package_id and a.matchday_id is not null;
  if v_requested is distinct from v_expected then
    raise exception 'mesa-intent-latest-article-set-invalid';
  end if;
  -- Lock canonical rows in the same order as the finalizer. Never use text or
  -- article identity supplied by a client to construct the public projection.
  perform 1 from public.editorial_articles a where a.id=any(v_requested) order by a.id for update;
  if exists (select 1 from public.newsroom_mesa_output_publications p
      join public.editorial_articles a on a.id=p.editorial_article_id
      where p.dossier_id=p_dossier_id and a.id=any(v_requested)
        and (a.status<>'published' or encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')
          is distinct from p.payload->>'intentResultFingerprint')) then
    raise exception 'mesa-intent-published-result-stale';
  end if;
  select array_agg(distinct a.matchday_id order by a.matchday_id) into v_days
    from public.editorial_articles a where a.id=any(v_requested);
  -- A completed replay is not permission to restore a later manually removed
  -- Latest entry. The immutable completion is returned without further writes.
  if exists (select 1 from public.newsroom_mesa_intent_finalizations f
      where f.dossier_id=p_dossier_id and f.package_id=p_package_id) then
    return query select jsonb_build_object('action','reused','articleCount',cardinality(v_requested),'matchdayCount',cardinality(v_days));
    return;
  end if;
  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();
  perform 1 from public.matchdays d where d.id=any(v_days) order by d.id for update;
  for v_article in select * from public.editorial_articles a where a.id=any(v_requested) order by a.matchday_id,a.id loop
    if v_article.published_at is null or exists(select 1 from unnest(array[
        v_article.slug,v_article.label,v_article.title,v_article.subtitle,v_article.body,v_article.image_url,v_article.author
      ]) field where nullif(btrim(field),'') is null) then
      raise exception 'mesa-intent-latest-article-incomplete';
    end if;
    v_path:='/noticias/'||btrim(v_article.slug);
    -- Equivalent to projectEditorialArticleToZone(article, 'editorial_line_item').
    v_label:=to_char(v_article.published_at at time zone 'Europe/Lisbon','HH24:MI')||' · '||btrim(v_article.label);
    select count(*),min(n.id::text)::uuid into v_count,v_existing
      from public.matchday_latest_news n
      where n.matchday_id=v_article.matchday_id and btrim(n.link_url)=v_path;
    if v_count>1 then raise exception 'mesa-intent-latest-existing-duplicate'; end if;
    if v_existing is not null then
      update public.matchday_latest_news set time_label=v_label,time_label_color=null,
        title=btrim(v_article.title),subtitle=null,image_url=null,link_url=v_path,
        article_id=null,status='published',updated_at=v_now where id=v_existing;
    else
      insert into public.matchday_latest_news(matchday_id,time_label,time_label_color,title,subtitle,
        image_url,link_url,article_id,status,sort_order,created_at,updated_at)
      select v_article.matchday_id,v_label,null,btrim(v_article.title),null,null,v_path,null,'published',
        coalesce(max(n.sort_order),0)+1,v_now,v_now
      from public.matchday_latest_news n where n.matchday_id=v_article.matchday_id;
    end if;
  end loop;
  foreach v_day in array v_days loop
    perform * from public.set_matchday_latest_news_settings_v15(v_day,'latest_news',null,null,false);
    perform public.normalize_matchday_latest_news_order(v_day);
  end loop;
  return query select jsonb_build_object('action','placed','articleCount',cardinality(v_requested),'matchdayCount',cardinality(v_days));
end;
$function$;
revoke all on function public.newsroom_place_mesa_intent_latest_v1(uuid,uuid,uuid[]) from public,anon,authenticated,service_role;
grant execute on function public.newsroom_place_mesa_intent_latest_v1(uuid,uuid,uuid[]) to service_role;

-- Complete only the exact requested cycle. A partial publication has no receipts
-- and stays active. SEM ALTERAÇÃO is an explicit checked decision, not an output.
create function public.newsroom_finalize_mesa_intents_v1(
  p_dossier_id uuid,p_package_id uuid,p_no_change_output_ids uuid[]
)
returns table(result jsonb) language plpgsql volatile security definer set search_path='' as $function$
declare
  v_plan jsonb; v_output jsonb; v_context jsonb; v_article jsonb; v_article_id uuid;
  v_written public.newsroom_mesa_output_publications%rowtype;
  v_final public.newsroom_mesa_intent_finalizations%rowtype;
  v_no_change uuid[]; v_receipts jsonb:='[]'; v_decisions jsonb:='[]';
  v_decision text; v_fingerprint text; v_event uuid; v_payload jsonb;
  v_updated integer:=0; v_new integer:=0; v_unchanged integer:=0;
  v_group record; v_version uuid; v_key text; v_completed timestamptz;
begin
  if p_dossier_id is null or p_package_id is null or p_no_change_output_ids is null
    or cardinality(p_no_change_output_ids)>30 or array_position(p_no_change_output_ids,null) is not null
    or (select count(distinct x) from unnest(p_no_change_output_ids) x)<>cardinality(p_no_change_output_ids) then
    raise exception 'mesa-intent-finalization-input-invalid';
  end if;
  select coalesce(array_agg(x order by x),'{}'::uuid[]) into v_no_change from unnest(p_no_change_output_ids) x;
  -- Completed replay is a historical fact, not a request to overwrite a later
  -- edit. Lock the same workspace as the writer before checking it.
  perform 1 from public.newsroom_mesa_production_contexts w where w.dossier_id=p_dossier_id for update;
  select * into v_final from public.newsroom_mesa_intent_finalizations f where f.dossier_id=p_dossier_id;
  if found then
    if v_final.package_id<>p_package_id or v_final.no_change_output_ids is distinct from v_no_change then
      raise exception 'mesa-intent-finalization-conflict';
    end if;
    return query select jsonb_build_object('action','reused','publicationEventId',v_final.publication_event_id,
      'updatedCount',v_final.updated_count,'newCount',v_final.new_count,'noChangeCount',v_final.no_change_count);
    return;
  end if;
  v_plan:=public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  if exists (select 1 from public.newsroom_mesa_production_contexts w
    where w.dossier_id=p_dossier_id and w.workspace_state<>'active') then
    raise exception 'mesa-intent-finalization-state-invalid';
  end if;
  if exists (select 1 from unnest(v_no_change) id where not exists (
      select 1 from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'outputId'=id::text and o ->> 'kind'='existing'))
    or exists (select 1 from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id and not exists (
      select 1 from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'outputId'=p.article_plan_id::text)) then
    raise exception 'mesa-intent-finalization-decision-invalid';
  end if;
  perform 1 from public.editorial_articles a where a.id in (
    select (o -> 'target' ->> 'editorialArticleId')::uuid from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'kind'='existing'
    union select p.editorial_article_id from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id
  ) order by a.id for update;
  for v_output in select value from jsonb_array_elements(v_plan -> 'outputs') loop
    select c into strict v_context from jsonb_array_elements(v_plan -> 'contexts') c where c ->> 'key'=v_output ->> 'contextKey';
    if (v_output ->> 'outputId')::uuid=any(v_no_change) then
      if exists (select 1 from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id and p.article_plan_id=(v_output ->> 'outputId')::uuid) then
        raise exception 'mesa-intent-no-change-already-published';
      end if;
      v_article_id:=(v_output -> 'target' ->> 'editorialArticleId')::uuid;
      select to_jsonb(a) into v_article from public.editorial_articles a where a.id=v_article_id and a.status='published';
      if not found or encode(sha256(convert_to(v_article::text,'UTF8')),'hex')
          is distinct from v_output -> 'target' ->> 'contentFingerprint' then
        raise exception 'mesa-intent-no-change-target-stale';
      end if;
      v_decision:='SEM_ALTERAÇÃO'; v_unchanged:=v_unchanged+1;
    else
      select * into v_written from public.newsroom_mesa_output_publications p
        where p.dossier_id=p_dossier_id and p.article_plan_id=(v_output ->> 'outputId')::uuid;
      if not found then raise exception 'mesa-intent-publication-incomplete'; end if;
      if v_written.package_id<>p_package_id or v_written.source_scope is distinct from 'context'
        or v_written.production_context_id is distinct from (v_context ->> 'productionContextId')::uuid
        or (v_output ->> 'kind'='existing' and v_written.editorial_article_id is distinct from (v_output -> 'target' ->> 'editorialArticleId')::uuid) then
        raise exception 'mesa-intent-publication-output-invalid';
      end if;
      v_article_id:=v_written.editorial_article_id;
      select to_jsonb(a) into v_article from public.editorial_articles a where a.id=v_article_id and a.status='published';
      if not found or encode(sha256(convert_to(v_article::text,'UTF8')),'hex') is distinct from v_written.payload ->> 'intentResultFingerprint' then
        raise exception 'mesa-intent-published-result-stale';
      end if;
      if not exists (select 1 from public.newsroom_editorial_dossier_article_plans p
        where p.id=v_written.article_plan_id and p.dossier_id=p_dossier_id and p.editorial_article_id=v_article_id) then
        raise exception 'mesa-intent-publication-output-invalid';
      end if;
      v_decision:=case when v_output ->> 'kind'='existing' then 'UPDATE' else 'NEW' end;
      if v_decision='UPDATE' then v_updated:=v_updated+1; else v_new:=v_new+1; end if;
    end if;
    v_fingerprint:=encode(sha256(convert_to(v_article::text,'UTF8')),'hex');
    v_decisions:=v_decisions||jsonb_build_array(jsonb_build_object('slot',v_output -> 'slot',
      'outputId',v_output -> 'outputId','contextKey',v_output -> 'contextKey',
      'decision',v_decision,'articleId',v_article_id,'resultFingerprint',v_fingerprint));
    if v_context ->> 'themeId' is not null then
      v_receipts:=v_receipts||jsonb_build_array(jsonb_build_object('themeId',v_context -> 'themeId',
        'articleId',v_article_id,'outputId',v_output -> 'outputId','slot',v_output -> 'slot',
        'decision',v_decision,'sources',v_context -> 'sources','resultFingerprint',v_fingerprint));
    end if;
  end loop;
  v_payload:=jsonb_build_object('contractVersion',1,'kind','mesa_production_intents',
    'packageId',p_package_id,'authorityFingerprint',v_plan -> 'authorityFingerprint',
    'capturedAt',v_plan -> 'capturedAt','decisions',v_decisions);
  insert into public.newsroom_mesa_publication_events(dossier_id,fingerprint,payload)
    values(p_dossier_id,md5(v_payload::text),v_payload) returning id into v_event;
  v_completed:=clock_timestamp();
  insert into public.newsroom_mesa_intent_finalizations(dossier_id,package_id,publication_event_id,
    no_change_output_ids,updated_count,new_count,no_change_count,completed_at)
    values(p_dossier_id,p_package_id,v_event,v_no_change,v_updated,v_new,v_unchanged,v_completed);
  insert into public.newsroom_mesa_intent_article_receipts(dossier_id,output_id,theme_id,editorial_article_id,
    slot,decision,captured_at,completed_at,sources,result_fingerprint)
    select p_dossier_id,(r ->> 'outputId')::uuid,(r ->> 'themeId')::uuid,(r ->> 'articleId')::uuid,
      r ->> 'slot',r ->> 'decision',(v_plan ->> 'capturedAt')::timestamptz,v_completed,r -> 'sources',r ->> 'resultFingerprint'
    from jsonb_array_elements(v_receipts) r;
  -- Preserve technical material projection, but group by context as well as
  -- sources. Equal source sets in different Themes must never merge their work.
  for v_group in
    select x.production_context_id,x.source_refs,array_agg(x.article_id order by x.article_id) article_ids,
      min(x.article_plan_id::text)::uuid key_plan_id
    from (
      select p.production_context_id,u.article_plan_id,min(u.editorial_article_id::text)::uuid article_id,
        public.newsroom_mesa_normalize_refs_v2(jsonb_agg(jsonb_build_object(
          'newsroomArticleId',u.newsroom_article_id,'newsroomSnapshotId',u.newsroom_snapshot_id)
          order by u.newsroom_article_id,u.newsroom_snapshot_id)) source_refs
      from public.newsroom_mesa_output_source_usage u
      join public.newsroom_mesa_output_publications p on p.dossier_id=u.dossier_id and p.article_plan_id=u.article_plan_id
      where u.dossier_id=p_dossier_id group by p.production_context_id,u.article_plan_id having count(*)>=2
    ) x group by x.production_context_id,x.source_refs
  loop
    select c into strict v_context from jsonb_array_elements(v_plan -> 'contexts') c
      where c ->> 'productionContextId'=v_group.production_context_id::text;
    v_key:='output:'||v_group.key_plan_id::text;
    insert into public.newsroom_mesa_material_versions(material_key,title,source_refs,article_ids,production_dossier_id,publication_event_id)
      values(v_key,v_context ->> 'title',v_group.source_refs,v_group.article_ids,p_dossier_id,v_event) returning id into v_version;
    if v_context ->> 'themeId' is not null then
      insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
        values((v_context ->> 'themeId')::uuid,v_key,v_version) on conflict do nothing;
    end if;
  end loop;
  insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
    select (r ->> 'themeId')::uuid,(r ->> 'articleId')::uuid from jsonb_array_elements(v_receipts) r
    on conflict(theme_id,editorial_article_id) do nothing;
  update public.newsroom_mesa_production_contexts set workspace_state='consolidated',consolidated_at=v_completed where dossier_id=p_dossier_id;
  return query select jsonb_build_object('action','consolidated','publicationEventId',v_event,
    'updatedCount',v_updated,'newCount',v_new,'noChangeCount',v_unchanged);
end;
$function$;
revoke all on function public.newsroom_finalize_mesa_intents_v1(uuid,uuid,uuid[]) from public,anon,authenticated,service_role;
grant execute on function public.newsroom_finalize_mesa_intents_v1(uuid,uuid,uuid[]) to service_role;

-- Only the most recent capture(s) per article are returned. Keeping all ties
-- lets the caller label ambiguous history UNKNOWN rather than inventing review.
create function public.newsroom_mesa_intent_latest_receipts_v1(p_theme_id uuid)
returns table(receipts jsonb) language sql stable security definer set search_path='' as $function$
  select coalesce(jsonb_agg(jsonb_build_object('contextKey','theme:'||r.theme_id::text,
    'themeId',r.theme_id,'articleId',r.editorial_article_id,'slot',r.slot,'decision',r.decision,
    'capturedAt',to_char(r.captured_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'sources',r.sources) order by r.editorial_article_id,r.dossier_id),'[]')
  from (select x.*,rank() over(partition by x.editorial_article_id order by x.captured_at desc) capture_rank
    from public.newsroom_mesa_intent_article_receipts x where x.theme_id=p_theme_id) r
  where r.capture_rank=1;
$function$;
revoke all on function public.newsroom_mesa_intent_latest_receipts_v1(uuid) from public,anon,authenticated,service_role;
grant execute on function public.newsroom_mesa_intent_latest_receipts_v1(uuid) to service_role;
notify pgrst,'reload schema';
commit;

-- Hotfix: an UPDATE revises an existing canonical article. It must not
-- claim the globally unique editorial_article_id link already owned by the
-- Article Plan that originally created that article.
begin;

do $preflight$
declare
  v_definition text;
begin
  if to_regprocedure('public.newsroom_publish_mesa_intent_output_v1(uuid,uuid,uuid,uuid[],jsonb)') is null then
    raise exception 'mesa-intent-update-revision-hotfix-publisher-missing';
  end if;
  if to_regprocedure('public.newsroom_finalize_mesa_intents_v1(uuid,uuid,uuid[])') is null then
    raise exception 'mesa-intent-update-revision-hotfix-finalizer-missing';
  end if;
  select pg_get_functiondef('public.newsroom_publish_mesa_intent_output_v1(uuid,uuid,uuid,uuid[],jsonb)'::regprocedure)
    into v_definition;
  if strpos(v_definition, 'set editorial_article_id = v_article_id, updated_at = v_now') = 0 then
    raise exception 'mesa-intent-update-revision-hotfix-unexpected-publisher';
  end if;
  if to_regclass('public.newsroom_editorial_dossier_article_plans') is null
    or to_regclass('public.newsroom_mesa_output_publications') is null then
    raise exception 'mesa-intent-update-revision-hotfix-schema-missing';
  end if;
end;
$preflight$;

create or replace function public.newsroom_publish_mesa_intent_output_v1(
  p_dossier_id uuid,
  p_output_id uuid,
  p_package_id uuid,
  p_dossier_source_ids uuid[],
  p_article jsonb
)
returns table(
  editorial_article_id uuid,
  article_slug text,
  publication_action text,
  consolidated boolean
)
language plpgsql security definer set search_path = '' as $function$
declare
  v_intent jsonb; v_slot jsonb; v_expected jsonb; v_current jsonb;
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_plan public.newsroom_editorial_dossier_article_plans%rowtype;
  v_manifest jsonb; v_manifest_output jsonb;
  v_existing public.newsroom_mesa_output_publications%rowtype;
  v_article_id uuid; v_slug text; v_label text; v_title text; v_subtitle text; v_body text;
  v_image text; v_author text; v_published_at timestamptz; v_matchday uuid; v_mode text;
  v_previous_slug text; v_source_scope text := 'workspace'; v_production_context_id uuid;
  v_declared_context_source_ids uuid[]; v_frozen_context_source_ids uuid[];
  v_is_2c boolean;
  v_payload jsonb; v_fingerprint text; v_consolidated boolean; v_now timestamptz := now();
begin
  if p_dossier_id is null or p_output_id is null or p_package_id is null
    or p_dossier_source_ids is null or cardinality(p_dossier_source_ids) < 1
    or cardinality(p_dossier_source_ids) > 20 or array_position(p_dossier_source_ids, null) is not null
    or (select count(distinct source_id) from unnest(p_dossier_source_ids) source_id) <> cardinality(p_dossier_source_ids)
    or p_article is null or jsonb_typeof(p_article) <> 'object' then
    raise exception 'mesa-publication-input-invalid';
  end if;

  -- All intent writers/finalizers acquire the workspace first, then canonical
  -- articles in ID order. Publication never calls the generic consolidator.
  v_intent := public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  select o into v_slot from jsonb_array_elements(v_intent -> 'outputs') o
    where o ->> 'outputId' = p_output_id::text;
  if not found then raise exception 'mesa-intent-output-invalid'; end if;
  v_expected := v_slot -> 'target';
  select * into v_context from public.newsroom_mesa_production_contexts context
    where context.dossier_id = p_dossier_id for update;
  if not found or v_context.workspace_role <> 'technical' or v_context.workspace_contract_version <> 2
    or v_context.workspace_state not in ('active', 'consolidated') then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  v_is_2c := coalesce(
    v_context.selection_payload ->> 'contractVersion' = '3'
      and v_context.selection_payload ->> 'contextContractVersion' = '1',
    false
  );
  if coalesce(
    v_context.selection_payload ->> 'contractVersion' = '3'
      or v_context.selection_payload ? 'contextContractVersion',
    false
  ) and not v_is_2c then
    raise exception 'mesa-publication-workspace-invalid';
  end if;
  if v_is_2c is distinct from (exists (
      select 1 from public.newsroom_mesa_production_context_items context_item
      where context_item.dossier_id = p_dossier_id
    )) then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  select * into v_plan from public.newsroom_editorial_dossier_article_plans plan
    where plan.dossier_id = p_dossier_id and plan.id = p_output_id
      and plan.status <> 'cancelled' for update;
  if not found then raise exception 'mesa-publication-output-invalid'; end if;

  if v_is_2c then
    select assignment.production_context_id
    into v_production_context_id
    from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id = p_dossier_id
      and assignment.article_plan_id = p_output_id;
    if not found or not public.newsroom_mesa_plan_context_sources_valid_v1(
      p_dossier_id, p_output_id, v_production_context_id
    ) then
      raise exception 'mesa-publication-output-invalid';
    end if;
    v_source_scope := 'context';
  elsif exists (
    select 1 from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id = p_dossier_id
      and assignment.article_plan_id = p_output_id
  ) then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  select package.manifest into v_manifest from public.newsroom_editorial_source_packages package
    where package.id = p_package_id for update;
  if not found or (v_manifest ->> 'version')::integer <> 5
    or v_manifest ->> 'provenanceContract' <> 'mesa-v2' then
    raise exception 'mesa-publication-package-invalid';
  end if;

  select output.value into v_manifest_output
  from jsonb_array_elements(v_manifest -> 'outputs') output(value)
  where lower(output.value ->> 'outputId') = p_output_id::text
    and lower(output.value -> 'articlePlan' ->> 'articlePlanId') = p_output_id::text
    and lower(output.value -> 'articlePlan' ->> 'dossierId') = p_dossier_id::text;
  if not found
    or v_manifest_output -> 'articlePlan' ->> 'sourceScope' is distinct from v_source_scope
    or v_manifest_output -> 'articlePlan' ? 'origin' then
    raise exception 'mesa-publication-package-invalid';
  end if;

  if v_source_scope = 'context' then
    if lower(v_manifest_output -> 'articlePlan' ->> 'contextId')
      is distinct from v_production_context_id::text
      or jsonb_typeof(v_manifest_output -> 'contextSourceIds') is distinct from 'array'
    then
      raise exception 'mesa-publication-package-invalid';
    end if;
    begin
      select array_agg((source_id.value #>> '{}')::uuid order by (source_id.value #>> '{}')::uuid)
      into v_declared_context_source_ids
      from jsonb_array_elements(v_manifest_output -> 'contextSourceIds') source_id(value);
    exception when others then
      raise exception 'mesa-publication-package-invalid';
    end;
    select array_agg(context_source.dossier_source_id order by context_source.dossier_source_id)
    into v_frozen_context_source_ids
    from public.newsroom_mesa_production_context_sources context_source
    where context_source.dossier_id = p_dossier_id
      and context_source.production_context_id = v_production_context_id;
    if v_declared_context_source_ids is distinct from v_frozen_context_source_ids
      or exists (
        select 1 from unnest(p_dossier_source_ids) requested(id)
        where not (requested.id = any(v_frozen_context_source_ids))
      )
    then
      raise exception 'mesa-publication-source-invalid';
    end if;
  end if;

  if exists(select 1 from unnest(p_dossier_source_ids) requested(id)
    left join public.newsroom_editorial_dossier_sources dossier_source
      on dossier_source.id = requested.id
      and dossier_source.dossier_id = p_dossier_id
      and dossier_source.included
    where dossier_source.id is null
      or not exists(select 1 from jsonb_array_elements(v_context.source_refs) ref
        where lower(ref ->> 'newsroomArticleId') = dossier_source.newsroom_article_id::text
          and lower(ref ->> 'newsroomSnapshotId') = dossier_source.newsroom_snapshot_id::text)
      or not exists(select 1 from jsonb_array_elements(v_manifest -> 'entries') entry
        where entry ->> 'status' = 'prepared'
          and lower(entry ->> 'provenanceSourceId') = requested.id::text
          and lower(entry ->> 'newsroomArticleId') = dossier_source.newsroom_article_id::text
          and lower(entry ->> 'newsroomSnapshotId') = dossier_source.newsroom_snapshot_id::text)
  ) then raise exception 'mesa-publication-source-invalid'; end if;

  begin
    v_article_id := (p_article ->> 'id')::uuid;
  exception when others then
    raise exception 'mesa-publication-article-invalid';
  end;
  v_slug := btrim(coalesce(p_article ->> 'slug', ''));
  v_label := btrim(coalesce(p_article ->> 'label', ''));
  v_title := btrim(coalesce(p_article ->> 'title', ''));
  v_subtitle := btrim(coalesce(p_article ->> 'subtitle', ''));
  v_body := btrim(coalesce(p_article ->> 'body', ''));
  v_image := nullif(btrim(coalesce(p_article ->> 'imageUrl', '')), '');
  v_author := btrim(coalesce(p_article ->> 'author', ''));
  v_mode := lower(btrim(coalesce(p_article ->> 'mode', '')));
  begin
    v_published_at := (p_article ->> 'publishedAt')::timestamptz;
    v_matchday := (p_article ->> 'matchdayId')::uuid;
  exception when others then
    raise exception 'mesa-publication-article-invalid';
  end;
  if v_article_id is null or v_published_at is null
    or v_slug = '' or v_label = '' or v_title = '' or v_subtitle = '' or v_body = '' or v_author = ''
    or v_mode not in ('create', 'update') then
    raise exception 'mesa-publication-article-invalid';
  end if;

  v_payload := jsonb_build_object(
    'article', jsonb_build_object(
      'id', v_article_id, 'slug', v_slug, 'label', v_label, 'title', v_title,
      'subtitle', v_subtitle, 'body', v_body, 'imageUrl', v_image, 'author', v_author,
      'publishedAt', v_published_at, 'matchdayId', v_matchday, 'mode', v_mode
    ),
    'sources', (select to_jsonb(array_agg(source_id order by source_id)) from unnest(p_dossier_source_ids) source_id),
    'packageId', p_package_id,
    'outputId', p_output_id,
    'sourceScope', v_source_scope
  ) || case when v_source_scope = 'context'
    then jsonb_build_object('contextId', v_production_context_id)
    else '{}'::jsonb end;
  v_fingerprint := md5(v_payload::text);

  select * into v_existing from public.newsroom_mesa_output_publications publication
    where publication.dossier_id = p_dossier_id and publication.article_plan_id = p_output_id;
  if found then
    if v_existing.fingerprint <> v_fingerprint or v_existing.editorial_article_id <> v_article_id
      or v_existing.source_scope is distinct from v_source_scope
      or v_existing.production_context_id is distinct from v_production_context_id
      or not exists(select 1 from public.editorial_articles article
        where article.id = v_article_id and article.status = 'published') then
      raise exception 'mesa-publication-provenance-conflict';
    end if;
    -- Retry never overwrites a later manual edit, even after the first write.
    select to_jsonb(a) into v_current from public.editorial_articles a where a.id=v_article_id for update;
    if encode(sha256(convert_to(v_current::text,'UTF8')),'hex')
        is distinct from v_existing.payload ->> 'intentResultFingerprint' then
      raise exception 'mesa-intent-published-result-stale';
    end if;
    return query select v_article_id, v_slug, 'reused'::text,
      v_context.workspace_state = 'consolidated';
    return;
  end if;
  if v_context.workspace_state = 'consolidated' then
    raise exception 'mesa-publication-provenance-conflict';
  end if;

  if v_mode = 'create' then
    if v_slot ->> 'kind' <> 'new' or v_matchday is null
      or v_plan.destination <> 'new' or v_plan.update_target_editorial_article_id is not null
      or v_image is null
      or exists(select 1 from public.editorial_articles article
        where article.id = v_article_id or article.slug = v_slug) then
      raise exception 'mesa-publication-article-conflict';
    end if;
    insert into public.editorial_articles(
      id, status, scope, author, label, title, subtitle, body, slug, image_url,
      image_caption, published_at, competition_id, season_id, matchday_id, created_at, updated_at
    ) values (
      v_article_id, 'published', 'matchday', v_author, v_label, v_title, v_subtitle,
      v_body, v_slug, v_image, null, v_published_at, null, null, v_matchday, v_now, v_now
    );
  else
    if v_slot ->> 'kind' <> 'existing' or v_plan.destination <> 'update'
      or v_plan.update_target_editorial_article_id is distinct from v_article_id
      or v_expected ->> 'editorialArticleId' is distinct from v_article_id::text
      or v_expected ->> 'slug' is distinct from v_slug
      or (v_expected ->> 'matchdayId')::uuid is distinct from v_matchday then
      raise exception 'mesa-publication-update-target-invalid';
    end if;
    select to_jsonb(article), article.slug into v_current, v_previous_slug
      from public.editorial_articles article
      where article.id=v_article_id and article.status='published' for update;
    if not found or encode(sha256(convert_to(v_current::text,'UTF8')),'hex')
        is distinct from v_expected ->> 'contentFingerprint' then
      raise exception 'mesa-intent-update-target-stale';
    end if;
    -- Preserve scope, competition, season, matchday (including NULL), slug,
    -- publication date, caption and all other non-editorial identity fields.
    update public.editorial_articles article
      set label=v_label, title=v_title, subtitle=v_subtitle, body=v_body,
        author=v_author, image_url=coalesce(v_image,article.image_url), updated_at=v_now
      where article.id=v_article_id and article.status='published'
        and article.matchday_id is not distinct from v_matchday and article.slug=v_slug;
    if not found then raise exception 'mesa-publication-update-target-invalid'; end if;
  end if;

  insert into public.newsroom_mesa_output_publications(
    dossier_id, article_plan_id, package_id, editorial_article_id, source_scope,
    production_context_id, origin_kind, origin_dossier_source_id, material_key,
    material_version_id, fingerprint, payload
  ) values (
    p_dossier_id, p_output_id, p_package_id, v_article_id, v_source_scope,
    v_production_context_id, null, null, null, null, v_fingerprint,
    v_payload || jsonb_build_object('intentResultFingerprint',(
      select encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')
      from public.editorial_articles a where a.id=v_article_id
    ))
  );
  insert into public.newsroom_mesa_output_source_usage(
    dossier_id, article_plan_id, dossier_source_id, newsroom_article_id,
    newsroom_snapshot_id, editorial_article_id, package_id
  ) select p_dossier_id, p_output_id, dossier_source.id, dossier_source.newsroom_article_id,
      dossier_source.newsroom_snapshot_id, v_article_id, p_package_id
    from public.newsroom_editorial_dossier_sources dossier_source
    where dossier_source.dossier_id = p_dossier_id
      and dossier_source.id = any(p_dossier_source_ids);
  -- NEW materializes a new canonical article and therefore owns the
  -- one-to-one Article Plan -> editorial_article_id link. UPDATE is a revision
  -- of an article that may already be owned by its original creation plan; the
  -- revision is linked through newsroom_mesa_output_publications and receipts.
  if v_mode = 'create' then
    update public.newsroom_editorial_dossier_article_plans plan
      set editorial_article_id = v_article_id, updated_at = v_now
      where plan.dossier_id = p_dossier_id and plan.id = p_output_id
        and plan.editorial_article_id is null;
    if not found then raise exception 'mesa-publication-output-conflict'; end if;
  elsif exists (
    select 1
    from public.newsroom_editorial_dossier_article_plans plan
    where plan.dossier_id = p_dossier_id
      and plan.id = p_output_id
      and plan.editorial_article_id is not null
      and plan.editorial_article_id is distinct from v_article_id
  ) then
    raise exception 'mesa-publication-output-conflict';
  end if;
  v_consolidated := false; -- only the explicit intent finalizer completes this cycle
  if v_mode = 'update' then
    perform * from public.sync_editorial_article_live_snapshots_v15(v_article_id, v_previous_slug);
  end if;
  return query select v_article_id, v_slug,
    case when v_mode = 'update' then 'updated' else 'created' end, v_consolidated;
end;
$function$;

revoke all on function public.newsroom_publish_mesa_intent_output_v1(uuid, uuid, uuid, uuid[], jsonb)
  from public, anon, authenticated, service_role;
grant execute on function public.newsroom_publish_mesa_intent_output_v1(uuid, uuid, uuid, uuid[], jsonb)
  to service_role;


create or replace function public.newsroom_finalize_mesa_intents_v1(
  p_dossier_id uuid,p_package_id uuid,p_no_change_output_ids uuid[]
)
returns table(result jsonb) language plpgsql volatile security definer set search_path='' as $function$
declare
  v_plan jsonb; v_output jsonb; v_context jsonb; v_article jsonb; v_article_id uuid;
  v_written public.newsroom_mesa_output_publications%rowtype;
  v_final public.newsroom_mesa_intent_finalizations%rowtype;
  v_no_change uuid[]; v_receipts jsonb:='[]'; v_decisions jsonb:='[]';
  v_decision text; v_fingerprint text; v_event uuid; v_payload jsonb;
  v_updated integer:=0; v_new integer:=0; v_unchanged integer:=0;
  v_group record; v_version uuid; v_key text; v_completed timestamptz;
begin
  if p_dossier_id is null or p_package_id is null or p_no_change_output_ids is null
    or cardinality(p_no_change_output_ids)>30 or array_position(p_no_change_output_ids,null) is not null
    or (select count(distinct x) from unnest(p_no_change_output_ids) x)<>cardinality(p_no_change_output_ids) then
    raise exception 'mesa-intent-finalization-input-invalid';
  end if;
  select coalesce(array_agg(x order by x),'{}'::uuid[]) into v_no_change from unnest(p_no_change_output_ids) x;
  -- Completed replay is a historical fact, not a request to overwrite a later
  -- edit. Lock the same workspace as the writer before checking it.
  perform 1 from public.newsroom_mesa_production_contexts w where w.dossier_id=p_dossier_id for update;
  select * into v_final from public.newsroom_mesa_intent_finalizations f where f.dossier_id=p_dossier_id;
  if found then
    if v_final.package_id<>p_package_id or v_final.no_change_output_ids is distinct from v_no_change then
      raise exception 'mesa-intent-finalization-conflict';
    end if;
    return query select jsonb_build_object('action','reused','publicationEventId',v_final.publication_event_id,
      'updatedCount',v_final.updated_count,'newCount',v_final.new_count,'noChangeCount',v_final.no_change_count);
    return;
  end if;
  v_plan:=public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  if exists (select 1 from public.newsroom_mesa_production_contexts w
    where w.dossier_id=p_dossier_id and w.workspace_state<>'active') then
    raise exception 'mesa-intent-finalization-state-invalid';
  end if;
  if exists (select 1 from unnest(v_no_change) id where not exists (
      select 1 from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'outputId'=id::text and o ->> 'kind'='existing'))
    or exists (select 1 from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id and not exists (
      select 1 from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'outputId'=p.article_plan_id::text)) then
    raise exception 'mesa-intent-finalization-decision-invalid';
  end if;
  perform 1 from public.editorial_articles a where a.id in (
    select (o -> 'target' ->> 'editorialArticleId')::uuid from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'kind'='existing'
    union select p.editorial_article_id from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id
  ) order by a.id for update;
  for v_output in select value from jsonb_array_elements(v_plan -> 'outputs') loop
    select c into strict v_context from jsonb_array_elements(v_plan -> 'contexts') c where c ->> 'key'=v_output ->> 'contextKey';
    if (v_output ->> 'outputId')::uuid=any(v_no_change) then
      if exists (select 1 from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id and p.article_plan_id=(v_output ->> 'outputId')::uuid) then
        raise exception 'mesa-intent-no-change-already-published';
      end if;
      v_article_id:=(v_output -> 'target' ->> 'editorialArticleId')::uuid;
      select to_jsonb(a) into v_article from public.editorial_articles a where a.id=v_article_id and a.status='published';
      if not found or encode(sha256(convert_to(v_article::text,'UTF8')),'hex')
          is distinct from v_output -> 'target' ->> 'contentFingerprint' then
        raise exception 'mesa-intent-no-change-target-stale';
      end if;
      v_decision:='SEM_ALTERAÇÃO'; v_unchanged:=v_unchanged+1;
    else
      select * into v_written from public.newsroom_mesa_output_publications p
        where p.dossier_id=p_dossier_id and p.article_plan_id=(v_output ->> 'outputId')::uuid;
      if not found then raise exception 'mesa-intent-publication-incomplete'; end if;
      if v_written.package_id<>p_package_id or v_written.source_scope is distinct from 'context'
        or v_written.production_context_id is distinct from (v_context ->> 'productionContextId')::uuid
        or (v_output ->> 'kind'='existing' and v_written.editorial_article_id is distinct from (v_output -> 'target' ->> 'editorialArticleId')::uuid) then
        raise exception 'mesa-intent-publication-output-invalid';
      end if;
      v_article_id:=v_written.editorial_article_id;
      select to_jsonb(a) into v_article from public.editorial_articles a where a.id=v_article_id and a.status='published';
      if not found or encode(sha256(convert_to(v_article::text,'UTF8')),'hex') is distinct from v_written.payload ->> 'intentResultFingerprint' then
        raise exception 'mesa-intent-published-result-stale';
      end if;
      if not exists (
        select 1
        from public.newsroom_editorial_dossier_article_plans p
        where p.id=v_written.article_plan_id
          and p.dossier_id=p_dossier_id
          and (
            (
              v_output ->> 'kind'='existing'
              and p.destination='update'
              and p.update_target_editorial_article_id=v_article_id
              and (p.editorial_article_id is null or p.editorial_article_id=v_article_id)
            )
            or (
              v_output ->> 'kind'='new'
              and p.destination='new'
              and p.update_target_editorial_article_id is null
              and p.editorial_article_id=v_article_id
            )
          )
      ) then
        raise exception 'mesa-intent-publication-output-invalid';
      end if;
      v_decision:=case when v_output ->> 'kind'='existing' then 'UPDATE' else 'NEW' end;
      if v_decision='UPDATE' then v_updated:=v_updated+1; else v_new:=v_new+1; end if;
    end if;
    v_fingerprint:=encode(sha256(convert_to(v_article::text,'UTF8')),'hex');
    v_decisions:=v_decisions||jsonb_build_array(jsonb_build_object('slot',v_output -> 'slot',
      'outputId',v_output -> 'outputId','contextKey',v_output -> 'contextKey',
      'decision',v_decision,'articleId',v_article_id,'resultFingerprint',v_fingerprint));
    if v_context ->> 'themeId' is not null then
      v_receipts:=v_receipts||jsonb_build_array(jsonb_build_object('themeId',v_context -> 'themeId',
        'articleId',v_article_id,'outputId',v_output -> 'outputId','slot',v_output -> 'slot',
        'decision',v_decision,'sources',v_context -> 'sources','resultFingerprint',v_fingerprint));
    end if;
  end loop;
  v_payload:=jsonb_build_object('contractVersion',1,'kind','mesa_production_intents',
    'packageId',p_package_id,'authorityFingerprint',v_plan -> 'authorityFingerprint',
    'capturedAt',v_plan -> 'capturedAt','decisions',v_decisions);
  insert into public.newsroom_mesa_publication_events(dossier_id,fingerprint,payload)
    values(p_dossier_id,md5(v_payload::text),v_payload) returning id into v_event;
  v_completed:=clock_timestamp();
  insert into public.newsroom_mesa_intent_finalizations(dossier_id,package_id,publication_event_id,
    no_change_output_ids,updated_count,new_count,no_change_count,completed_at)
    values(p_dossier_id,p_package_id,v_event,v_no_change,v_updated,v_new,v_unchanged,v_completed);
  insert into public.newsroom_mesa_intent_article_receipts(dossier_id,output_id,theme_id,editorial_article_id,
    slot,decision,captured_at,completed_at,sources,result_fingerprint)
    select p_dossier_id,(r ->> 'outputId')::uuid,(r ->> 'themeId')::uuid,(r ->> 'articleId')::uuid,
      r ->> 'slot',r ->> 'decision',(v_plan ->> 'capturedAt')::timestamptz,v_completed,r -> 'sources',r ->> 'resultFingerprint'
    from jsonb_array_elements(v_receipts) r;
  -- Preserve technical material projection, but group by context as well as
  -- sources. Equal source sets in different Themes must never merge their work.
  for v_group in
    select x.production_context_id,x.source_refs,array_agg(x.article_id order by x.article_id) article_ids,
      min(x.article_plan_id::text)::uuid key_plan_id
    from (
      select p.production_context_id,u.article_plan_id,min(u.editorial_article_id::text)::uuid article_id,
        public.newsroom_mesa_normalize_refs_v2(jsonb_agg(jsonb_build_object(
          'newsroomArticleId',u.newsroom_article_id,'newsroomSnapshotId',u.newsroom_snapshot_id)
          order by u.newsroom_article_id,u.newsroom_snapshot_id)) source_refs
      from public.newsroom_mesa_output_source_usage u
      join public.newsroom_mesa_output_publications p on p.dossier_id=u.dossier_id and p.article_plan_id=u.article_plan_id
      where u.dossier_id=p_dossier_id group by p.production_context_id,u.article_plan_id having count(*)>=2
    ) x group by x.production_context_id,x.source_refs
  loop
    select c into strict v_context from jsonb_array_elements(v_plan -> 'contexts') c
      where c ->> 'productionContextId'=v_group.production_context_id::text;
    v_key:='output:'||v_group.key_plan_id::text;
    insert into public.newsroom_mesa_material_versions(material_key,title,source_refs,article_ids,production_dossier_id,publication_event_id)
      values(v_key,v_context ->> 'title',v_group.source_refs,v_group.article_ids,p_dossier_id,v_event) returning id into v_version;
    if v_context ->> 'themeId' is not null then
      insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
        values((v_context ->> 'themeId')::uuid,v_key,v_version) on conflict do nothing;
    end if;
  end loop;
  insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
    select (r ->> 'themeId')::uuid,(r ->> 'articleId')::uuid from jsonb_array_elements(v_receipts) r
    on conflict(theme_id,editorial_article_id) do nothing;
  update public.newsroom_mesa_production_contexts set workspace_state='consolidated',consolidated_at=v_completed where dossier_id=p_dossier_id;
  return query select jsonb_build_object('action','consolidated','publicationEventId',v_event,
    'updatedCount',v_updated,'newCount',v_new,'noChangeCount',v_unchanged);
end;
$function$;

revoke all on function public.newsroom_finalize_mesa_intents_v1(uuid, uuid, uuid[])
  from public, anon, authenticated, service_role;
grant execute on function public.newsroom_finalize_mesa_intents_v1(uuid, uuid, uuid[])
  to service_role;

commit;

-- Technical selection context for existing Production Intents.
-- Additive production migration: technical selection context for existing Production Intents.
begin;
do $preflight$
begin
  if to_regprocedure('public.newsroom_mesa_global_article_candidates_v1(uuid[],uuid[])') is null
    or to_regprocedure('public.newsroom_prepare_mesa_contexts_v3(uuid,text,jsonb,uuid,uuid[])') is null
    or to_regprocedure('public.newsroom_mesa_preview_intents_v1(jsonb)') is null
    or to_regclass('public.newsroom_mesa_production_context_items') is null
  then raise exception 'mesa-selection-context-preflight-missing'; end if;
end;
$preflight$;

alter table public.newsroom_mesa_production_context_items drop constraint newsroom_mesa_context_items_kind_check;
alter table public.newsroom_mesa_production_context_items add constraint newsroom_mesa_context_items_kind_check check (
  (context_kind='source' and source_newsroom_article_id is not null and theme_id is null)
  or (context_kind='theme' and source_newsroom_article_id is null and theme_id is not null)
  or (context_kind='selection' and source_newsroom_article_id is null and theme_id is null)
);
create unique index newsroom_mesa_context_items_selection_uidx
  on public.newsroom_mesa_production_context_items(dossier_id) where context_kind='selection';

create or replace function public.newsroom_mesa_context_item_sources_valid_v1(
  p_dossier_id uuid,
  p_production_context_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select case item.context_kind
    when 'source' then
      (
        select count(*) = 1
          and min(dossier_source.newsroom_article_id::text)
            = item.source_newsroom_article_id::text
        from public.newsroom_mesa_production_context_sources context_source
        join public.newsroom_editorial_dossier_sources dossier_source
          on dossier_source.dossier_id = context_source.dossier_id
          and dossier_source.id = context_source.dossier_source_id
        where context_source.dossier_id = item.dossier_id
          and context_source.production_context_id = item.id
      )
    when 'theme' then exists (
      select 1
      from public.newsroom_mesa_production_context_sources context_source
      where context_source.dossier_id = item.dossier_id
        and context_source.production_context_id = item.id
    )
    when 'selection' then exists (
      select 1
      from public.newsroom_mesa_production_context_sources context_source
      where context_source.dossier_id = item.dossier_id
        and context_source.production_context_id = item.id
    )
    else false
  end
  from public.newsroom_mesa_production_context_items item
  where item.dossier_id = p_dossier_id
    and item.id = p_production_context_id;
$function$;
create or replace function public.newsroom_prepare_mesa_contexts_v3(
  p_preparation_key uuid,
  p_title text,
  p_contexts jsonb,
  p_incorporate_theme_id uuid default null,
  p_incorporate_source_ids uuid[] default '{}'::uuid[]
)
returns table (
  dossier_id uuid,
  preparation_action text,
  source_count integer,
  published_context_count integer,
  image_count integer,
  context_count integer
)
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_request_fingerprint text;
  v_existing public.newsroom_mesa_production_contexts%rowtype;
  v_result record;
  v_context jsonb;
  v_contexts jsonb := '[]'::jsonb;
  v_refs jsonb;
  v_union_refs jsonb := '[]'::jsonb;
  v_ref jsonb;
  v_kind text;
  v_source_id uuid;
  v_theme_id uuid;
  v_title_snapshot text;
  v_context_id uuid;
  v_snapshot_id uuid;
  v_ordinality bigint;
  v_ref_ordinality bigint;
  v_requested_theme_sources uuid[];
  v_current_theme_sources uuid[];
  v_incorporate_source_ids uuid[];
begin
  if p_preparation_key is null
    or nullif(btrim(p_title), '') is null
    or length(btrim(p_title)) > 180
    or p_contexts is null
    or jsonb_typeof(p_contexts) is distinct from 'array'
  then
    raise exception 'mesa-context-preparation-input-invalid';
  end if;

  if jsonb_array_length(p_contexts) not between 1 and 20
    or p_incorporate_source_ids is null
    or array_position(p_incorporate_source_ids, null) is not null
  then
    raise exception 'mesa-context-preparation-input-invalid';
  end if;

  select coalesce(array_agg(source_id order by source_id), '{}'::uuid[])
  into v_incorporate_source_ids
  from (
    select distinct source_id
    from unnest(p_incorporate_source_ids) source_rows(source_id)
  ) normalized;

  if cardinality(v_incorporate_source_ids) <> cardinality(p_incorporate_source_ids)
    or cardinality(v_incorporate_source_ids) > 20
    or (p_incorporate_theme_id is null and cardinality(v_incorporate_source_ids) <> 0)
    or (p_incorporate_theme_id is not null and cardinality(v_incorporate_source_ids) < 1)
  then
    raise exception 'mesa-context-incorporation-input-invalid';
  end if;

  v_request_fingerprint := md5(jsonb_build_object(
    'contractVersion', 3,
    'title', btrim(p_title),
    'contexts', p_contexts,
    'incorporateThemeId', p_incorporate_theme_id,
    'incorporateSourceIds', to_jsonb(v_incorporate_source_ids)
  )::text);

  perform pg_advisory_xact_lock(
    hashtextextended('newsroom-mesa-organization-v1', 0)
  );

  select context.*
  into v_existing
  from public.newsroom_mesa_production_contexts context
  where context.preparation_key = p_preparation_key;

  if found then
    if v_existing.selection_payload ->> 'contextRequestFingerprint'
        is distinct from v_request_fingerprint
      or v_existing.workspace_contract_version is distinct from 2::smallint
      or v_existing.workspace_state is distinct from 'active'
      or not exists (
        select 1
        from public.newsroom_mesa_production_context_items item
        where item.dossier_id = v_existing.dossier_id
      )
    then
      raise exception 'mesa-context-preparation-conflict';
    end if;

    return query
    select
      v_existing.dossier_id,
      'reused'::text,
      jsonb_array_length(v_existing.source_refs),
      (
        select count(*)::integer
        from public.newsroom_editorial_dossier_published_contexts published_context
        where published_context.dossier_id = v_existing.dossier_id
      ),
      (
        select count(*)::integer
        from public.newsroom_editorial_dossier_images image
        where image.dossier_id = v_existing.dossier_id
      ),
      (
        select count(*)::integer
        from public.newsroom_mesa_production_context_items item
        where item.dossier_id = v_existing.dossier_id
      );
    return;
  end if;

  if exists (
    select 1
    from public.newsroom_editorial_dossiers dossier
    where dossier.preparation_key = p_preparation_key
  ) then
    raise exception 'mesa-context-prepared-before-v3';
  end if;

  for v_context, v_ordinality in
    select context.value, context.ordinality
    from jsonb_array_elements(p_contexts)
      with ordinality context(value, ordinality)
  loop
    if jsonb_typeof(v_context) is distinct from 'object'
      or jsonb_typeof(v_context -> 'sources') is distinct from 'array'
    then
      raise exception 'mesa-context-selection-invalid';
    end if;

    v_kind := lower(btrim(coalesce(v_context ->> 'kind', '')));
    v_source_id := null;
    v_theme_id := null;

    begin
      if v_kind = 'source' then
        v_source_id := (v_context ->> 'sourceId')::uuid;
      elsif v_kind = 'theme' then
        v_theme_id := (v_context ->> 'themeId')::uuid;
      elsif v_kind = 'selection' then
        if coalesce(v_context ->> 'sourceId','') <> ''
          or coalesce(v_context ->> 'themeId','') <> ''
        then raise exception 'mesa-context-selection-invalid'; end if;
      else
        raise exception 'mesa-context-selection-invalid';
      end if;
    exception
      when invalid_text_representation or not_null_violation then
        raise exception 'mesa-context-selection-invalid';
    end;

    v_refs := public.newsroom_mesa_normalize_refs_v2(v_context -> 'sources');
    if jsonb_array_length(v_refs) not between 1 and 20 then
      raise exception 'mesa-context-selection-invalid';
    end if;

    if v_kind = 'source' then
      if jsonb_array_length(v_refs) <> 1
        or lower(v_refs -> 0 ->> 'newsroomArticleId') <> v_source_id::text
      then
        raise exception 'mesa-context-source-selection-invalid';
      end if;
      select coalesce(nullif(btrim(article.title), ''), 'Fonte')
      into v_title_snapshot
      from public.newsroom_articles article
      where article.id = v_source_id;
      if not found then
        raise exception 'mesa-context-source-unavailable';
      end if;
      if exists (
        select 1
        from public.newsroom_editorial_theme_sources membership
        where membership.newsroom_article_id = v_source_id
      ) then
        raise exception 'mesa-context-source-not-loose';
      end if;
    elsif v_kind = 'theme' then
      select theme.title
      into v_title_snapshot
      from public.newsroom_editorial_themes theme
      where theme.id = v_theme_id
        and theme.status = 'open'
      for update;
      if not found then
        raise exception 'mesa-context-theme-unavailable';
      end if;
    else
      v_title_snapshot := btrim(p_title);
    end if;

    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object(
      'kind', v_kind,
      'sourceId', v_source_id,
      'themeId', v_theme_id,
      'titleSnapshot', v_title_snapshot,
      'sortOrder', v_ordinality,
      'sources', v_refs
    ));
    v_union_refs := v_union_refs || v_refs;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(v_contexts) context(value)
    group by
      context.value ->> 'kind',
      coalesce(context.value ->> 'sourceId', context.value ->> 'themeId')
    having count(*) > 1
  ) then
    raise exception 'mesa-context-selection-duplicate';
  end if;

  v_union_refs := public.newsroom_mesa_normalize_refs_v2(v_union_refs);
  if jsonb_array_length(v_union_refs) not between 1 and 20 then
    raise exception 'mesa-context-selection-invalid';
  end if;

  if p_incorporate_theme_id is not null then
    if jsonb_array_length(v_contexts) <> 1
      or v_contexts -> 0 ->> 'kind' <> 'theme'
      or lower(v_contexts -> 0 ->> 'themeId') <> p_incorporate_theme_id::text
    then
      raise exception 'mesa-context-incorporation-ambiguous';
    end if;

    if exists (
      select 1
      from unnest(v_incorporate_source_ids) requested(source_id)
      where not exists (
        select 1
        from jsonb_array_elements(v_contexts -> 0 -> 'sources') ref(value)
        where lower(ref.value ->> 'newsroomArticleId') = requested.source_id::text
      )
        or exists (
          select 1
          from public.newsroom_editorial_theme_sources membership
          where membership.newsroom_article_id = requested.source_id
        )
    ) then
      raise exception 'mesa-context-incorporation-source-invalid';
    end if;

    foreach v_source_id in array v_incorporate_source_ids
    loop
      select (ref.value ->> 'newsroomSnapshotId')::uuid
      into strict v_snapshot_id
      from jsonb_array_elements(v_contexts -> 0 -> 'sources') ref(value)
      where lower(ref.value ->> 'newsroomArticleId') = v_source_id::text;

      perform public.newsroom_set_editorial_theme_source_membership_v1(
        p_incorporate_theme_id,
        v_source_id,
        true
      );
      perform public.newsroom_acknowledge_theme_source_v1(
        p_incorporate_theme_id,
        v_source_id,
        v_snapshot_id
      );
    end loop;
  end if;

  for v_context in
    select context.value
    from jsonb_array_elements(v_contexts) context(value)
    where context.value ->> 'kind' = 'theme'
  loop
    select array_agg(membership.newsroom_article_id order by membership.newsroom_article_id)
    into v_current_theme_sources
    from public.newsroom_editorial_theme_sources membership
    where membership.theme_id = (v_context ->> 'themeId')::uuid;

    select array_agg(
      distinct (ref.value ->> 'newsroomArticleId')::uuid
      order by (ref.value ->> 'newsroomArticleId')::uuid
    )
    into v_requested_theme_sources
    from jsonb_array_elements(v_context -> 'sources') ref(value);

    if coalesce(v_current_theme_sources, '{}'::uuid[])
      is distinct from coalesce(v_requested_theme_sources, '{}'::uuid[])
    then
      raise exception 'mesa-context-theme-membership-stale';
    end if;
  end loop;

  select *
  into v_result
  from public.newsroom_prepare_mesa_materials_v2(
    p_preparation_key,
    null,
    btrim(p_title),
    v_union_refs,
    '[]'::jsonb
  );

  update public.newsroom_mesa_production_contexts context
  set selection_payload = jsonb_build_object(
    'contractVersion', 3,
    'contextContractVersion', 1,
    'contextRequestFingerprint', v_request_fingerprint,
    'title', btrim(p_title),
    'sources', v_union_refs,
    'materials', '[]'::jsonb,
    'contexts', v_contexts,
    'incorporateThemeId', p_incorporate_theme_id,
    'incorporateSourceIds', to_jsonb(v_incorporate_source_ids)
  )
  where context.dossier_id = v_result.dossier_id;

  if not found then
    raise exception 'mesa-context-preparation-workspace-missing';
  end if;

  for v_context in
    select context.value
    from jsonb_array_elements(v_contexts) context(value)
    order by (context.value ->> 'sortOrder')::smallint
  loop
    insert into public.newsroom_mesa_production_context_items(
      dossier_id,
      context_kind,
      source_newsroom_article_id,
      theme_id,
      title_snapshot,
      sort_order
    ) values (
      v_result.dossier_id,
      v_context ->> 'kind',
      (v_context ->> 'sourceId')::uuid,
      (v_context ->> 'themeId')::uuid,
      v_context ->> 'titleSnapshot',
      (v_context ->> 'sortOrder')::smallint
    )
    returning id into v_context_id;

    for v_ref, v_ref_ordinality in
      select ref.value, ref.ordinality
      from jsonb_array_elements(v_context -> 'sources')
        with ordinality ref(value, ordinality)
    loop
      insert into public.newsroom_mesa_production_context_sources(
        dossier_id,
        production_context_id,
        dossier_source_id,
        sort_order
      )
      select
        v_result.dossier_id,
        v_context_id,
        dossier_source.id,
        v_ref_ordinality::smallint
      from public.newsroom_editorial_dossier_sources dossier_source
      where dossier_source.dossier_id = v_result.dossier_id
        and dossier_source.newsroom_article_id = (v_ref ->> 'newsroomArticleId')::uuid
        and dossier_source.newsroom_snapshot_id = (v_ref ->> 'newsroomSnapshotId')::uuid
        and dossier_source.included;

      if not found then
        raise exception 'mesa-context-frozen-source-missing';
      end if;
    end loop;
  end loop;

  return query
  select
    v_result.dossier_id,
    v_result.preparation_action,
    v_result.source_count,
    v_result.published_context_count,
    v_result.image_count,
    jsonb_array_length(v_contexts);
end;
$function$;
create or replace function public.newsroom_mesa_normalize_intent_v1(p_request jsonb)
returns jsonb language plpgsql immutable set search_path = '' as $function$
declare
  v_item jsonb; v_themes jsonb := '[]'; v_sources jsonb := '[]';
  v_selection jsonb := null; v_selection_sources jsonb := '[]'; v_selection_themes jsonb := '[]';
  v_selection_candidates jsonb := '[]'; v_selection_articles jsonb := '[]';
  v_uuid constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  if jsonb_typeof(p_request) is distinct from 'object'
    or not (p_request ?& array['version','preparationKey','title','themes','sources'])
    or p_request - array['version','preparationKey','title','themes','sources','selection'] <> '{}'
    or p_request -> 'version' is distinct from '1'::jsonb
    or jsonb_typeof(p_request -> 'preparationKey') is distinct from 'string'
    or lower(p_request ->> 'preparationKey') !~ v_uuid
    or jsonb_typeof(p_request -> 'title') is distinct from 'string'
    or length(btrim(p_request ->> 'title')) not between 1 and 180
    or jsonb_typeof(p_request -> 'themes') is distinct from 'array'
    or jsonb_typeof(p_request -> 'sources') is distinct from 'array'
  then raise exception 'mesa-intent-input-invalid'; end if;
  if jsonb_array_length(p_request -> 'themes') > 20
    or jsonb_array_length(p_request -> 'sources') > 200
  then raise exception 'mesa-intent-input-invalid'; end if;
  for v_item in select value from jsonb_array_elements(p_request -> 'themes') loop
    if jsonb_typeof(v_item) is distinct from 'object'
      or not (v_item ?& array['themeId','action'])
      or jsonb_typeof(v_item -> 'themeId') is distinct from 'string'
      or lower(v_item ->> 'themeId') !~ v_uuid
      or coalesce(v_item ->> 'action','') not in ('defer','prepare')
    then raise exception 'mesa-intent-theme-invalid'; end if;
    if v_item ->> 'action' = 'defer' then
      if v_item - array['themeId','action'] <> '{}' then raise exception 'mesa-intent-theme-invalid'; end if;
    else
      if not (v_item ?& array['reviewPublished','newArticleCount'])
        or v_item - array['themeId','action','reviewPublished','newArticleCount'] <> '{}'
        or jsonb_typeof(v_item -> 'reviewPublished') is distinct from 'boolean'
        or jsonb_typeof(v_item -> 'newArticleCount') is distinct from 'number'
        or (v_item ->> 'newArticleCount') !~ '^[0-9]+$'
      then raise exception 'mesa-intent-theme-invalid'; end if;
      if (v_item ->> 'newArticleCount')::numeric not between 0 and 30 then raise exception 'mesa-intent-theme-invalid'; end if;
    end if;
    v_themes := v_themes || jsonb_build_array(v_item || jsonb_build_object('themeId',lower(v_item ->> 'themeId')));
  end loop;
  for v_item in select value from jsonb_array_elements(p_request -> 'sources') loop
    if jsonb_typeof(v_item) is distinct from 'object'
      or not (v_item ?& array['sourceId','destination'])
      or jsonb_typeof(v_item -> 'sourceId') is distinct from 'string'
      or lower(v_item ->> 'sourceId') !~ v_uuid
      or coalesce(v_item ->> 'destination','') not in ('defer','independent','theme')
    then raise exception 'mesa-intent-source-invalid'; end if;
    case v_item ->> 'destination'
    when 'defer' then
      if v_item - array['sourceId','destination'] <> '{}' then raise exception 'mesa-intent-source-invalid'; end if;
    when 'theme' then
      if not (v_item ? 'themeId') or v_item - array['sourceId','destination','themeId'] <> '{}'
        or jsonb_typeof(v_item -> 'themeId') is distinct from 'string' or lower(v_item ->> 'themeId') !~ v_uuid
      then raise exception 'mesa-intent-source-invalid'; end if;
      v_item := v_item || jsonb_build_object('themeId',lower(v_item ->> 'themeId'));
      if not exists (select 1 from jsonb_array_elements(v_themes) t
        where t ->> 'themeId' = v_item ->> 'themeId' and t ->> 'action' = 'prepare')
      then raise exception 'mesa-intent-incorporation-target-invalid'; end if;
    else
      if not (v_item ? 'newArticleCount') or v_item - array['sourceId','destination','newArticleCount'] <> '{}'
        or jsonb_typeof(v_item -> 'newArticleCount') is distinct from 'number'
        or (v_item ->> 'newArticleCount') !~ '^[0-9]+$'
      then raise exception 'mesa-intent-source-invalid'; end if;
      if (v_item ->> 'newArticleCount')::numeric not between 1 and 30 then raise exception 'mesa-intent-source-invalid'; end if;
    end case;
    v_sources := v_sources || jsonb_build_array(v_item || jsonb_build_object('sourceId',lower(v_item ->> 'sourceId')));
  end loop;
  if exists (select 1 from jsonb_array_elements(v_themes) t group by t ->> 'themeId' having count(*) > 1)
    or exists (select 1 from jsonb_array_elements(v_sources) s group by s ->> 'sourceId' having count(*) > 1)
  then raise exception 'mesa-intent-selection-duplicate'; end if;
  if p_request ? 'selection' then
    v_selection := p_request -> 'selection';
    if jsonb_typeof(v_selection) is distinct from 'object'
      or not (v_selection ?& array['sourceIds','reviewArticleIds','newArticleCount'])
      or v_selection - array['sourceIds','themeIds','candidateArticleIds','reviewArticleIds','newArticleCount'] <> '{}'
      or jsonb_typeof(v_selection -> 'sourceIds') is distinct from 'array'
      or jsonb_array_length(v_selection -> 'sourceIds') > 20
      or jsonb_typeof(coalesce(v_selection -> 'themeIds','[]'::jsonb)) is distinct from 'array'
      or jsonb_array_length(coalesce(v_selection -> 'themeIds','[]'::jsonb)) > 20
      or jsonb_typeof(coalesce(v_selection -> 'candidateArticleIds','[]'::jsonb)) is distinct from 'array'
      or jsonb_array_length(coalesce(v_selection -> 'candidateArticleIds','[]'::jsonb)) > 200
      or jsonb_typeof(v_selection -> 'reviewArticleIds') is distinct from 'array'
      or jsonb_array_length(v_selection -> 'reviewArticleIds') > 30
      or jsonb_typeof(v_selection -> 'newArticleCount') is distinct from 'number'
      or (v_selection ->> 'newArticleCount') !~ '^[0-9]+$'
      or (v_selection ->> 'newArticleCount')::numeric not between 0 and 30
    then raise exception 'mesa-intent-selection-invalid'; end if;
    for v_item in select value from jsonb_array_elements(v_selection -> 'sourceIds') loop
      if jsonb_typeof(v_item) is distinct from 'string' or lower(v_item #>> '{}') !~ v_uuid then raise exception 'mesa-intent-selection-invalid'; end if;
      v_selection_sources := v_selection_sources || jsonb_build_array(lower(v_item #>> '{}'));
    end loop;
    for v_item in select value from jsonb_array_elements(coalesce(v_selection -> 'themeIds','[]'::jsonb)) loop
      if jsonb_typeof(v_item) is distinct from 'string' or lower(v_item #>> '{}') !~ v_uuid then raise exception 'mesa-intent-selection-invalid'; end if;
      v_selection_themes := v_selection_themes || jsonb_build_array(lower(v_item #>> '{}'));
    end loop;
    for v_item in select value from jsonb_array_elements(coalesce(v_selection -> 'candidateArticleIds','[]'::jsonb)) loop
      if jsonb_typeof(v_item) is distinct from 'string' or lower(v_item #>> '{}') !~ v_uuid then raise exception 'mesa-intent-selection-invalid'; end if;
      v_selection_candidates := v_selection_candidates || jsonb_build_array(lower(v_item #>> '{}'));
    end loop;
    for v_item in select value from jsonb_array_elements(v_selection -> 'reviewArticleIds') loop
      if jsonb_typeof(v_item) is distinct from 'string' or lower(v_item #>> '{}') !~ v_uuid then raise exception 'mesa-intent-selection-invalid'; end if;
      v_selection_articles := v_selection_articles || jsonb_build_array(lower(v_item #>> '{}'));
    end loop;
    if jsonb_array_length(v_selection_sources)+jsonb_array_length(v_selection_themes) < 1
      or (select count(distinct value #>> '{}') from jsonb_array_elements(v_selection_sources)) <> jsonb_array_length(v_selection_sources)
      or (select count(distinct value #>> '{}') from jsonb_array_elements(v_selection_themes)) <> jsonb_array_length(v_selection_themes)
      or (select count(distinct value #>> '{}') from jsonb_array_elements(v_selection_candidates)) <> jsonb_array_length(v_selection_candidates)
      or (select count(distinct value #>> '{}') from jsonb_array_elements(v_selection_articles)) <> jsonb_array_length(v_selection_articles)
      or exists (select 1 from jsonb_array_elements(v_selection_sources) selected join jsonb_array_elements(v_sources) source on source ->> 'sourceId'=selected #>> '{}')
      or exists (select 1 from jsonb_array_elements(v_selection_themes) selected join jsonb_array_elements(v_themes) theme on theme ->> 'themeId'=selected #>> '{}')
      or (v_selection ? 'candidateArticleIds' and exists (
        select 1 from jsonb_array_elements(v_selection_articles) reviewed
        where not exists (select 1 from jsonb_array_elements(v_selection_candidates) candidate where candidate #>> '{}'=reviewed #>> '{}')
      ))
      or jsonb_array_length(v_selection_articles)+(v_selection ->> 'newArticleCount')::integer < 1
    then raise exception 'mesa-intent-selection-invalid'; end if;
    select coalesce(jsonb_agg(value order by value #>> '{}'),'[]'::jsonb) into v_selection_sources from jsonb_array_elements(v_selection_sources);
    select coalesce(jsonb_agg(value order by value #>> '{}'),'[]'::jsonb) into v_selection_themes from jsonb_array_elements(v_selection_themes);
    select coalesce(jsonb_agg(value order by value #>> '{}'),'[]'::jsonb) into v_selection_candidates from jsonb_array_elements(v_selection_candidates);
    select coalesce(jsonb_agg(value order by value #>> '{}'),'[]'::jsonb) into v_selection_articles from jsonb_array_elements(v_selection_articles);
    v_selection := jsonb_build_object('sourceIds',v_selection_sources,'reviewArticleIds',v_selection_articles,
      'newArticleCount',(v_selection ->> 'newArticleCount')::integer)
      || case when p_request -> 'selection' ? 'themeIds' then jsonb_build_object('themeIds',v_selection_themes) else '{}'::jsonb end
      || case when p_request -> 'selection' ? 'candidateArticleIds' then jsonb_build_object('candidateArticleIds',v_selection_candidates) else '{}'::jsonb end;
  end if;
  return jsonb_build_object('version',1,'preparationKey',lower(p_request ->> 'preparationKey'),
    'title',btrim(p_request ->> 'title'),
    'themes',(select coalesce(jsonb_agg(t order by t ->> 'themeId'),'[]') from jsonb_array_elements(v_themes) t),
    'sources',(select coalesce(jsonb_agg(s order by s ->> 'sourceId'),'[]') from jsonb_array_elements(v_sources) s))
    || case when v_selection is null then '{}'::jsonb else jsonb_build_object('selection',v_selection) end;
end;
$function$;
create or replace function public.newsroom_mesa_preview_intents_v1(p_request jsonb)
returns table(plan jsonb) language plpgsql stable security definer set search_path = '' as $function$
declare
  v_request jsonb := public.newsroom_mesa_normalize_intent_v1(p_request);
  v_intent jsonb; v_theme public.newsroom_editorial_themes%rowtype;
  v_id uuid; v_key text; v_source jsonb; v_sources jsonb; v_history jsonb; v_candidates jsonb;
  v_contexts jsonb := '[]'; v_outputs jsonb := '[]'; v_incorporations jsonb := '[]';
  v_context jsonb; v_article jsonb; v_review_count integer := 0; v_new_count integer := 0;
  v_source_count integer; v_i integer; v_material jsonb;
begin
  for v_intent in select t from jsonb_array_elements(v_request -> 'themes') t where t ->> 'action' = 'prepare' loop
    select * into v_theme from public.newsroom_editorial_themes t where t.id = (v_intent ->> 'themeId')::uuid and t.status = 'open';
    if not found then raise exception 'mesa-intent-theme-unavailable' using detail = v_intent ->> 'themeId'; end if;
    v_key := 'theme:' || v_theme.id::text;
    v_sources := '[]';
    for v_id in
      select m.newsroom_article_id from public.newsroom_editorial_theme_sources m where m.theme_id = v_theme.id
      union select (s ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') s
        where s ->> 'destination' = 'theme' and s ->> 'themeId' = v_theme.id::text
      order by 1
    loop
      v_source := public.newsroom_mesa_intent_source_v1(v_id);
      if v_source is null or v_source ->> 'newsroomSnapshotId' is null or v_source -> 'usable' is distinct from 'true'::jsonb then
        raise exception 'mesa-intent-source-snapshot-unavailable' using detail = v_key || ':' || v_id::text;
      end if;
      if v_source ->> 'classificationKey' is null then raise exception 'mesa-intent-classification-required' using detail = v_id::text; end if;
      v_sources := v_sources || jsonb_build_array(v_source);
      if not exists (select 1 from public.newsroom_editorial_theme_sources m where m.theme_id = v_theme.id and m.newsroom_article_id = v_id) then
        v_incorporations := v_incorporations || jsonb_build_array(jsonb_build_object('themeId',v_theme.id,'sourceId',v_id));
      end if;
    end loop;
    if jsonb_array_length(v_sources) = 0 then raise exception 'mesa-intent-theme-sources-missing' using detail = v_key; end if;
    select coalesce(jsonb_agg(jsonb_build_object('editorialArticleId',a.id,'slug',a.slug,'title',a.title,
      'matchdayId',a.matchday_id,'contentFingerprint',encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),
      'article',to_jsonb(a)) order by a.id),'[]') into v_history
    from public.newsroom_editorial_theme_articles m join public.editorial_articles a on a.id = m.editorial_article_id
    where m.theme_id = v_theme.id and a.status = 'published';
    if exists (select 1 from jsonb_array_elements(v_history) a where nullif(btrim(a ->> 'slug'),'') is null or nullif(btrim(a ->> 'title'),'') is null) then
      raise exception 'mesa-intent-published-history-invalid' using detail = v_key;
    end if;
    if (v_intent ->> 'reviewPublished')::boolean and jsonb_array_length(v_history) = 0 then
      raise exception 'mesa-intent-nothing-to-review' using detail = v_key;
    end if;
    if not (v_intent ->> 'reviewPublished')::boolean and (v_intent ->> 'newArticleCount')::integer = 0 then
      raise exception 'mesa-intent-theme-work-missing' using detail = v_key;
    end if;
    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object('key',v_key,'kind','theme',
      'themeId',v_theme.id,'sourceId',null,'title',v_theme.title,'theme',to_jsonb(v_theme),
      'reviewPublished',v_intent -> 'reviewPublished','newArticleCount',v_intent -> 'newArticleCount',
      'sources',v_sources,'publishedArticles',v_history));
  end loop;
  for v_intent in select s from jsonb_array_elements(v_request -> 'sources') s where s ->> 'destination' = 'independent' loop
    v_id := (v_intent ->> 'sourceId')::uuid; v_key := 'source:' || v_id::text;
    if exists (select 1 from public.newsroom_editorial_theme_sources m where m.newsroom_article_id = v_id) then
      raise exception 'mesa-intent-independent-source-not-loose' using detail = v_key;
    end if;
    v_source := public.newsroom_mesa_intent_source_v1(v_id);
    if v_source is null or v_source ->> 'newsroomSnapshotId' is null or v_source -> 'usable' is distinct from 'true'::jsonb then
      raise exception 'mesa-intent-source-snapshot-unavailable' using detail = v_key;
    end if;
    if v_source ->> 'classificationKey' is null then raise exception 'mesa-intent-classification-required' using detail = v_key; end if;
    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object('key',v_key,'kind','source',
      'themeId',null,'sourceId',v_id,'title','Fonte independente','reviewPublished',false,
      'newArticleCount',v_intent -> 'newArticleCount','sources',jsonb_build_array(v_source),'publishedArticles','[]'::jsonb));
  end loop;
  if v_request ? 'selection' then
    v_key := 'selection:' || (v_request ->> 'preparationKey');
    if exists (
      select 1 from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) selected
      where not exists (select 1 from public.newsroom_editorial_themes theme
        where theme.id=(selected #>> '{}')::uuid and theme.status='open')
    ) then raise exception 'mesa-intent-theme-unavailable' using detail=v_key; end if;
    v_sources := '[]'::jsonb;
    for v_id in
      select (value #>> '{}')::uuid from jsonb_array_elements(v_request -> 'selection' -> 'sourceIds')
      union
      select membership.newsroom_article_id from public.newsroom_editorial_theme_sources membership
      where membership.theme_id in (
        select (value #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb))
      )
      order by 1
    loop
      v_source := public.newsroom_mesa_intent_source_v1(v_id);
      if v_source is null or v_source ->> 'newsroomSnapshotId' is null or v_source -> 'usable' is distinct from 'true'::jsonb
      then raise exception 'mesa-intent-source-snapshot-unavailable' using detail=v_key||':'||v_id::text; end if;
      if v_source ->> 'classificationKey' is null then raise exception 'mesa-intent-classification-required' using detail=v_key||':'||v_id::text; end if;
      v_sources := v_sources || jsonb_build_array(v_source);
    end loop;
    if jsonb_array_length(v_sources)=0 then raise exception 'mesa-intent-selection-sources-missing' using detail=v_key; end if;
    select candidates into strict v_candidates from public.newsroom_mesa_global_article_candidates_v1(
      array(select (value #>> '{}')::uuid from jsonb_array_elements(v_request -> 'selection' -> 'sourceIds')),
      array(select (value #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)))
    );
    select coalesce(jsonb_agg(candidate order by candidate ->> 'editorialArticleId'),'[]'::jsonb)
      into v_candidates
      from jsonb_array_elements(v_candidates) candidate;
    if v_request -> 'selection' ? 'candidateArticleIds' and
      (select coalesce(jsonb_agg(candidate -> 'editorialArticleId' order by candidate ->> 'editorialArticleId'),'[]'::jsonb)
       from jsonb_array_elements(v_candidates) candidate) is distinct from v_request -> 'selection' -> 'candidateArticleIds'
    then raise exception 'mesa-intent-selection-candidates-stale' using detail=v_key; end if;
    if exists (
      select 1 from jsonb_array_elements(v_request -> 'selection' -> 'reviewArticleIds') requested
      where not exists (select 1 from jsonb_array_elements(v_candidates) candidate where candidate ->> 'editorialArticleId'=requested #>> '{}')
    ) then raise exception 'mesa-intent-selection-target-unavailable' using detail=v_key; end if;
    select coalesce(jsonb_agg(candidate order by candidate ->> 'editorialArticleId'),'[]'::jsonb)
      into v_history from jsonb_array_elements(v_candidates) candidate
      where exists (select 1 from jsonb_array_elements(v_request -> 'selection' -> 'reviewArticleIds') requested
        where requested #>> '{}'=candidate ->> 'editorialArticleId');
    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object(
      'key',v_key,'kind','selection','themeId',null,'sourceId',null,'title',v_request ->> 'title',
      'reviewPublished',jsonb_array_length(v_request -> 'selection' -> 'reviewArticleIds')>0,
      'newArticleCount',v_request -> 'selection' -> 'newArticleCount',
      'sources',v_sources,'publishedArticles',v_history,'candidateArticles',v_candidates));
  end if;
  select coalesce(jsonb_agg(c order by c ->> 'key'),'[]') into v_contexts from jsonb_array_elements(v_contexts) c;
  for v_context in select c from jsonb_array_elements(v_contexts) c where (c ->> 'reviewPublished')::boolean loop
    for v_article in select a from jsonb_array_elements(v_context -> 'publishedArticles') a loop
      if exists (select 1 from jsonb_array_elements(v_outputs) o where o -> 'target' ->> 'editorialArticleId' = v_article ->> 'editorialArticleId') then
        raise exception 'mesa-intent-review-target-conflict';
      end if;
      v_review_count := v_review_count + 1;
      v_outputs := v_outputs || jsonb_build_array(jsonb_build_object('slot','EXISTING_' || lpad(v_review_count::text,2,'0'),
        'contextKey',v_context ->> 'key','kind','existing','target',v_article));
    end loop;
  end loop;
  for v_context in select value from jsonb_array_elements(v_contexts) loop
    for v_i in 1..(v_context ->> 'newArticleCount')::integer loop
      v_new_count := v_new_count + 1;
      v_outputs := v_outputs || jsonb_build_array(jsonb_build_object('slot','NEW_' || lpad(v_new_count::text,2,'0'),
        'contextKey',v_context ->> 'key','kind','new','target',null));
    end loop;
  end loop;
  select count(distinct s ->> 'newsroomArticleId')::integer into v_source_count
    from jsonb_array_elements(v_contexts) c cross join lateral jsonb_array_elements(c -> 'sources') s;
  if jsonb_array_length(v_contexts) > 20 then raise exception 'mesa-intent-context-limit'; end if;
  if v_source_count > 20 then raise exception 'mesa-intent-source-limit'; end if;
  if v_review_count + v_new_count = 0 then raise exception 'mesa-intent-no-work-requested'; end if;
  if v_review_count + v_new_count > 30 then raise exception 'mesa-intent-output-limit'; end if;
  v_material := jsonb_build_object('contractVersion',1,'request',v_request,
    'preparationKey',v_request ->> 'preparationKey','title',v_request ->> 'title',
    'contexts',v_contexts,'outputs',v_outputs,'incorporations',v_incorporations,
    'deferred',jsonb_build_object(
      'themeIds',(select coalesce(jsonb_agg(t -> 'themeId'),'[]') from jsonb_array_elements(v_request -> 'themes') t where t ->> 'action' = 'defer'),
      'sourceIds',(select coalesce(jsonb_agg(s -> 'sourceId'),'[]') from jsonb_array_elements(v_request -> 'sources') s where s ->> 'destination' = 'defer')),
    'totals',jsonb_build_object('contexts',jsonb_array_length(v_contexts),'sources',v_source_count,'reviews',v_review_count,'newArticles',v_new_count));
  return query select v_material || jsonb_build_object('capturedAt',to_char(statement_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'authorityFingerprint',encode(sha256(convert_to(v_material::text,'UTF8')),'hex'));
end;
$function$;
create or replace function public.newsroom_prepare_mesa_intents_v1(p_request jsonb, p_expected_authority_fingerprint text)
returns table(result jsonb) language plpgsql volatile security definer set search_path = '' as $function$
declare
  v_request jsonb := public.newsroom_mesa_normalize_intent_v1(p_request);
  v_key uuid := (v_request ->> 'preparationKey')::uuid;
  v_existing public.newsroom_mesa_intent_preparations%rowtype;
  v_preview jsonb; v_contexts jsonb := '[]'; v_context jsonb; v_item jsonb;
  v_result record; v_context_id uuid; v_plan_id uuid; v_ids uuid[]; v_plan_ids uuid[] := '{}';
  v_frozen_contexts jsonb := '[]'; v_outputs jsonb := '[]'; v_frozen jsonb; v_i integer := 0;
begin
  if p_expected_authority_fingerprint is null or p_expected_authority_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'mesa-intent-fingerprint-invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1',0));
  -- Test idempotency before current-state reads: a retry must not be invalidated
  -- by memberships created by its own first successful call.
  select * into v_existing from public.newsroom_mesa_intent_preparations p where p.preparation_key = v_key;
  if found then
    if v_existing.request is distinct from v_request or v_existing.authority_fingerprint is distinct from p_expected_authority_fingerprint then
      raise exception 'mesa-intent-preparation-conflict';
    end if;
    return query select jsonb_build_object('dossierId',v_existing.dossier_id,'preparationAction','reused','plan',v_existing.frozen_plan);
    return;
  end if;
  if exists (select 1 from public.newsroom_mesa_production_contexts w where w.preparation_key = v_key)
    or exists (select 1 from public.newsroom_editorial_dossiers d where d.preparation_key = v_key)
  then raise exception 'mesa-intent-preparation-key-used'; end if;
  update public.newsroom_mesa_containment_guard set revision = not revision where singleton;
  if not found then raise exception 'mesa-organization-containment-guard-missing'; end if;
  perform 1 from public.newsroom_editorial_themes t where t.id in (
    select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
    union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) x
  ) order by t.id for update;
  -- Parent FOR UPDATE locks also block an ingest inserting a new snapshot through
  -- its FK while sources are frozen. Existing snapshot rows are locked as well.
  perform 1 from public.newsroom_articles a where a.id in (
    select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
    union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'sourceIds','[]'::jsonb)) x
    union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m
      where m.theme_id in (
        select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
        union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) x
      )
  ) order by a.id for update;
  perform 1 from public.newsroom_article_snapshots s where s.article_id in (
    select a.id from public.newsroom_articles a where a.id in (
      select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
    union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'sourceIds','[]'::jsonb)) x
      union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m where m.theme_id in (
        select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
        union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) x))
  ) order by s.id for share;
  perform 1 from public.newsroom_editorial_article_classifications c where c.newsroom_article_id in (
    select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
    union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'sourceIds','[]'::jsonb)) x
    union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m where m.theme_id in (
      select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
      union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) x)
  ) order by c.newsroom_article_id for share;
  perform 1 from public.editorial_articles a where a.id in (
    select m.editorial_article_id from public.newsroom_editorial_theme_articles m where m.theme_id in (
      select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare')
    union select (x #>> '{}')::uuid
      from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'reviewArticleIds','[]'::jsonb)) x
  ) order by a.id for share;
  select p.plan into strict v_preview from public.newsroom_mesa_preview_intents_v1(v_request) p;
  if v_preview ->> 'authorityFingerprint' is distinct from p_expected_authority_fingerprint then
    raise exception 'mesa-intent-authority-stale';
  end if;
  -- Incorporations and all workspaces/plans share THIS transaction. Any later
  -- exception rolls everything back; previewing the request never associates.
  for v_item in select value from jsonb_array_elements(v_preview -> 'incorporations') loop
    perform public.newsroom_set_editorial_theme_source_membership_v1((v_item ->> 'themeId')::uuid,(v_item ->> 'sourceId')::uuid,true);
  end loop;
  for v_context in select value from jsonb_array_elements(v_preview -> 'contexts') loop
    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object('kind',v_context -> 'kind',
      'themeId',v_context -> 'themeId','sourceId',v_context -> 'sourceId',
      'sources',(select jsonb_agg(jsonb_build_object('newsroomArticleId',s -> 'newsroomArticleId',
        'newsroomSnapshotId',s -> 'newsroomSnapshotId') order by s ->> 'newsroomArticleId') from jsonb_array_elements(v_context -> 'sources') s)));
  end loop;
  select * into strict v_result from public.newsroom_prepare_mesa_contexts_v3(v_key,v_request ->> 'title',v_contexts,null,'{}');
  for v_context in select value from jsonb_array_elements(v_preview -> 'contexts') loop
    select c.id into strict v_context_id from public.newsroom_mesa_production_context_items c
      where c.dossier_id = v_result.dossier_id and c.context_kind = v_context ->> 'kind'
        and c.theme_id is not distinct from (v_context ->> 'themeId')::uuid
        and c.source_newsroom_article_id is not distinct from (v_context ->> 'sourceId')::uuid;
    v_frozen_contexts := v_frozen_contexts || jsonb_build_array(v_context || jsonb_build_object('productionContextId',v_context_id));
  end loop;
  for v_item in select value from jsonb_array_elements(v_preview -> 'outputs') loop
    v_i := v_i + 1;
    select c into strict v_context from jsonb_array_elements(v_frozen_contexts) c where c ->> 'key' = v_item ->> 'contextKey';
    v_context_id := (v_context ->> 'productionContextId')::uuid;
    select array_agg(s.dossier_source_id order by s.sort_order) into v_ids
      from public.newsroom_mesa_production_context_sources s where s.dossier_id = v_result.dossier_id and s.production_context_id = v_context_id;
    select p.article_plan_id into strict v_plan_id from public.newsroom_save_mesa_context_article_plan_v1(
      v_result.dossier_id,null,left((v_item ->> 'slot') || ' — ' || coalesce(v_item -> 'target' ->> 'title','novo artigo'),180),
      'planned',v_i*10,'news','standard',case when v_item ->> 'kind' = 'existing' then 'Rever o artigo: UPDATE ou SEM ALTERAÇÃO.'
        else 'Produzir artigo novo apenas com as fontes deste contexto; não rever os artigos de referência.' end,v_ids,v_context_id) p;
    perform public.newsroom_save_dossier_article_plan_state_v1(v_result.dossier_id,v_plan_id,
      case when v_item ->> 'kind' = 'existing' then 'update' else 'new' end,
      (v_item -> 'target' ->> 'editorialArticleId')::uuid,'{}',
      case when v_item ->> 'kind' = 'existing' then 'preserve_published' else 'unselected' end,null);
    v_plan_ids := v_plan_ids || v_plan_id;
    v_outputs := v_outputs || jsonb_build_array(v_item || jsonb_build_object('outputId',v_plan_id,'productionContextId',v_context_id));
  end loop;
  perform public.newsroom_set_mesa_shared_outputs_v2(v_result.dossier_id,v_plan_ids);
  v_frozen := v_preview || jsonb_build_object('dossierId',v_result.dossier_id,'contexts',v_frozen_contexts,'outputs',v_outputs);
  insert into public.newsroom_mesa_intent_preparations(preparation_key,dossier_id,request,authority_fingerprint,captured_at,frozen_plan)
    values(v_key,v_result.dossier_id,v_request,p_expected_authority_fingerprint,(v_preview ->> 'capturedAt')::timestamptz,v_frozen);
  update public.newsroom_mesa_production_contexts set selection_payload = selection_payload || jsonb_build_object('productionIntents',v_frozen)
    where dossier_id = v_result.dossier_id;
  return query select jsonb_build_object('dossierId',v_result.dossier_id,'preparationAction','created','plan',v_frozen);
end;
$function$;
commit;

-- Article-centric receipt memory. Theme remains optional organization metadata.
-- Additive production migration: article-centric receipt memory; Theme remains optional organization metadata.
begin;

do $preflight$
begin
  if to_regclass('public.newsroom_mesa_intent_article_receipts') is null
    or to_regprocedure('public.newsroom_finalize_mesa_intents_v1(uuid,uuid,uuid[])') is null
  then raise exception 'mesa-article-continuity-v2-preflight-missing'; end if;
end;
$preflight$;

alter table public.newsroom_mesa_intent_article_receipts
  alter column theme_id drop not null,
  add column context_key text;

update public.newsroom_mesa_intent_article_receipts
set context_key='theme:'||theme_id::text
where context_key is null and theme_id is not null;

alter table public.newsroom_mesa_intent_article_receipts
  alter column context_key set not null,
  add constraint newsroom_mesa_intent_receipt_context_key_v2 check (
    context_key ~ '^(theme|source|selection):[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and (theme_id is null or context_key='theme:'||theme_id::text)
  );

create index newsroom_mesa_intent_receipt_article_global_v2
  on public.newsroom_mesa_intent_article_receipts(editorial_article_id,captured_at desc,dossier_id);

create or replace function public.newsroom_finalize_mesa_intents_v1(
  p_dossier_id uuid,p_package_id uuid,p_no_change_output_ids uuid[]
)
returns table(result jsonb) language plpgsql volatile security definer set search_path='' as $function$
declare
  v_plan jsonb; v_output jsonb; v_context jsonb; v_article jsonb; v_article_id uuid;
  v_written public.newsroom_mesa_output_publications%rowtype;
  v_final public.newsroom_mesa_intent_finalizations%rowtype;
  v_no_change uuid[]; v_receipts jsonb:='[]'; v_decisions jsonb:='[]';
  v_decision text; v_fingerprint text; v_event uuid; v_payload jsonb;
  v_updated integer:=0; v_new integer:=0; v_unchanged integer:=0;
  v_group record; v_version uuid; v_key text; v_completed timestamptz;
begin
  if p_dossier_id is null or p_package_id is null or p_no_change_output_ids is null
    or cardinality(p_no_change_output_ids)>30 or array_position(p_no_change_output_ids,null) is not null
    or (select count(distinct x) from unnest(p_no_change_output_ids) x)<>cardinality(p_no_change_output_ids) then
    raise exception 'mesa-intent-finalization-input-invalid';
  end if;
  select coalesce(array_agg(x order by x),'{}'::uuid[]) into v_no_change from unnest(p_no_change_output_ids) x;
  -- Completed replay is a historical fact, not a request to overwrite a later
  -- edit. Lock the same workspace as the writer before checking it.
  perform 1 from public.newsroom_mesa_production_contexts w where w.dossier_id=p_dossier_id for update;
  select * into v_final from public.newsroom_mesa_intent_finalizations f where f.dossier_id=p_dossier_id;
  if found then
    if v_final.package_id<>p_package_id or v_final.no_change_output_ids is distinct from v_no_change then
      raise exception 'mesa-intent-finalization-conflict';
    end if;
    return query select jsonb_build_object('action','reused','publicationEventId',v_final.publication_event_id,
      'updatedCount',v_final.updated_count,'newCount',v_final.new_count,'noChangeCount',v_final.no_change_count);
    return;
  end if;
  v_plan:=public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  if exists (select 1 from public.newsroom_mesa_production_contexts w
    where w.dossier_id=p_dossier_id and w.workspace_state<>'active') then
    raise exception 'mesa-intent-finalization-state-invalid';
  end if;
  if exists (select 1 from unnest(v_no_change) id where not exists (
      select 1 from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'outputId'=id::text and o ->> 'kind'='existing'))
    or exists (select 1 from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id and not exists (
      select 1 from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'outputId'=p.article_plan_id::text)) then
    raise exception 'mesa-intent-finalization-decision-invalid';
  end if;
  perform 1 from public.editorial_articles a where a.id in (
    select (o -> 'target' ->> 'editorialArticleId')::uuid from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'kind'='existing'
    union select p.editorial_article_id from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id
  ) order by a.id for update;
  for v_output in select value from jsonb_array_elements(v_plan -> 'outputs') loop
    select c into strict v_context from jsonb_array_elements(v_plan -> 'contexts') c where c ->> 'key'=v_output ->> 'contextKey';
    if (v_output ->> 'outputId')::uuid=any(v_no_change) then
      if exists (select 1 from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id and p.article_plan_id=(v_output ->> 'outputId')::uuid) then
        raise exception 'mesa-intent-no-change-already-published';
      end if;
      v_article_id:=(v_output -> 'target' ->> 'editorialArticleId')::uuid;
      select to_jsonb(a) into v_article from public.editorial_articles a where a.id=v_article_id and a.status='published';
      if not found or encode(sha256(convert_to(v_article::text,'UTF8')),'hex')
          is distinct from v_output -> 'target' ->> 'contentFingerprint' then
        raise exception 'mesa-intent-no-change-target-stale';
      end if;
      v_decision:='SEM_ALTERAÇÃO'; v_unchanged:=v_unchanged+1;
    else
      select * into v_written from public.newsroom_mesa_output_publications p
        where p.dossier_id=p_dossier_id and p.article_plan_id=(v_output ->> 'outputId')::uuid;
      if not found then raise exception 'mesa-intent-publication-incomplete'; end if;
      if v_written.package_id<>p_package_id or v_written.source_scope is distinct from 'context'
        or v_written.production_context_id is distinct from (v_context ->> 'productionContextId')::uuid
        or (v_output ->> 'kind'='existing' and v_written.editorial_article_id is distinct from (v_output -> 'target' ->> 'editorialArticleId')::uuid) then
        raise exception 'mesa-intent-publication-output-invalid';
      end if;
      v_article_id:=v_written.editorial_article_id;
      select to_jsonb(a) into v_article from public.editorial_articles a where a.id=v_article_id and a.status='published';
      if not found or encode(sha256(convert_to(v_article::text,'UTF8')),'hex') is distinct from v_written.payload ->> 'intentResultFingerprint' then
        raise exception 'mesa-intent-published-result-stale';
      end if;
      if not exists (
        select 1
        from public.newsroom_editorial_dossier_article_plans p
        where p.id=v_written.article_plan_id
          and p.dossier_id=p_dossier_id
          and (
            (
              v_output ->> 'kind'='existing'
              and p.destination='update'
              and p.update_target_editorial_article_id=v_article_id
              and (p.editorial_article_id is null or p.editorial_article_id=v_article_id)
            )
            or (
              v_output ->> 'kind'='new'
              and p.destination='new'
              and p.update_target_editorial_article_id is null
              and p.editorial_article_id=v_article_id
            )
          )
      ) then
        raise exception 'mesa-intent-publication-output-invalid';
      end if;
      v_decision:=case when v_output ->> 'kind'='existing' then 'UPDATE' else 'NEW' end;
      if v_decision='UPDATE' then v_updated:=v_updated+1; else v_new:=v_new+1; end if;
    end if;
    v_fingerprint:=encode(sha256(convert_to(v_article::text,'UTF8')),'hex');
    v_decisions:=v_decisions||jsonb_build_array(jsonb_build_object('slot',v_output -> 'slot',
      'outputId',v_output -> 'outputId','contextKey',v_output -> 'contextKey',
      'decision',v_decision,'articleId',v_article_id,'resultFingerprint',v_fingerprint));
    v_receipts:=v_receipts||jsonb_build_array(jsonb_build_object(
      'contextKey',v_context -> 'key','themeId',v_context -> 'themeId',
      'articleId',v_article_id,'outputId',v_output -> 'outputId','slot',v_output -> 'slot',
      'decision',v_decision,'sources',v_context -> 'sources','resultFingerprint',v_fingerprint));
  end loop;
  v_payload:=jsonb_build_object('contractVersion',1,'kind','mesa_production_intents',
    'packageId',p_package_id,'authorityFingerprint',v_plan -> 'authorityFingerprint',
    'capturedAt',v_plan -> 'capturedAt','decisions',v_decisions);
  insert into public.newsroom_mesa_publication_events(dossier_id,fingerprint,payload)
    values(p_dossier_id,md5(v_payload::text),v_payload) returning id into v_event;
  v_completed:=clock_timestamp();
  insert into public.newsroom_mesa_intent_finalizations(dossier_id,package_id,publication_event_id,
    no_change_output_ids,updated_count,new_count,no_change_count,completed_at)
    values(p_dossier_id,p_package_id,v_event,v_no_change,v_updated,v_new,v_unchanged,v_completed);
  insert into public.newsroom_mesa_intent_article_receipts(
    dossier_id,output_id,context_key,theme_id,editorial_article_id,
    slot,decision,captured_at,completed_at,sources,result_fingerprint
  )
    select p_dossier_id,(r ->> 'outputId')::uuid,r ->> 'contextKey',(r ->> 'themeId')::uuid,(r ->> 'articleId')::uuid,
      r ->> 'slot',r ->> 'decision',(v_plan ->> 'capturedAt')::timestamptz,v_completed,r -> 'sources',r ->> 'resultFingerprint'
    from jsonb_array_elements(v_receipts) r;
  -- Preserve technical material projection, but group by context as well as
  -- sources. Equal source sets in different Themes must never merge their work.
  for v_group in
    select x.production_context_id,x.source_refs,array_agg(x.article_id order by x.article_id) article_ids,
      min(x.article_plan_id::text)::uuid key_plan_id
    from (
      select p.production_context_id,u.article_plan_id,min(u.editorial_article_id::text)::uuid article_id,
        public.newsroom_mesa_normalize_refs_v2(jsonb_agg(jsonb_build_object(
          'newsroomArticleId',u.newsroom_article_id,'newsroomSnapshotId',u.newsroom_snapshot_id)
          order by u.newsroom_article_id,u.newsroom_snapshot_id)) source_refs
      from public.newsroom_mesa_output_source_usage u
      join public.newsroom_mesa_output_publications p on p.dossier_id=u.dossier_id and p.article_plan_id=u.article_plan_id
      where u.dossier_id=p_dossier_id group by p.production_context_id,u.article_plan_id having count(*)>=2
    ) x group by x.production_context_id,x.source_refs
  loop
    select c into strict v_context from jsonb_array_elements(v_plan -> 'contexts') c
      where c ->> 'productionContextId'=v_group.production_context_id::text;
    v_key:='output:'||v_group.key_plan_id::text;
    insert into public.newsroom_mesa_material_versions(material_key,title,source_refs,article_ids,production_dossier_id,publication_event_id)
      values(v_key,v_context ->> 'title',v_group.source_refs,v_group.article_ids,p_dossier_id,v_event) returning id into v_version;
    if v_context ->> 'themeId' is not null then
      insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
        values((v_context ->> 'themeId')::uuid,v_key,v_version) on conflict do nothing;
    end if;
  end loop;
  insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
    select (r ->> 'themeId')::uuid,(r ->> 'articleId')::uuid
    from jsonb_array_elements(v_receipts) r
    where r ->> 'themeId' is not null
    on conflict(theme_id,editorial_article_id) do nothing;
  update public.newsroom_mesa_production_contexts set workspace_state='consolidated',consolidated_at=v_completed where dossier_id=p_dossier_id;
  return query select jsonb_build_object('action','consolidated','publicationEventId',v_event,
    'updatedCount',v_updated,'newCount',v_new,'noChangeCount',v_unchanged);
end;
$function$;

create function public.newsroom_mesa_intent_latest_article_receipts_v2(p_article_ids uuid[])
returns table(receipts jsonb)
language plpgsql stable security definer set search_path='' as $function$
declare
  v_ids uuid[];
begin
  if p_article_ids is null or cardinality(p_article_ids) not between 1 and 30
    or array_position(p_article_ids,null) is not null
  then raise exception 'mesa-intent-article-receipts-input-invalid'; end if;
  select array_agg(distinct id order by id) into v_ids from unnest(p_article_ids) requested(id);
  if cardinality(v_ids)<>cardinality(p_article_ids) then
    raise exception 'mesa-intent-article-receipts-input-invalid';
  end if;

  return query
  select coalesce(jsonb_agg(jsonb_build_object(
    'contextKey',r.context_key,'themeId',r.theme_id,'articleId',r.editorial_article_id,
    'slot',r.slot,'decision',r.decision,
    'capturedAt',to_char(r.captured_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'sources',r.sources
  ) order by r.editorial_article_id,r.dossier_id,r.output_id),'[]'::jsonb)
  from (
    select x.*,rank() over(partition by x.editorial_article_id order by x.captured_at desc) capture_rank
    from public.newsroom_mesa_intent_article_receipts x
    where x.editorial_article_id=any(v_ids)
  ) r
  where r.capture_rank=1;
end;
$function$;
revoke all on function public.newsroom_mesa_intent_latest_article_receipts_v2(uuid[])
  from public,anon,authenticated,service_role;
grant execute on function public.newsroom_mesa_intent_latest_article_receipts_v2(uuid[])
  to service_role;

commit;

do $preflight$
begin
  if to_regprocedure('public.newsroom_prepare_mesa_intents_v1(jsonb,text)') is null
    or to_regprocedure('public.newsroom_prepare_mesa_intents_v1_context_v1(jsonb,text)') is not null
    or to_regclass('public.newsroom_mesa_intent_preparations') is null
  then
    raise exception 'mesa-output-focus-v1-preflight-missing';
  end if;
end;
$preflight$;

create function public.newsroom_mesa_intent_output_focus_source_ids_v1(
  p_context jsonb,
  p_request jsonb,
  p_output jsonb,
  p_outputs jsonb
)
returns uuid[]
language plpgsql
immutable
set search_path = ''
as $function$
declare
  v_all uuid[];
  v_explicit uuid[];
  v_theme_sources uuid[];
  v_selected_themes uuid[];
  v_evidence_sources uuid[];
  v_evidence_themes uuid[];
  v_selected uuid[];
  v_reviewed uuid[] := '{}'::uuid[];
  v_remaining uuid[];
  v_existing jsonb;
  v_existing_focus uuid[];
  v_touches_theme boolean := false;
  v_has_existing boolean := false;
begin
  select coalesce(
    array_agg(
      distinct lower(source ->> 'newsroomArticleId')::uuid
      order by lower(source ->> 'newsroomArticleId')::uuid
    ),
    '{}'::uuid[]
  )
  into v_all
  from jsonb_array_elements(coalesce(p_context -> 'sources', '[]'::jsonb)) source
  where source ->> 'newsroomArticleId'
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

  if cardinality(v_all) < 1
    or p_context ->> 'kind' <> 'selection'
    or jsonb_typeof(p_request -> 'selection') is distinct from 'object'
  then
    return null;
  end if;

  select coalesce(
    array_agg(
      distinct lower(value #>> '{}')::uuid
      order by lower(value #>> '{}')::uuid
    ),
    '{}'::uuid[]
  )
  into v_explicit
  from jsonb_array_elements(
    coalesce(p_request -> 'selection' -> 'sourceIds', '[]'::jsonb)
  )
  where value #>> '{}'
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

  select coalesce(
    array_agg(
      distinct lower(value #>> '{}')::uuid
      order by lower(value #>> '{}')::uuid
    ),
    '{}'::uuid[]
  )
  into v_selected_themes
  from jsonb_array_elements(
    coalesce(p_request -> 'selection' -> 'themeIds', '[]'::jsonb)
  )
  where value #>> '{}'
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

  select coalesce(array_agg(id order by id), '{}'::uuid[])
  into v_theme_sources
  from unnest(v_all) source(id)
  where not (source.id = any(v_explicit));

  if p_output ->> 'kind' = 'existing' then
    if jsonb_typeof(p_output -> 'target' -> 'evidence') is distinct from 'object' then
      return null;
    end if;

    select coalesce(array_agg(distinct id order by id), '{}'::uuid[])
    into v_evidence_sources
    from (
      select lower(value #>> '{}')::uuid as id
      from jsonb_array_elements(
        coalesce(p_output -> 'target' -> 'evidence' -> 'sourceIds', '[]'::jsonb)
      )
      where value #>> '{}'
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    ) evidence
    where evidence.id = any(v_all);

    if cardinality(v_selected_themes) = 1 then
      select coalesce(
        array_agg(
          distinct lower(value #>> '{}')::uuid
          order by lower(value #>> '{}')::uuid
        ),
        '{}'::uuid[]
      )
      into v_evidence_themes
      from jsonb_array_elements(
        coalesce(p_output -> 'target' -> 'evidence' -> 'themeIds', '[]'::jsonb)
      )
      where value #>> '{}'
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

      v_touches_theme :=
        v_selected_themes[1] = any(v_evidence_themes)
        or exists (
          select 1
          from unnest(v_evidence_sources) evidence_source(id)
          where evidence_source.id = any(v_theme_sources)
        );

      if v_touches_theme and cardinality(v_theme_sources) > 0 then
        select coalesce(array_agg(distinct id order by id), '{}'::uuid[])
        into v_selected
        from (
          select id from unnest(v_evidence_sources) source(id)
          union
          select id from unnest(v_theme_sources) source(id)
        ) selected;
        return v_selected;
      end if;
    end if;

    return case
      when cardinality(v_evidence_sources) > 0 then v_evidence_sources
      else null
    end;
  end if;

  if p_output ->> 'kind' = 'new' then
    if coalesce((p_context ->> 'newArticleCount')::integer, 0) <> 1 then
      return null;
    end if;

    for v_existing in
      select value
      from jsonb_array_elements(coalesce(p_outputs, '[]'::jsonb))
      where value ->> 'kind' = 'existing'
        and value ->> 'contextKey' = p_output ->> 'contextKey'
    loop
      v_has_existing := true;
      v_existing_focus := public.newsroom_mesa_intent_output_focus_source_ids_v1(
        p_context,
        p_request,
        v_existing,
        '[]'::jsonb
      );
      if v_existing_focus is null or cardinality(v_existing_focus) < 1 then
        return null;
      end if;
      v_reviewed := v_reviewed || v_existing_focus;
    end loop;

    if not v_has_existing then
      return null;
    end if;

    select coalesce(array_agg(distinct id order by id), '{}'::uuid[])
    into v_reviewed
    from unnest(v_reviewed) reviewed(id);

    select coalesce(array_agg(id order by id), '{}'::uuid[])
    into v_remaining
    from unnest(v_explicit) source(id)
    where source.id = any(v_all)
      and not (source.id = any(v_reviewed));

    return case
      when cardinality(v_remaining) > 0 then v_remaining
      else null
    end;
  end if;

  return null;
end;
$function$;

revoke all on function public.newsroom_mesa_intent_output_focus_source_ids_v1(jsonb,jsonb,jsonb,jsonb)
  from public,anon,authenticated,service_role;

-- Preserve the #339 preparation implementation. This wrapper only annotates
-- each frozen output with a deterministic focus when the evidence is sufficient.
alter function public.newsroom_prepare_mesa_intents_v1(jsonb,text)
  rename to newsroom_prepare_mesa_intents_v1_context_v1;

revoke all on function public.newsroom_prepare_mesa_intents_v1_context_v1(jsonb,text)
  from public,anon,authenticated,service_role;

create function public.newsroom_prepare_mesa_intents_v1(
  p_request jsonb,
  p_expected_authority_fingerprint text
)
returns table(result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_result jsonb;
  v_plan jsonb;
  v_outputs jsonb := '[]'::jsonb;
  v_output jsonb;
  v_context jsonb;
  v_focus_source_ids uuid[];
  v_dossier_id uuid;
begin
  select original.result
  into strict v_result
  from public.newsroom_prepare_mesa_intents_v1_context_v1(
    p_request,
    p_expected_authority_fingerprint
  ) original;

  v_plan := v_result -> 'plan';
  v_dossier_id := (v_plan ->> 'dossierId')::uuid;

  for v_output in
    select value
    from jsonb_array_elements(v_plan -> 'outputs')
  loop
    select value
    into strict v_context
    from jsonb_array_elements(v_plan -> 'contexts')
    where value ->> 'key' = v_output ->> 'contextKey';

    v_focus_source_ids := public.newsroom_mesa_intent_output_focus_source_ids_v1(
      v_context,
      v_plan -> 'request',
      v_output,
      v_plan -> 'outputs'
    );

    if v_focus_source_ids is not null and cardinality(v_focus_source_ids) > 0 then
      v_output := v_output || jsonb_build_object(
        'focusSourceIds',
        to_jsonb(v_focus_source_ids)
      );
    end if;

    v_outputs := v_outputs || jsonb_build_array(v_output);
  end loop;

  v_plan := jsonb_set(v_plan, '{outputs}', v_outputs);
  v_result := jsonb_set(v_result, '{plan}', v_plan);

  update public.newsroom_mesa_intent_preparations
  set frozen_plan = v_plan
  where dossier_id = v_dossier_id;

  update public.newsroom_mesa_production_contexts
  set selection_payload = jsonb_set(
    selection_payload,
    '{productionIntents}',
    v_plan,
    true
  )
  where dossier_id = v_dossier_id;

  return query select v_result;
end;
$function$;

revoke all on function public.newsroom_prepare_mesa_intents_v1(jsonb,text)
  from public,anon,authenticated,service_role;
grant execute on function public.newsroom_prepare_mesa_intents_v1(jsonb,text)
  to service_role;

begin;

create table if not exists jornada_private.newsroom_automatic_feed_tokens (
  token_hash text primary key,
  expires_at timestamptz not null,
  created_at timestamptz not null default pg_catalog.statement_timestamp()
);

revoke all
on table jornada_private.newsroom_automatic_feed_tokens
from public, anon, authenticated, service_role;

create or replace function public.newsroom_consume_automatic_feed_token_v1(
  p_token text
)
returns table (
  authorized boolean
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_hash text;
  v_deleted bigint := 0;
begin
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then
    return query select false;
    return;
  end if;

  v_hash := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(p_token, 'UTF8'), 'sha256'),
    'hex'
  );

  delete from jornada_private.newsroom_automatic_feed_tokens as token_row
  where token_row.token_hash = v_hash
    and token_row.expires_at >= pg_catalog.statement_timestamp();

  get diagnostics v_deleted = row_count;

  delete from jornada_private.newsroom_automatic_feed_tokens as token_row
  where token_row.expires_at < pg_catalog.statement_timestamp();

  return query select v_deleted = 1;
end;
$function$;

revoke all
on function public.newsroom_consume_automatic_feed_token_v1(text)
from public, anon, authenticated, service_role;

grant execute
on function public.newsroom_consume_automatic_feed_token_v1(text)
to service_role;

comment on function public.newsroom_consume_automatic_feed_token_v1(text)
is
  'Consome atomicamente um token efémero de uma só utilização para autorizar a recolha automática da Mesa.';

do $cron$
begin
  if exists (
    select 1
    from cron.job
    where jobname = 'jornada-newsroom-current-feed-quarter-hour'
  ) then
    perform cron.unschedule('jornada-newsroom-current-feed-quarter-hour');
  end if;

  perform cron.schedule(
    'jornada-newsroom-current-feed-quarter-hour',
    '*/15 * * * *',
    $job$
      with generated as (
        select pg_catalog.encode(extensions.gen_random_bytes(32), 'hex') as token
      ),
      stored as (
        insert into jornada_private.newsroom_automatic_feed_tokens (
          token_hash,
          expires_at
        )
        select
          pg_catalog.encode(
            extensions.digest(pg_catalog.convert_to(generated.token, 'UTF8'), 'sha256'),
            'hex'
          ),
          pg_catalog.statement_timestamp() + interval '5 minutes'
        from generated
        returning token_hash
      )
      select net.http_post(
        url := 'https://jornada.pt/api/cron/redacao-automatica/current-feed',
        headers := pg_catalog.jsonb_build_object(
          'Content-Type', 'application/json'
        ),
        body := pg_catalog.jsonb_build_object(
          'token',
          generated.token
        ),
        timeout_milliseconds := 240000
      ) as request_id
      from generated
      cross join stored;
    $job$
  );
end;
$cron$;

commit;

begin;

alter table public.newsroom_articles
  drop constraint newsroom_articles_manual_origin_urls_check,
  add constraint newsroom_articles_manual_origin_urls_check
    check (
      (
        source_code = 'manual_entry'
        and (
          (original_url is null and normalized_url is null)
          or
          (original_url is not null and normalized_url is not null)
        )
      )
      or (
        source_code <> 'manual_entry'
        and original_url is not null
        and normalized_url is not null
      )
    );

create function public.newsroom_create_manual_source(
  p_submission_id uuid,
  p_request_fingerprint text,
  p_title text,
  p_body jsonb,
  p_image_url text,
  p_published_date text,
  p_source_url text,
  p_source_page_title text,
  p_source_host text,
  p_content_hash text
)
returns table (
  submission_id uuid,
  request_fingerprint text,
  newsroom_article_id uuid,
  newsroom_snapshot_id uuid,
  entry_action text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request public.newsroom_manual_entry_requests%rowtype;
  v_article_id uuid;
  v_snapshot_id uuid;
  v_published_date date;
  v_published_at timestamptz;
  v_now timestamptz := pg_catalog.now();
  v_body_length integer;
  v_source_metadata jsonb;
begin
  if p_submission_id is null
     or p_request_fingerprint is null
     or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or p_title is null
     or btrim(p_title) = ''
     or length(btrim(p_title)) > 180
     or p_body is null
     or jsonb_typeof(p_body) <> 'array'
     or jsonb_array_length(p_body) = 0
     or p_image_url is null
     or btrim(p_image_url) = ''
     or length(p_image_url) > 2048
     or p_image_url !~* '^https?://[^[:space:]]+$'
     or p_image_url ~* '^https?://[^/?#]*@'
     or p_content_hash is null
     or p_content_hash !~ '^[0-9a-f]{64}$'
     or (
       p_published_date is not null
       and p_published_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     )
     or (
       p_source_url is not null
       and (
         btrim(p_source_url) = ''
         or length(p_source_url) > 4096
         or p_source_url !~* '^https?://[^[:space:]]+$'
         or p_source_url ~* '^https?://[^/?#]*@'
       )
     )
     or (p_source_page_title is not null and length(p_source_page_title) > 500)
     or (p_source_host is not null and length(p_source_host) > 255) then
    raise exception 'manual_source_input_invalid' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_body) body_item(value)
    where jsonb_typeof(body_item.value) is distinct from 'object'
      or jsonb_typeof(body_item.value -> 'type') is distinct from 'string'
      or (body_item.value ->> 'type') is distinct from 'paragraph'
      or jsonb_typeof(body_item.value -> 'text') is distinct from 'string'
      or nullif(btrim(coalesce(body_item.value ->> 'text', '')), '') is null
      or exists (
        select 1
        from jsonb_object_keys(
          case when jsonb_typeof(body_item.value) = 'object'
            then body_item.value else '{}'::jsonb end
        ) body_key(key)
        where body_key.key not in ('type', 'text')
      )
  ) then
    raise exception 'manual_source_body_invalid' using errcode = '22023';
  end if;

  select coalesce(sum(length(body_item.value ->> 'text')), 0)::integer
  into v_body_length
  from jsonb_array_elements(p_body) body_item(value);

  if v_body_length < 1 or v_body_length > 50000 then
    raise exception 'manual_source_body_invalid' using errcode = '22023';
  end if;

  if p_published_date is not null then
    begin
      v_published_date := p_published_date::date;
    exception
      when invalid_datetime_format or datetime_field_overflow then
        raise exception 'manual_source_published_date_invalid' using errcode = '22007';
    end;
    if to_char(v_published_date, 'YYYY-MM-DD') <> p_published_date
       or v_published_date > (v_now at time zone 'Europe/Lisbon')::date then
      raise exception 'manual_source_published_date_invalid' using errcode = '22007';
    end if;
    v_published_at := (p_published_date || 'T00:00:00.000Z')::timestamptz;
  end if;

  insert into public.newsroom_manual_entry_requests (
    submission_id,
    request_fingerprint
  ) values (
    p_submission_id,
    p_request_fingerprint
  )
  on conflict on constraint newsroom_manual_entry_requests_pkey do nothing;

  select request_row.*
  into v_request
  from public.newsroom_manual_entry_requests request_row
  where request_row.submission_id = p_submission_id
  for update;

  if not found then
    raise exception 'manual_source_request_unavailable' using errcode = '55000';
  end if;
  if v_request.request_fingerprint <> p_request_fingerprint then
    raise exception 'manual_source_payload_conflict' using errcode = 'P0001';
  end if;

  if v_request.newsroom_article_id is not null
     and v_request.newsroom_snapshot_id is not null then
    if not exists (
      select 1
      from public.newsroom_articles article
      join public.newsroom_article_snapshots snapshot
        on snapshot.id = v_request.newsroom_snapshot_id
       and snapshot.article_id = article.id
      where article.id = v_request.newsroom_article_id
        and article.source_code = 'manual_entry'
        and snapshot.content_hash = p_content_hash
        and snapshot.source_metadata ->> 'origin' = 'manual'
        and snapshot.source_metadata ->> 'manualSubmissionId' = p_submission_id::text
    ) then
      raise exception 'manual_source_request_inconsistent' using errcode = '55000';
    end if;

    return query
    select p_submission_id, p_request_fingerprint,
      v_request.newsroom_article_id, v_request.newsroom_snapshot_id,
      'reused'::text;
    return;
  end if;

  if v_request.newsroom_article_id is not null
     or v_request.newsroom_snapshot_id is not null then
    raise exception 'manual_source_request_incomplete' using errcode = '55000';
  end if;

  v_article_id := pg_catalog.gen_random_uuid();
  v_snapshot_id := pg_catalog.gen_random_uuid();
  v_source_metadata := jsonb_strip_nulls(jsonb_build_object(
    'origin', 'manual',
    'sourceCode', 'manual_entry',
    'sourceName', 'Entrada manual',
    'manualSubmissionId', p_submission_id::text,
    'title', btrim(p_title),
    'publishedAt', case when v_published_at is null then null else to_char(
      v_published_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    ) end,
    'publishedAtPrecision', case when v_published_at is null then null else 'date' end,
    'imageUrl', btrim(p_image_url),
    'sourceUrl', p_source_url,
    'sourcePageTitle', p_source_page_title,
    'sourceHost', p_source_host,
    'introducedAt', to_char(
      v_now at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    )
  ));

  insert into public.newsroom_articles (
    id, source_code, original_url, normalized_url, external_id,
    title, subtitle, summary, author, published_at, modified_at,
    detected_at, image_url, processing_status, first_detected_at,
    last_detected_at, created_at, updated_at
  ) values (
    v_article_id, 'manual_entry', p_source_url, p_source_url, null,
    btrim(p_title), null, null, null, v_published_at, null,
    v_now, btrim(p_image_url), 'ready_for_review', v_now,
    v_now, v_now, v_now
  );

  insert into public.newsroom_article_snapshots (
    id, article_id, content_hash, body, source_metadata, extracted_at, created_at
  ) values (
    v_snapshot_id, v_article_id, p_content_hash, p_body,
    v_source_metadata, v_now, v_now
  );

  update public.newsroom_manual_entry_requests request_row
  set newsroom_article_id = v_article_id,
      newsroom_snapshot_id = v_snapshot_id
  where request_row.submission_id = p_submission_id;

  return query
  select p_submission_id, p_request_fingerprint,
    v_article_id, v_snapshot_id, 'created'::text;
end;
$$;

revoke all on function public.newsroom_create_manual_source(
  uuid, text, text, jsonb, text, text, text, text, text, text
) from public, anon, authenticated, service_role;

grant execute on function public.newsroom_create_manual_source(
  uuid, text, text, jsonb, text, text, text, text, text, text
) to service_role;

comment on function public.newsroom_create_manual_source(
  uuid, text, text, jsonb, text, text, text, text, text, text
) is
  'Creates or idempotently reuses a simplified manual source for the newsroom desk; it does not create editorial copy or publish content.';

commit;

begin;

-- Allow a new physical zone, its block and its capacity-valid placements to
-- be persisted by the existing authoritative Apply statement. The v20 core
-- still validates the complete requested final state before its first DML and
-- retains the existing lock order, planner, downstream work and postconditions.

create or replace function
jornada_private.apply_matchday_live_layout_physical_workspace_v20_core(
  p_matchday_id uuid,
  p_profile_key text,
  p_expected_physical_state_token text,
  p_zones jsonb,
  p_blocks jsonb,
  p_placements jsonb,
  p_faixa_slot_count integer,
  p_explicit_bank_item_ids jsonb,
  p_displaced_bank_item_ids jsonb,
  p_worked_bank_item_ids jsonb,
  p_faixa_arrival_bank_item_ids jsonb,
  p_displaced_arrival_bank_item_ids jsonb,
  p_presentation jsonb
)
returns table (
  state_token text,
  applied_zone_count integer,
  applied_block_count integer,
  applied_placement_count integer,
  explicit_bank_item_count integer,
  displaced_bank_item_count integer,
  worked_bank_item_count integer
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_assignment_profile_key text;
  v_current_state_token text;
  v_final_state_token text;
  v_plan jsonb := '[]'::jsonb;
  v_faixa_before jsonb := '[]'::jsonb;
  v_blocks_before jsonb := '[]'::jsonb;
  v_classification_before text;
  v_faixa_anchor timestamptz;
  v_displaced_anchor timestamptz;
  v_block_offset integer := 1100000000;
  v_had_cutover boolean;
  v_had_settings boolean;
begin
  -- Envelope validation is read-only and precedes every lock and DML.
  if p_matchday_id is null
    or p_profile_key is null
    or pg_catalog.btrim(p_profile_key) = ''
    or p_expected_physical_state_token is null
    or pg_catalog.btrim(p_expected_physical_state_token) = ''
    or pg_catalog.btrim(p_expected_physical_state_token) !~
       '^[0-9a-f]{32}$'
    or p_zones is null
    or pg_catalog.jsonb_typeof(p_zones) <> 'array'
    or p_blocks is null
    or pg_catalog.jsonb_typeof(p_blocks) <> 'array'
    or p_placements is null
    or pg_catalog.jsonb_typeof(p_placements) <> 'array'
    or p_faixa_slot_count is null
    or p_faixa_slot_count < 0
    or p_explicit_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_explicit_bank_item_ids) <> 'array'
    or p_displaced_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_bank_item_ids) <> 'array'
    or p_worked_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_worked_bank_item_ids) <> 'array'
    or p_faixa_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_faixa_arrival_bank_item_ids) <> 'array'
    or p_displaced_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_arrival_bank_item_ids) <> 'array'
    or p_presentation is null
    or pg_catalog.jsonb_typeof(p_presentation) <> 'object'
  then
    raise exception 'matchday-live-layout-physical-v20-invalid-input';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zones) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 3
      or not raw_row.payload ?& array[
        'id', 'public_title', 'visual_family'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-shape-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_blocks) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 4
      or not raw_row.payload ?& array[
        'id', 'block_type', 'zone_id', 'sort_order'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-shape-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_placements) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 4
      or not raw_row.payload ?& array[
        'bank_item_id', 'placement_type', 'zone_id', 'slot_position'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-shape-invalid';
  end if;

  if not p_presentation ?& array[
    'headline_title_color',
    'latest_zone_placement',
    'latest_zone_title',
    'video_module_active'
  ] or (
    p_presentation - array[
      'headline_title_color',
      'latest_zone_placement',
      'latest_zone_title',
      'video_module_active'
    ]::text[]
  ) <> '{}'::jsonb
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'headline_title_color'
    ) not in ('null', 'string')
    or (
      pg_catalog.jsonb_typeof(
        p_presentation -> 'headline_title_color'
      ) = 'string'
      and pg_catalog.btrim(
        p_presentation ->> 'headline_title_color'
      ) !~ '^#[0-9A-Fa-f]{6}$'
    )
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'latest_zone_placement'
    ) <> 'string'
    or p_presentation ->> 'latest_zone_placement' not in (
      'top', 'four_news', 'hidden'
    )
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'latest_zone_title'
    ) <> 'string'
    or pg_catalog.char_length(
      pg_catalog.btrim(p_presentation ->> 'latest_zone_title')
    ) > 120
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'video_module_active'
    ) <> 'boolean'
  then
    raise exception 'matchday-live-layout-physical-v20-presentation-invalid';
  end if;

  if exists (
    select 1
    from (
      select p_explicit_bank_item_ids as payload
      union all select p_displaced_bank_item_ids
      union all select p_worked_bank_item_ids
      union all select p_faixa_arrival_bank_item_ids
      union all select p_displaced_arrival_bank_item_ids
    ) as list_row
    cross join lateral pg_catalog.jsonb_array_elements(list_row.payload)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or pg_catalog.btrim(raw_row.value #>> '{}') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception 'matchday-live-layout-physical-v20-bank-list-invalid';
  end if;

  -- Identical lock order to the existing physical writers.
  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-live-layout-physical-v20-matchday-not-found';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id = p_matchday_id
      and desk_row.is_managed = true
  ) then
    raise exception 'matchday-live-layout-physical-v20-matchday-not-live';
  end if;

  select assignment_row.profile_key
  into v_assignment_profile_key
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_matchday_id;

  if v_assignment_profile_key is distinct from p_profile_key then
    raise exception 'matchday-live-layout-physical-v20-profile-mismatch';
  end if;

  select token_row.state_token
  into v_current_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  if v_current_state_token is distinct from
     p_expected_physical_state_token
  then
    raise exception 'matchday-live-layout-physical-v20-concurrent-write';
  end if;

  select exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
  ) into v_had_cutover;

  select exists (
    select 1
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
  ) into v_had_settings;

  if v_had_cutover is distinct from v_had_settings then
    raise exception 'matchday-live-layout-physical-v20-authority-state-corrupt';
  end if;

  if v_had_cutover and exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
      and cutover_row.profile_key is distinct from p_profile_key
  ) then
    raise exception 'matchday-live-layout-physical-v20-cutover-profile-mismatch';
  end if;

  perform jornada_private.validate_matchday_live_layout_legacy_projection_v14(
    p_matchday_id,
    p_profile_key
  );

  -- Final zones may be empty, but every row has a real UUID, title and a
  -- centrally known layout. No classification field participates.
  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
    where zone_row.zone_id is null
      or zone_row.public_title is null
      or pg_catalog.char_length(zone_row.public_title) > 120
      or jornada_private.matchday_live_layout_layout_capacity_v20(
           zone_row.visual_family
         ) is null
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-value-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
  ) <> (
    select pg_catalog.count(distinct zone_row.zone_id)
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-duplicate';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as desired_row
    join public.matchday_live_layout_zones as current_row
      on current_row.id = desired_row.zone_id
    where current_row.matchday_id <> p_matchday_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-owned-by-other-matchday';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_id is null
      or block_row.block_type not in ('zone', 'latest', 'video')
      or block_row.sort_order is null
      or block_row.sort_order <= 0
      or block_row.sort_order > 1000000000
      or not (
        (block_row.block_type = 'zone' and block_row.zone_id is not null)
        or (
          block_row.block_type in ('latest', 'video')
          and block_row.zone_id is null
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-value-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
  ) <> (
    select pg_catalog.count(distinct block_row.block_id)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    group by block_row.sort_order
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-duplicate';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    join public.matchday_live_layout_blocks as current_row
      on current_row.id = desired_row.block_id
    where current_row.matchday_id <> p_matchday_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-owned-by-other-matchday';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    join public.matchday_live_layout_blocks as current_row
      on current_row.id = desired_row.block_id
     and current_row.matchday_id = p_matchday_id
    where current_row.block_type is distinct from desired_row.block_type
      or current_row.zone_id is distinct from desired_row.zone_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-identity-mismatch';
  end if;

  -- Retained zones retain their associated physical block identity. A new
  -- block is valid only for a new zone; deleting a zone deletes its old block.
  if exists (
    select 1
    from public.matchday_live_layout_blocks as current_block
    join public.matchday_live_layout_zones as current_zone
      on current_zone.id = current_block.zone_id
     and current_zone.matchday_id = current_block.matchday_id
    where current_block.matchday_id = p_matchday_id
      and current_block.block_type = 'zone'
      and exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as desired_zone
        where desired_zone.zone_id = current_zone.id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
          as desired_block
        where desired_block.block_id = current_block.id
          and desired_block.block_type = 'zone'
          and desired_block.zone_id = current_zone.id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-retained-zone-block-changed';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
    where (
      select pg_catalog.count(*)
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as block_row
      where block_row.block_type = 'zone'
        and block_row.zone_id = zone_row.zone_id
    ) <> 1
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'zone'
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as zone_row
        where zone_row.zone_id = block_row.zone_id
      )
  ) or (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'latest'
  ) <> 1 or (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'video'
  ) > 1 then
    raise exception 'matchday-live-layout-physical-v20-block-topology-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_placements) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload -> 'bank_item_id') <> 'string'
      or pg_catalog.btrim(raw_row.payload ->> 'bank_item_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or pg_catalog.jsonb_typeof(raw_row.payload -> 'placement_type') <>
         'string'
      or pg_catalog.lower(
           pg_catalog.btrim(raw_row.payload ->> 'placement_type')
         ) not in ('opening', 'faixa', 'selection', 'video_highlight', 'zone')
      or pg_catalog.jsonb_typeof(raw_row.payload -> 'slot_position') <>
         'number'
      or raw_row.payload ->> 'slot_position' !~ '^[0-9]+$'
      or (raw_row.payload ->> 'slot_position')::numeric > 2147483647
      or not (
        (
          pg_catalog.lower(
            pg_catalog.btrim(raw_row.payload ->> 'placement_type')
          ) = 'zone'
          and pg_catalog.jsonb_typeof(raw_row.payload -> 'zone_id') =
              'string'
          and pg_catalog.btrim(raw_row.payload ->> 'zone_id') ~*
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        )
        or (
          pg_catalog.lower(
            pg_catalog.btrim(raw_row.payload ->> 'placement_type')
          ) <> 'zone'
          and pg_catalog.jsonb_typeof(raw_row.payload -> 'zone_id') = 'null'
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-value-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    where placement_row.bank_item_id is null
      or placement_row.slot_position is null
      or placement_row.slot_position <= 0
      or not (
        (
          placement_row.placement_type = 'opening'
          and placement_row.zone_id is null
          and placement_row.slot_position between 1 and 5
        )
        or (
          placement_row.placement_type = 'faixa'
          and placement_row.zone_id is null
          and placement_row.slot_position <= p_faixa_slot_count
        )
        or (
          placement_row.placement_type = 'selection'
          and placement_row.zone_id is null
          and placement_row.slot_position between 1 and 4
        )
        or (
          placement_row.placement_type = 'video_highlight'
          and placement_row.zone_id is null
          and placement_row.slot_position = 1
        )
        or (
          placement_row.placement_type = 'zone'
          and placement_row.zone_id is not null
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-target-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    )
  ) <> (
    select pg_catalog.count(distinct placement_row.bank_item_id)
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    group by
      placement_row.placement_type,
      placement_row.zone_id,
      placement_row.slot_position
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-duplicate';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    left join jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
      on zone_row.zone_id = placement_row.zone_id
    where placement_row.placement_type = 'zone'
      and (
        zone_row.zone_id is null
        or placement_row.slot_position >
           jornada_private.matchday_live_layout_layout_capacity_v20(
             zone_row.visual_family
           )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-capacity-invalid';
  end if;


  if not (p_presentation ->> 'video_module_active')::boolean
    and exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
      where placement_row.placement_type = 'video_highlight'
    )
  then
    raise exception 'matchday-live-layout-physical-v20-video-state-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    where placement_row.placement_type = 'video_highlight'
  ) and not exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'video'
  ) then
    raise exception 'matchday-live-layout-physical-v20-video-block-missing';
  end if;

  if exists (
    select 1
    from (
      select p_explicit_bank_item_ids as payload
      union all select p_displaced_bank_item_ids
      union all select p_worked_bank_item_ids
      union all select p_faixa_arrival_bank_item_ids
      union all select p_displaced_arrival_bank_item_ids
    ) as list_row
    cross join lateral (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.count(distinct normalized_row.bank_item_id) as unique_count
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        list_row.payload
      ) as normalized_row
    ) as count_row
    where count_row.item_count <> count_row.unique_count
  ) then
    raise exception 'matchday-live-layout-physical-v20-bank-list-duplicate';
  end if;

  if exists (
    with requested as materialized (
      select placement_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_worked_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_faixa_arrival_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_arrival_bank_item_ids
      ) as list_row
    )
    select 1
    from requested as requested_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = requested_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
     and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) =
         'active'
    where bank_row.id is null
  ) then
    raise exception 'matchday-live-layout-physical-v20-bank-item-not-active';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = explicit_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) <>
          'editorial_article'
  ) then
    raise exception 'matchday-live-layout-physical-v20-explicit-bank-unsupported';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as state_row
    join jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
      on placement_row.bank_item_id = state_row.bank_item_id
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as state_row
    join jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
      on placement_row.bank_item_id = state_row.bank_item_id
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
      on displaced_row.bank_item_id = explicit_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-state-conflict';
  end if;

  -- General final-state completeness is retained from v14.
  if exists (
    select 1
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and (
        current_row.placement_type <> 'zone'
        or exists (
          select 1
          from jornada_private.normalize_matchday_live_layout_zones_v14(
            p_zones
          ) as retained_zone
          where retained_zone.zone_id = current_row.zone_id
        )
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
          p_placements
        ) as desired_row
        where desired_row.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_explicit_bank_item_ids
        ) as explicit_row
        where explicit_row.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_bank_item_ids
        ) as displaced_row
        where displaced_row.bank_item_id = current_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-removed-item-state-missing';
  end if;

  -- Deleted-zone items have a stricter server-side contract. If no final
  -- public destination exists they must be DESALOJADA, never explicit Bank.
  if exists (
    select 1
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and current_row.placement_type = 'zone'
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as desired_zone
        where desired_zone.zone_id = current_row.zone_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
          p_placements
        ) as desired_placement
        where desired_placement.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_bank_item_ids
        ) as displaced_row
        where displaced_row.bank_item_id = current_row.bank_item_id
      )
  ) then
    raise exception
      'matchday-live-layout-physical-v20-deleted-zone-items-not-displaced';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and current_row.placement_type = 'zone'
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as desired_zone
        where desired_zone.zone_id = current_row.zone_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
          p_placements
        ) as desired_placement
        where desired_placement.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = current_row.bank_item_id
          and memory_row.memory_kind = 'displaced'
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = current_row.bank_item_id
      )
  ) then
    raise exception
      'matchday-live-layout-physical-v20-deleted-zone-displaced-arrival-missing';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
      and bank_row.editorially_worked_at is not null
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_worked_bank_item_ids
        ) as worked_row
        where worked_row.bank_item_id = bank_row.id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-worked-regression';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as faixa_row
    join jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as displaced_row
      on displaced_row.bank_item_id = faixa_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-event-conflict';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as arrival_row
    where not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as desired_row
      where desired_row.bank_item_id = arrival_row.bank_item_id
        and desired_row.placement_type = 'faixa'
    )
      or exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = arrival_row.bank_item_id
          and current_row.placement_type = 'faixa'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-faixa-event-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as desired_row
    where desired_row.placement_type = 'faixa'
      and not exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = desired_row.bank_item_id
          and current_row.placement_type = 'faixa'
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_faixa_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = desired_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-faixa-event-incomplete';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as arrival_row
    where not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row
      where displaced_row.bank_item_id = arrival_row.bank_item_id
    )
      or exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = arrival_row.bank_item_id
          and memory_row.memory_kind = 'displaced'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-displaced-event-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    where not exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.bank_item_id = displaced_row.bank_item_id
        and memory_row.memory_kind = 'displaced'
    )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = displaced_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-displaced-event-incomplete';
  end if;

  -- Only data actually consumed by a legacy surface must satisfy its legacy
  -- identity requirements. Unmapped zones are never rejected here.
  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type in (
      'opening', 'faixa', 'video_highlight'
    )
      and nullif(pg_catalog.btrim(bank_row.link_url), '') is null
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type = 'selection'
      and (
        nullif(pg_catalog.btrim(bank_row.source_type), '') is null
        or nullif(pg_catalog.btrim(bank_row.source_id), '') is null
      )
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join jornada_private.matchday_live_layout_zone_legacy_projection
      as projection_row
      on projection_row.matchday_id = p_matchday_id
     and projection_row.zone_id = placement_row.zone_id
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type = 'zone'
      and (
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) <>
          'editorial_article'
        or nullif(pg_catalog.btrim(bank_row.source_id), '') is null
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-downstream-input-invalid';
  end if;

  -- Before-images used to preserve event clocks and block timestamps.
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'bank_item_id', placement_row.bank_item_id,
        'created_at', placement_row.created_at
      ) order by placement_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_faixa_before
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa';

  select coalesce(
    pg_catalog.jsonb_agg(pg_catalog.to_jsonb(block_row) order by block_row.id),
    '[]'::jsonb
  )
  into v_blocks_before
  from public.matchday_live_layout_blocks as block_row
  where block_row.matchday_id = p_matchday_id;

  select pg_catalog.md5(coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', bank_row.id,
        'automatic_eligible', bank_row.automatic_eligible,
        'classification_key', bank_row.classification_key,
        'classification_source', bank_row.classification_source,
        'classified_at', bank_row.classified_at
      ) order by bank_row.id
    ),
    '[]'::jsonb
  )::text)
  into v_classification_before
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = p_matchday_id;

  if exists (
    select 1
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
      and block_row.sort_order > 1000000000
  ) then
    raise exception
      'matchday-live-layout-physical-v20-current-block-order-invalid';
  end if;

  -- FIRST DML. Every topology, displacement and classification validation is
  -- complete; any later error rolls the whole function statement back.
  insert into jornada_private.matchday_live_layout_physical_cutovers (
    matchday_id,
    profile_key
  ) values (
    p_matchday_id,
    p_profile_key
  )
  on conflict (matchday_id) do nothing;

  insert into public.matchday_live_layout_workspace_settings as settings_row (
    matchday_id,
    faixa_slot_count,
    headline_title_color,
    latest_zone_placement,
    latest_zone_title,
    video_module_active
  ) values (
    p_matchday_id,
    p_faixa_slot_count,
    case
      when pg_catalog.jsonb_typeof(
        p_presentation -> 'headline_title_color'
      ) = 'null' then null
      else pg_catalog.upper(pg_catalog.btrim(
        p_presentation ->> 'headline_title_color'
      ))
    end,
    p_presentation ->> 'latest_zone_placement',
    pg_catalog.btrim(p_presentation ->> 'latest_zone_title'),
    (p_presentation ->> 'video_module_active')::boolean
  )
  on conflict (matchday_id) do update
  set faixa_slot_count = excluded.faixa_slot_count,
      headline_title_color = excluded.headline_title_color,
      latest_zone_placement = excluded.latest_zone_placement,
      latest_zone_title = excluded.latest_zone_title,
      video_module_active = excluded.video_module_active,
      updated_at = pg_catalog.statement_timestamp()
  where (
    settings_row.faixa_slot_count,
    settings_row.headline_title_color,
    settings_row.latest_zone_placement,
    settings_row.latest_zone_title,
    settings_row.video_module_active
  ) is distinct from (
    excluded.faixa_slot_count,
    excluded.headline_title_color,
    excluded.latest_zone_placement,
    excluded.latest_zone_title,
    excluded.video_module_active
  );

  insert into public.matchday_live_layout_zones (
    id,
    matchday_id,
    public_title,
    visual_family
  )
  select
    desired_row.zone_id,
    p_matchday_id,
    desired_row.public_title,
    desired_row.visual_family
  from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
    as desired_row
  where not exists (
    select 1
    from public.matchday_live_layout_zones as current_row
    where current_row.id = desired_row.zone_id
  )
  order by desired_row.zone_id;

  update public.matchday_live_layout_zones as zone_row
  set public_title = desired_row.public_title,
      visual_family = desired_row.visual_family,
      updated_at = pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
    as desired_row
  where zone_row.matchday_id = p_matchday_id
    and zone_row.id = desired_row.zone_id
    and (
      zone_row.public_title,
      zone_row.visual_family
    ) is distinct from (
      desired_row.public_title,
      desired_row.visual_family
    );

  -- Remove deleted-zone placements explicitly before their FK cascade. This
  -- makes displacement observable and keeps delete semantics independent of
  -- ON DELETE behavior.
  delete from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'zone'
    and not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
        as desired_zone
      where desired_zone.zone_id = placement_row.zone_id
    );

  -- All existing block rows first move into a collision-free range. Exact
  -- final orders are then assigned while original clocks remain available in
  -- v_blocks_before.
  if exists (
    with desired as materialized (
      select
        desired_row.block_id as id,
        desired_row.block_type,
        desired_row.zone_id,
        desired_row.sort_order
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as desired_row
    ),
    current_state as materialized (
      select block_row.id, block_row.block_type, block_row.zone_id,
             block_row.sort_order
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    update public.matchday_live_layout_blocks as block_row
    set sort_order = block_row.sort_order + v_block_offset
    where block_row.matchday_id = p_matchday_id;

    delete from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
          as desired_row
        where desired_row.block_id = block_row.id
      );

    insert into public.matchday_live_layout_blocks (
      id,
      matchday_id,
      block_type,
      zone_id,
      sort_order
    )
    select
      desired_row.block_id,
      p_matchday_id,
      desired_row.block_type,
      desired_row.zone_id,
      desired_row.sort_order
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    where not exists (
      select 1
      from public.matchday_live_layout_blocks as current_row
      where current_row.id = desired_row.block_id
    )
    order by desired_row.sort_order, desired_row.block_id;

    with previous as materialized (
      select previous_row.id, previous_row.sort_order
      from pg_catalog.jsonb_to_recordset(v_blocks_before) as previous_row(
        id uuid,
        matchday_id uuid,
        block_type text,
        zone_id uuid,
        sort_order integer,
        created_at timestamptz,
        updated_at timestamptz
      )
    )
    update public.matchday_live_layout_blocks as block_row
    set sort_order = desired_row.sort_order,
        updated_at = case
          when previous.sort_order is distinct from desired_row.sort_order
            then pg_catalog.statement_timestamp()
          else block_row.updated_at
        end
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    left join previous on previous.id = desired_row.block_id
    where block_row.matchday_id = p_matchday_id
      and block_row.id = desired_row.block_id;
  end if;

  delete from public.matchday_live_layout_zones as zone_row
  where zone_row.matchday_id = p_matchday_id
    and not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
        as desired_row
      where desired_row.zone_id = zone_row.id
    );

  perform jornada_private.begin_matchday_live_layout_downstream_v14(
    p_matchday_id
  );

  begin
    delete from public.matchday_editorial_profile_manual_overrides
      as override_row
    where override_row.matchday_id = p_matchday_id
      and override_row.profile_key = p_profile_key
      and (
        override_row.placement_target is distinct from 'bank'
        or not exists (
          select 1
          from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
            p_explicit_bank_item_ids
          ) as explicit_row
          join public.matchday_editorial_bank_items as bank_row
            on bank_row.id = explicit_row.bank_item_id
           and bank_row.matchday_id = p_matchday_id
          where pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
                pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
            and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
                pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
        )
      );

    update public.matchday_editorial_profile_manual_overrides as override_row
    set placement_target = 'bank',
        zone_key = null,
        sort_order = null,
        updated_at = pg_catalog.statement_timestamp()
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = explicit_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where override_row.matchday_id = p_matchday_id
      and override_row.profile_key = p_profile_key
      and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
          pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
      and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
          pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
      and (
        override_row.placement_target is distinct from 'bank'
        or override_row.zone_key is not null
        or override_row.sort_order is not null
      );

    insert into public.matchday_editorial_profile_manual_overrides (
      matchday_id,
      profile_key,
      source_type,
      source_id,
      placement_target,
      zone_key,
      sort_order
    )
    select
      p_matchday_id,
      p_profile_key,
      pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
      pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)),
      'bank',
      null,
      null
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = explicit_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where not exists (
      select 1
      from public.matchday_editorial_profile_manual_overrides as override_row
      where override_row.matchday_id = p_matchday_id
        and override_row.profile_key = p_profile_key
        and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
            pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
        and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
            pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
    )
    order by explicit_row.operation_order;

    with desired as materialized (
      select *
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      )
    ),
    clear_operations as (
      select
        0 as phase,
        current_row.placement_type,
        current_row.zone_id,
        current_row.slot_position,
        current_row.bank_item_id,
        pg_catalog.jsonb_build_object(
          'action', 'clear',
          'bank_item_id', null,
          'placement_type', current_row.placement_type,
          'zone_id', current_row.zone_id,
          'slot_position', current_row.slot_position
        ) as payload
      from public.matchday_live_layout_placements as current_row
      where current_row.matchday_id = p_matchday_id
        and not exists (
          select 1
          from desired as desired_row
          where desired_row.bank_item_id = current_row.bank_item_id
            and desired_row.placement_type = current_row.placement_type
            and desired_row.zone_id is not distinct from current_row.zone_id
            and desired_row.slot_position = current_row.slot_position
        )
        and not exists (
          select 1
          from desired as desired_row
          where desired_row.bank_item_id = current_row.bank_item_id
        )
        and not exists (
          select 1
          from desired as desired_row
          where desired_row.placement_type = current_row.placement_type
            and desired_row.zone_id is not distinct from current_row.zone_id
            and desired_row.slot_position = current_row.slot_position
        )
    ),
    place_operations as (
      select
        1 as phase,
        desired_row.placement_type,
        desired_row.zone_id,
        desired_row.slot_position,
        desired_row.bank_item_id,
        pg_catalog.jsonb_build_object(
          'action', 'place',
          'bank_item_id', desired_row.bank_item_id,
          'placement_type', desired_row.placement_type,
          'zone_id', desired_row.zone_id,
          'slot_position', desired_row.slot_position
        ) as payload
      from desired as desired_row
      where not exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = desired_row.bank_item_id
          and current_row.placement_type = desired_row.placement_type
          and current_row.zone_id is not distinct from desired_row.zone_id
          and current_row.slot_position = desired_row.slot_position
      )
    ),
    operations as (
      select * from clear_operations
      union all
      select * from place_operations
    )
    select coalesce(
      pg_catalog.jsonb_agg(
        operation_row.payload
        order by
          operation_row.phase,
          operation_row.placement_type,
          operation_row.zone_id nulls first,
          operation_row.slot_position,
          operation_row.bank_item_id
      ),
      '[]'::jsonb
    )
    into v_plan
    from operations as operation_row;

    perform jornada_private.apply_matchday_live_layout_placement_plan(
      p_matchday_id,
      v_plan,
      false
    );

    -- Re-entry into Faixa preserves its prior clock unless explicitly marked
    -- as a new arrival.
    with previous as materialized (
      select previous_row.bank_item_id, previous_row.created_at
      from pg_catalog.jsonb_to_recordset(v_faixa_before) as previous_row(
        bank_item_id uuid,
        created_at timestamptz
      )
    )
    update public.matchday_live_layout_placements as placement_row
    set created_at = previous.created_at
    from previous
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'faixa'
      and placement_row.bank_item_id = previous.bank_item_id
      and placement_row.created_at is distinct from previous.created_at
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_faixa_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = placement_row.bank_item_id
      );

    v_faixa_anchor := pg_catalog.clock_timestamp();

    update public.matchday_live_layout_placements as placement_row
    set created_at = v_faixa_anchor
        - ((arrival_row.operation_order - 1) * interval '1 microsecond')
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as arrival_row
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'faixa'
      and placement_row.bank_item_id = arrival_row.bank_item_id;

    delete from public.matchday_live_layout_bank_item_state_memory as memory_row
    where memory_row.matchday_id = p_matchday_id
      and (
        exists (
          select 1
          from public.matchday_live_layout_placements as placement_row
          where placement_row.matchday_id = p_matchday_id
            and placement_row.bank_item_id = memory_row.bank_item_id
        )
        or exists (
          select 1
          from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
            p_explicit_bank_item_ids
          ) as explicit_row
          where explicit_row.bank_item_id = memory_row.bank_item_id
        )
        or (
          memory_row.memory_kind = 'displaced'
          and not exists (
            select 1
            from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
              p_displaced_bank_item_ids
            ) as displaced_row
            where displaced_row.bank_item_id = memory_row.bank_item_id
          )
        )
      );

    insert into public.matchday_live_layout_bank_item_state_memory
      as memory_row (
        matchday_id,
        bank_item_id,
        memory_kind,
        recorded_at
      )
    select
      p_matchday_id,
      displaced_row.bank_item_id,
      'displaced',
      pg_catalog.statement_timestamp()
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    on conflict (matchday_id, bank_item_id)
    do update
    set memory_kind = 'displaced',
        recorded_at = excluded.recorded_at
    where memory_row.memory_kind is distinct from 'displaced';

    v_displaced_anchor := pg_catalog.clock_timestamp();

    update public.matchday_live_layout_bank_item_state_memory as memory_row
    set memory_kind = 'displaced',
        recorded_at = v_displaced_anchor
          - ((arrival_row.operation_order - 1) * interval '1 microsecond')
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as arrival_row
    where memory_row.matchday_id = p_matchday_id
      and memory_row.bank_item_id = arrival_row.bank_item_id;

    update public.matchday_editorial_bank_items as bank_row
    set editorially_worked_at = pg_catalog.statement_timestamp()
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_worked_bank_item_ids
    ) as worked_row
    where bank_row.matchday_id = p_matchday_id
      and bank_row.id = worked_row.bank_item_id
      and bank_row.editorially_worked_at is null;

    perform
      jornada_private.project_matchday_live_layout_workspace_best_effort_v20(
        p_matchday_id,
        p_profile_key
      );
  exception when others then
    perform jornada_private.end_matchday_live_layout_downstream_v14(
      p_matchday_id
    );
    raise;
  end;

  perform jornada_private.end_matchday_live_layout_downstream_v14(
    p_matchday_id
  );

  -- Exact physical postconditions. Empty zones and missing slot positions are
  -- valid occupancy, so only persisted rows participate.
  if exists (
    with desired as materialized (
      select desired_row.zone_id as id, desired_row.public_title,
             desired_row.visual_family
      from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
        as desired_row
    ),
    current_state as materialized (
      select zone_row.id, zone_row.public_title, zone_row.visual_family
      from public.matchday_live_layout_zones as zone_row
      where zone_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select desired_row.block_id as id, desired_row.block_type,
             desired_row.zone_id, desired_row.sort_order
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as desired_row
    ),
    current_state as materialized (
      select block_row.id, block_row.block_type, block_row.zone_id,
             block_row.sort_order
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select placement_row.bank_item_id, placement_row.placement_type,
             placement_row.zone_id, placement_row.slot_position
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
    ),
    current_state as materialized (
      select placement_row.bank_item_id, placement_row.placement_type,
             placement_row.zone_id, placement_row.slot_position
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-postcondition';
  end if;

  if not exists (
    select 1
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
      and settings_row.faixa_slot_count = p_faixa_slot_count
      and settings_row.headline_title_color is not distinct from case
        when pg_catalog.jsonb_typeof(
          p_presentation -> 'headline_title_color'
        ) = 'null' then null
        else pg_catalog.upper(pg_catalog.btrim(
          p_presentation ->> 'headline_title_color'
        ))
      end
      and settings_row.latest_zone_placement =
          p_presentation ->> 'latest_zone_placement'
      and settings_row.latest_zone_title =
          pg_catalog.btrim(p_presentation ->> 'latest_zone_title')
      and settings_row.video_module_active =
          (p_presentation ->> 'video_module_active')::boolean
  ) then
    raise exception 'matchday-live-layout-physical-v20-settings-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select displaced_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row
    ),
    current_state as materialized (
      select memory_row.bank_item_id
      from public.matchday_live_layout_bank_item_state_memory as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.memory_kind = 'displaced'
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-displaced-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select explicit_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as explicit_row
    ),
    current_state as materialized (
      select bank_row.id as bank_item_id
      from public.matchday_editorial_profile_manual_overrides as override_row
      join public.matchday_editorial_bank_items as bank_row
        on bank_row.matchday_id = p_matchday_id
       and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) =
           pg_catalog.lower(pg_catalog.btrim(override_row.source_type))
       and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) =
           pg_catalog.lower(pg_catalog.btrim(override_row.source_id))
      where override_row.matchday_id = p_matchday_id
        and override_row.profile_key = p_profile_key
        and override_row.placement_target = 'bank'
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-bank-postcondition';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    left join public.matchday_live_layout_zones as zone_row
      on zone_row.id = placement_row.zone_id
     and zone_row.matchday_id = placement_row.matchday_id
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'zone'
      and (
        zone_row.id is null
        or placement_row.slot_position >
           jornada_private.matchday_live_layout_layout_capacity_v20(
             zone_row.visual_family
           )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-capacity-postcondition';
  end if;

  if v_classification_before is distinct from (
    select pg_catalog.md5(coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', bank_row.id,
          'automatic_eligible', bank_row.automatic_eligible,
          'classification_key', bank_row.classification_key,
          'classification_source', bank_row.classification_source,
          'classified_at', bank_row.classified_at
        ) order by bank_row.id
      ),
      '[]'::jsonb
    )::text)
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-classification-changed';
  end if;

  perform jornada_private.assert_matchday_live_layout_downstream_v14(
    p_matchday_id,
    p_profile_key
  );

  perform
    jornada_private.assert_matchday_live_layout_physical_topology_source_v17(
      p_matchday_id,
      p_profile_key
    );

  select token_row.state_token
  into v_final_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  return query
  select
    v_final_state_token,
    pg_catalog.jsonb_array_length(p_zones),
    pg_catalog.jsonb_array_length(p_blocks),
    pg_catalog.jsonb_array_length(p_placements),
    pg_catalog.jsonb_array_length(p_explicit_bank_item_ids),
    pg_catalog.jsonb_array_length(p_displaced_bank_item_ids),
    pg_catalog.jsonb_array_length(p_worked_bank_item_ids);
end;
$function$;

comment on function
  jornada_private.apply_matchday_live_layout_physical_workspace_v20_core(
    uuid,text,text,jsonb,jsonb,jsonb,integer,
    jsonb,jsonb,jsonb,jsonb,jsonb,jsonb
  )
is
  'Atomic physical workspace core: a new zone, its physical block and capacity-valid placements may be committed by one authoritative Apply.';

commit;

