  p_classification_key text
)
returns table(
  editorial_article_id uuid,
  article_slug text,
  publication_action text,
  consolidated boolean
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  v_result record;
  v_frozen_classification_key text;
begin
  if p_classification_key is null
    or p_classification_key not in (
      'benfica',
      'sporting',
      'fc_porto',
