  loop
    v_oid := pg_catalog.to_regprocedure(v_signature);
    if v_oid is null then
      raise exception 'six-news-1-2-3: missing function %', v_signature;
    end if;
    v_definition := pg_catalog.pg_get_functiondef(v_oid);
