      'when[[:space:]]+''six_news''[[:space:]]+then[[:space:]]+6',
      'when ''six_news'' then 6 when ''six_news_1_2_3'' then 6', 'gi');
    if v_updated = v_definition then
      raise exception 'six-news-1-2-3: no family validation found in %', v_signature;
    end if;
    execute v_updated;
  end loop;
end;
